const QUIZ_QUESTIONS = [{"id":2001,"day":1,"category":"acts1","difficulty":"easy","question":"Who is Luke writing this account to?","options":["Thomas","Theophilus","Titus","Timothy"],"correct":1,"reference":"Acts 1:1","explanation":"Luke begins by addressing Theophilus — the same man he wrote the Gospel of Luke to. Think 'Theo-FILE-us': Luke is sending him a second file!"},{"id":2002,"day":1,"category":"acts1","difficulty":"medium","question":"For how many days did Jesus present Himself alive to the apostles after His suffering?","options":["Fifty days","Three days","Seven days","Forty days"],"correct":3,"reference":"Acts 1:3","explanation":"Jesus appeared to them for forty days by many infallible proofs, speaking about the kingdom of God. Forty is a number to watch all through Acts."},{"id":2003,"day":1,"category":"acts1","difficulty":"easy","question":"Which city did Jesus command the apostles not to depart from?","options":["Nazareth","Jerusalem","Bethlehem","Damascus"],"correct":1,"reference":"Acts 1:4","explanation":"They had to wait in Jerusalem for the Promise of the Father — the Holy Spirit."},{"id":2004,"day":1,"category":"acts1","difficulty":"medium","question":"Complete the verse: 'For John truly baptized with water, but you shall be baptized with the ___.'","options":["word of God","Spirit of truth","Holy Spirit","fire of heaven"],"correct":2,"reference":"Acts 1:5","explanation":"John's baptism was with water; the disciples would be baptized with the Holy Spirit — which happens at Pentecost in chapter 2."},{"id":2005,"day":1,"category":"acts1","difficulty":"hard","question":"What are the four places Jesus said they would be witnesses, in order?","options":["Jerusalem, Samaria, Judea, the end of the earth","Jerusalem, Judea, Samaria, the end of the earth","Judea, Jerusalem, Samaria, Rome","Jerusalem, Galilee, Samaria, the end of the earth"],"correct":1,"reference":"Acts 1:8","explanation":"Jerusalem, Judea, Samaria, the end of the earth. This verse is the map of the whole book of Acts — the story moves outward in exactly that order."},{"id":2006,"day":2,"category":"acts1","difficulty":"easy","question":"What received Jesus out of the sight of the disciples?","options":["A strong wind","A cloud","A bright light","A chariot"],"correct":1,"reference":"Acts 1:9","explanation":"As they watched, He was taken up and a cloud received Him out of their sight."},{"id":2007,"day":2,"category":"acts1","difficulty":"medium","question":"How many men in white apparel stood by the disciples?","options":["Twelve","Three","One","Two"],"correct":3,"reference":"Acts 1:10","explanation":"Two men in white apparel appeared and asked the men of Galilee why they stood gazing up into heaven."},{"id":2008,"day":2,"category":"acts1","difficulty":"medium","question":"From which mount did the disciples return to Jerusalem?","options":["Sinai","Carmel","Olivet","Golgotha"],"correct":2,"reference":"Acts 1:12","explanation":"They returned from the mount called Olivet, which is a Sabbath day's journey from Jerusalem."},{"id":2009,"day":2,"category":"acts1","difficulty":"hard","question":"How far was Mount Olivet from Jerusalem?","options":["Three miles","A day's walk","An hour's journey","A Sabbath day's journey"],"correct":3,"reference":"Acts 1:12","explanation":"Luke measures it as 'a Sabbath day's journey' — a short distance a person was permitted to travel on the Sabbath."},{"id":2010,"day":2,"category":"acts1","difficulty":"medium","question":"Who was NOT listed among those in the upper room?","options":["Matthew","Martha","Thomas","Andrew"],"correct":1,"reference":"Acts 1:13","explanation":"The list names Peter, James, John, Andrew, Philip, Thomas, Bartholomew, Matthew, James the son of Alphaeus, Simon the Zealot, and Judas the son of James. Martha is not in it."},{"id":2011,"day":3,"category":"acts1","difficulty":"medium","question":"About how many names were gathered together when Peter stood up?","options":["About a hundred and twenty","About five hundred","About three thousand","About seventy"],"correct":0,"reference":"Acts 1:15","explanation":"Altogether the number of names was about a hundred and twenty."},{"id":2012,"day":3,"category":"acts1","difficulty":"medium","question":"Through whose mouth did the Holy Spirit speak the Scripture about Judas?","options":["Isaiah","Joel","Moses","David"],"correct":3,"reference":"Acts 1:16","explanation":"Peter says the Holy Spirit spoke before by the mouth of David concerning Judas."},{"id":2013,"day":3,"category":"acts1","difficulty":"easy","question":"What did Judas purchase with the wages of iniquity?","options":["A tomb","A house","A field","A vineyard"],"correct":2,"reference":"Acts 1:18","explanation":"He purchased a field with the wages of iniquity."},{"id":2014,"day":3,"category":"acts1","difficulty":"hard","question":"What was the field called in their own language, and what does it mean?","options":["Golgotha — Place of a Skull","Gethsemane — Field of Oil","Akel Dama — Field of Bones","Akel Dama — Field of Blood"],"correct":3,"reference":"Acts 1:19","explanation":"It was called Akel Dama, that is, Field of Blood. Say it as 'Ah-kel Dama' and remember the grim meaning — it is often asked."},{"id":2015,"day":3,"category":"acts1","difficulty":"medium","question":"Which book of Scripture did Peter quote about Judas's place and office?","options":["The Book of Isaiah","The Book of Psalms","The Book of Joel","The Book of Proverbs"],"correct":1,"reference":"Acts 1:20","explanation":"Peter says, 'For it is written in the Book of Psalms.'"},{"id":2016,"day":4,"category":"acts1","difficulty":"medium","question":"The replacement apostle had to be a witness of what?","options":["His resurrection","His baptism only","His miracles","His birth"],"correct":0,"reference":"Acts 1:22","explanation":"One of these must become a witness with us of His resurrection — that was the qualification."},{"id":2017,"day":4,"category":"acts1","difficulty":"hard","question":"Whose baptism marked the starting point of the time the candidate must have accompanied them?","options":["Jesus' baptism of the Spirit","Peter's baptism","John's baptism","Philip's baptism"],"correct":2,"reference":"Acts 1:22","explanation":"'Beginning from the baptism of John to that day when He was taken up from us.'"},{"id":2018,"day":4,"category":"acts1","difficulty":"medium","question":"Which two men did they propose?","options":["Joseph called Barsabas, and Matthias","Joseph and Justus","Matthias and Stephen","Barsabas and Barnabas"],"correct":0,"reference":"Acts 1:23","explanation":"They proposed Joseph called Barsabas (surnamed Justus) and Matthias. Careful — Joseph, Barsabas and Justus are all names for the SAME man."},{"id":2019,"day":4,"category":"acts1","difficulty":"easy","question":"What did the disciples do before choosing between the two men?","options":["They fasted for a week","They drew straws in silence","They went fishing","They prayed"],"correct":3,"reference":"Acts 1:24","explanation":"They prayed, asking the Lord who knows the hearts of all to show which one He had chosen."},{"id":2020,"day":4,"category":"acts1","difficulty":"easy","question":"How was the choice finally made, and who was chosen?","options":["They cast lots, and the lot fell on Matthias","Peter decided, and chose Matthias","They voted, and chose Barsabas","They cast lots, and the lot fell on Justus"],"correct":0,"reference":"Acts 1:26","explanation":"They cast their lots and the lot fell on Matthias, and he was numbered with the eleven apostles. Remember: 'Matthias Made it.'"},{"id":2021,"day":5,"category":"acts2","difficulty":"easy","question":"On what day had the believers gathered when the Holy Spirit came?","options":["The Feast of Tabernacles","The Passover","The Day of Pentecost","The Day of Atonement"],"correct":2,"reference":"Acts 2:1","explanation":"When the Day of Pentecost had fully come, they were all with one accord in one place."},{"id":2022,"day":5,"category":"acts2","difficulty":"medium","question":"Complete the verse: 'They were all with one ___ in one ___.'","options":["mind / room","heart / house","accord / place","voice / temple"],"correct":2,"reference":"Acts 2:1","explanation":"'With one accord in one place' — unity came before the power."},{"id":2023,"day":5,"category":"acts2","difficulty":"medium","question":"Where did the sound come from?","options":["Heaven","The wind outside","The temple","The people"],"correct":0,"reference":"Acts 2:2","explanation":"Suddenly there came a sound from heaven, as of a rushing mighty wind, and it filled the whole house."},{"id":2024,"day":5,"category":"acts2","difficulty":"medium","question":"What appeared to them, and what did it look like?","options":["Doves of light","A pillar of smoke","A bright cloud","Divided tongues, as of fire"],"correct":3,"reference":"Acts 2:3","explanation":"Divided tongues, as of fire, appeared and one sat upon each of them."},{"id":2025,"day":5,"category":"acts2","difficulty":"easy","question":"What did they begin to speak with?","options":["Other tongues","Bold words","Loud voices","New songs"],"correct":0,"reference":"Acts 2:4","explanation":"They were all filled with the Holy Spirit and began to speak with other tongues, as the Spirit gave them utterance."},{"id":2026,"day":6,"category":"acts2","difficulty":"medium","question":"Who was dwelling in Jerusalem at that time?","options":["Priests and scribes only","Roman soldiers and traders","Jews, devout men, from every nation under heaven","Only Galileans"],"correct":2,"reference":"Acts 2:5","explanation":"Devout Jewish men from every nation under heaven were in Jerusalem — which is why so many languages were heard."},{"id":2027,"day":6,"category":"acts2","difficulty":"easy","question":"What language did each person in the crowd hear?","options":["His own language","Greek","Hebrew","Latin"],"correct":0,"reference":"Acts 2:6","explanation":"Everyone heard them speak in his own language — that is what confused and amazed the crowd."},{"id":2028,"day":6,"category":"acts2","difficulty":"medium","question":"The crowd was amazed because the speakers were all from which region?","options":["Judea","Galilee","Cappadocia","Samaria"],"correct":1,"reference":"Acts 2:7","explanation":"'Look, are not all these who speak Galileans?' Galileans were not expected to know all those languages."},{"id":2029,"day":6,"category":"acts2","difficulty":"hard","question":"Which of these places was NOT in the list of nations?","options":["Pamphylia","Phrygia","Cappadocia","Nineveh"],"correct":3,"reference":"Acts 2:9-10","explanation":"The list names Parthians, Medes, Elamites, Mesopotamia, Judea, Cappadocia, Pontus, Asia, Phrygia, Pamphylia, Egypt, Libya near Cyrene, Rome, Cretans and Arabs. Nineveh is not there. Learn to recognize the list, not recite it."},{"id":2030,"day":6,"category":"acts2","difficulty":"easy","question":"What did the mockers say the believers were full of?","options":["Evil spirits","Strong drink","New wine","Foolish talk"],"correct":2,"reference":"Acts 2:13","explanation":"Others mocking said, 'They are full of new wine.' Peter answers that mockery in the very next verse."},{"id":2031,"day":7,"category":"acts2","difficulty":"medium","question":"Who stood up with Peter when he raised his voice to the crowd?","options":["John alone","The eleven","The twelve","The seven"],"correct":1,"reference":"Acts 2:14","explanation":"Peter stood up with the eleven — Matthias had now been added, so Peter plus eleven others."},{"id":2032,"day":7,"category":"acts2","difficulty":"medium","question":"What hour of the day did Peter say it was?","options":["The third hour","The sixth hour","The ninth hour","The eleventh hour"],"correct":0,"reference":"Acts 2:15","explanation":"'It is only the third hour of the day' — about 9 in the morning, far too early for anyone to be drunk."},{"id":2033,"day":7,"category":"acts2","difficulty":"easy","question":"Which prophet did Peter quote?","options":["Jeremiah","Joel","Amos","Isaiah"],"correct":1,"reference":"Acts 2:16","explanation":"'But this is what was spoken by the prophet Joel.' Remember: Peter quotes J for Joel."},{"id":2034,"day":7,"category":"acts2","difficulty":"hard","question":"According to the prophecy, what would the old men do?","options":["Prophesy","See visions","Speak in tongues","Dream dreams"],"correct":3,"reference":"Acts 2:17","explanation":"Sons and daughters shall prophesy, young men shall see visions, old men shall dream dreams. Young = visions, old = dreams."},{"id":2035,"day":7,"category":"acts2","difficulty":"medium","question":"Complete the prophecy: 'Whoever calls on the name of the LORD shall be ___.'","options":["blessed","forgiven","saved","healed"],"correct":2,"reference":"Acts 2:21","explanation":"'Whoever calls on the name of the LORD shall be saved.' This is the closing line of Peter's Joel quotation."},{"id":2036,"day":8,"category":"acts2","difficulty":"medium","question":"How did Peter describe Jesus of Nazareth to the men of Israel?","options":["A Man attested by God by miracles, wonders, and signs","The son of David only","A teacher sent from heaven","A prophet like Moses"],"correct":0,"reference":"Acts 2:22","explanation":"Jesus was 'attested by God to you by miracles, wonders, and signs which God did through Him in your midst.'"},{"id":2037,"day":8,"category":"acts2","difficulty":"hard","question":"By what was Jesus delivered up, according to Peter?","options":["The determined purpose and foreknowledge of God","The betrayal of Judas alone","The jealousy of the rulers","The command of Pilate"],"correct":0,"reference":"Acts 2:23","explanation":"'Being delivered by the determined purpose and foreknowledge of God' — it was not an accident."},{"id":2038,"day":8,"category":"acts2","difficulty":"medium","question":"What did God loose when He raised Jesus up?","options":["The gates of Hades","The pains of death","The bonds of sin","The chains of the grave"],"correct":1,"reference":"Acts 2:24","explanation":"'Whom God raised up, having loosed the pains of death, because it was not possible that He should be held by it.'"},{"id":2039,"day":8,"category":"acts2","difficulty":"medium","question":"Whose words did Peter quote in verses 25 to 28?","options":["Moses","Joel","Samuel","David"],"correct":3,"reference":"Acts 2:25","explanation":"'For David says concerning Him…' Peter moves from Joel to David in his sermon."},{"id":2040,"day":8,"category":"acts2","difficulty":"hard","question":"Complete the quotation: 'You will not allow Your Holy One to see ___.'","options":["death","corruption","sorrow","the grave"],"correct":1,"reference":"Acts 2:27","explanation":"'For You will not leave my soul in Hades, nor will You allow Your Holy One to see corruption.'"},{"id":2041,"day":9,"category":"acts2","difficulty":"medium","question":"What did Peter say about the patriarch David?","options":["He is both dead and buried, and his tomb is with us","He was taken up like Elijah","He is alive with the Lord","He ascended into the heavens"],"correct":0,"reference":"Acts 2:29","explanation":"David is dead and buried and his tomb is still there — so the psalm about not seeing corruption must be about someone else: Jesus."},{"id":2042,"day":9,"category":"acts2","difficulty":"hard","question":"Peter says David did NOT do what?","options":["Speak as a prophet","Ascend into the heavens","Write the Psalms","Sit on a throne"],"correct":1,"reference":"Acts 2:34","explanation":"'For David did not ascend into the heavens, but he says himself: The LORD said to my Lord…'"},{"id":2043,"day":9,"category":"acts2","difficulty":"medium","question":"God has made this Jesus, whom you crucified, both what?","options":["Prophet and Judge","Lord and Savior","Lord and Christ","King and Priest"],"correct":2,"reference":"Acts 2:36","explanation":"'God has made this Jesus, whom you crucified, both Lord and Christ.' That sentence is the climax of the whole sermon."},{"id":2044,"day":9,"category":"acts2","difficulty":"easy","question":"How did the crowd feel when they heard Peter's words?","options":["They were angry","They laughed","They walked away","They were cut to the heart"],"correct":3,"reference":"Acts 2:37","explanation":"They were cut to the heart and asked, 'Men and brethren, what shall we do?'"},{"id":2045,"day":9,"category":"acts2","difficulty":"medium","question":"What two things did Peter tell them to do?","options":["Pray and fast","Repent and be baptized","Give and serve","Believe and wait"],"correct":1,"reference":"Acts 2:38","explanation":"'Repent, and let every one of you be baptized in the name of Jesus Christ for the remission of sins; and you shall receive the gift of the Holy Spirit.'"},{"id":2046,"day":10,"category":"acts2","difficulty":"easy","question":"About how many souls were added that day?","options":["Ten thousand","One hundred and twenty","Five thousand","Three thousand"],"correct":3,"reference":"Acts 2:41","explanation":"About three thousand souls were added that day. Watch out — five thousand comes later, in Acts 4:4. Remember '3 then 5.'"},{"id":2047,"day":10,"category":"acts2","difficulty":"hard","question":"What four things did the new believers continue steadfastly in?","options":["Teaching, singing, giving, and prayers","Doctrine, fasting, fellowship, and prayers","The apostles' doctrine, fellowship, breaking of bread, and prayers","Prayer, praise, preaching, and giving"],"correct":2,"reference":"Acts 2:42","explanation":"Doctrine, Fellowship, Bread, Prayers — remember D-F-B-P: 'Don't Forget Bread and Prayer.'"},{"id":2048,"day":10,"category":"acts2","difficulty":"medium","question":"What came upon every soul?","options":["Peace","Boldness","Fear","Joy"],"correct":2,"reference":"Acts 2:43","explanation":"'Then fear came upon every soul, and many wonders and signs were done through the apostles.'"},{"id":2049,"day":10,"category":"acts2","difficulty":"medium","question":"How did the believers handle their possessions?","options":["They kept them and gave a tenth","They stored them for the famine","They gave them to the temple","They sold them and divided them as anyone had need"],"correct":3,"reference":"Acts 2:44-45","explanation":"They had all things in common, sold their possessions and goods, and divided them among all, as anyone had need."},{"id":2050,"day":10,"category":"acts2","difficulty":"medium","question":"Who added to the church daily those who were being saved?","options":["The Lord","The elders","The apostles","Peter"],"correct":0,"reference":"Acts 2:47","explanation":"'And the Lord added to the church daily those who were being saved.' The growth was God's work, not a clever plan."},{"id":2051,"day":11,"category":"acts3","difficulty":"medium","question":"At what hour did Peter and John go up to the temple to pray?","options":["The sixth hour","The first hour","The third hour","The ninth hour"],"correct":3,"reference":"Acts 3:1","explanation":"The ninth hour — about 3 in the afternoon, the hour of prayer. Compare with the third hour in Acts 2:15."},{"id":2052,"day":11,"category":"acts3","difficulty":"easy","question":"What was the name of the gate where the lame man was laid?","options":["Mercy","Golden","Beautiful","Sheep"],"correct":2,"reference":"Acts 3:2","explanation":"He was laid daily at the gate of the temple which is called Beautiful, to ask alms."},{"id":2053,"day":11,"category":"acts3","difficulty":"medium","question":"How long had the man been lame?","options":["From his mother's womb","Since childhood","Forty years","Eight years"],"correct":0,"reference":"Acts 3:2","explanation":"He was lame from his mother's womb — he had never walked. Note: he was LAME, not blind, which is a common trick question."},{"id":2054,"day":11,"category":"acts3","difficulty":"hard","question":"Complete Peter's words: 'Silver and gold I do not have, but ___.'","options":["the Lord will provide","what I do have I give you","God will bless you","take what you need"],"correct":1,"reference":"Acts 3:6","explanation":"'Silver and gold I do not have, but what I do have I give you: In the name of Jesus Christ of Nazareth, rise up and walk.' Learn this one word for word."},{"id":2055,"day":11,"category":"acts3","difficulty":"medium","question":"What three things did the healed man do as he entered the temple?","options":["Walking, leaping, and praising God","Leaping, weeping, and praising God","Running, shouting, and singing","Walking, dancing, and praying"],"correct":0,"reference":"Acts 3:8","explanation":"Walking, leaping, and praising God — in that order. Act it out and you will never forget it."},{"id":2056,"day":12,"category":"acts3","difficulty":"medium","question":"In which porch did all the people run together to Peter and John?","options":["The Beautiful Gate","The Court of the Gentiles","The King's Porch","Solomon's"],"correct":3,"reference":"Acts 3:11","explanation":"They ran together in the porch which is called Solomon's, greatly amazed."},{"id":2057,"day":12,"category":"acts3","difficulty":"medium","question":"Peter asked why they stared, as if by whose power the man was made to walk?","options":["The power of Moses","The power of the temple","Their own power or godliness","The power of the priests"],"correct":2,"reference":"Acts 3:12","explanation":"Peter immediately refuses the credit: it was not by their own power or godliness."},{"id":2058,"day":12,"category":"acts3","difficulty":"hard","question":"Whose God did Peter say glorified His Servant Jesus?","options":["The God of Israel and Judah","The God of Abraham, Isaac, and Jacob","The God of David and Solomon","The God of Moses and Aaron"],"correct":1,"reference":"Acts 3:13","explanation":"'The God of Abraham, Isaac, and Jacob, the God of our fathers, glorified His Servant Jesus.'"},{"id":2059,"day":12,"category":"acts3","difficulty":"hard","question":"What title did Peter give Jesus in verse 15?","options":["The Prince of life","The Son of Man","The Holy One","The Chief Cornerstone"],"correct":0,"reference":"Acts 3:15","explanation":"'And killed the Prince of life, whom God raised from the dead, of which we are witnesses.'"},{"id":2060,"day":12,"category":"acts3","difficulty":"medium","question":"Peter said they and their rulers had acted in what?","options":["Anger","Pride","Ignorance","Fear"],"correct":2,"reference":"Acts 3:17","explanation":"'Yet now, brethren, I know that you did it in ignorance, as did also your rulers.' Peter is stern but not cruel."},{"id":2061,"day":13,"category":"acts3","difficulty":"medium","question":"What did Peter say would happen to their sins if they repented and were converted?","options":["They would be remembered no more","They would be washed away","They would be covered","They would be blotted out"],"correct":3,"reference":"Acts 3:19","explanation":"'Repent therefore and be converted, that your sins may be blotted out, so that times of refreshing may come from the presence of the Lord.'"},{"id":2062,"day":13,"category":"acts3","difficulty":"hard","question":"What must heaven receive Jesus until?","options":["The times of restoration of all things","The end of the age","The times of refreshing","The day of judgment"],"correct":0,"reference":"Acts 3:21","explanation":"'Whom heaven must receive until the times of restoration of all things.'"},{"id":2063,"day":13,"category":"acts3","difficulty":"medium","question":"Which prophet said God would raise up a Prophet like himself?","options":["Elijah","Moses","Joel","Samuel"],"correct":1,"reference":"Acts 3:22","explanation":"'For Moses truly said to the fathers, The LORD your God will raise up for you a Prophet like me from your brethren.'"},{"id":2064,"day":13,"category":"acts3","difficulty":"hard","question":"Peter said all the prophets from whom onward had foretold these days?","options":["Samuel","David","Moses","Elijah"],"correct":0,"reference":"Acts 3:24","explanation":"'Yes, and all the prophets, from Samuel and those who follow, as many as have spoken, have also foretold these days.'"},{"id":2065,"day":13,"category":"acts3","difficulty":"medium","question":"Complete God's promise to Abraham: 'And in your seed all the ___ of the earth shall be blessed.'","options":["nations","kingdoms","families","peoples"],"correct":2,"reference":"Acts 3:25","explanation":"'And in your seed all the families of the earth shall be blessed.'"},{"id":2066,"day":14,"category":"acts4","difficulty":"medium","question":"Which three groups came upon Peter and John as they spoke?","options":["The Pharisees, the Sadducees, and the Herodians","The priests, the scribes, and the Pharisees","The elders, the scribes, and the Sadducees","The priests, the captain of the temple, and the Sadducees"],"correct":3,"reference":"Acts 4:1","explanation":"The priests, the captain of the temple, and the Sadducees. The Sadducees did not believe in resurrection, which is exactly what was being preached."},{"id":2067,"day":14,"category":"acts4","difficulty":"medium","question":"Why were they greatly disturbed?","options":["Because a crowd had gathered","Because the apostles preached in Jesus the resurrection from the dead","Because money was collected","Because the man was healed on the Sabbath"],"correct":1,"reference":"Acts 4:2","explanation":"They were disturbed that the apostles taught the people and preached in Jesus the resurrection from the dead."},{"id":2068,"day":14,"category":"acts4","difficulty":"medium","question":"Why did they keep Peter and John in custody until the next day?","options":["Because it was already evening","Because the crowd was too large","Because the high priest was ill","Because the council was away"],"correct":0,"reference":"Acts 4:3","explanation":"They laid hands on them and put them in custody until the next day, for it was already evening."},{"id":2069,"day":14,"category":"acts4","difficulty":"easy","question":"About how many men believed after hearing the word?","options":["One thousand","Three thousand","Five thousand","Twelve thousand"],"correct":2,"reference":"Acts 4:4","explanation":"The number of the men came to be about five thousand. Keep the pair straight: 3,000 in chapter 2, 5,000 in chapter 4."},{"id":2070,"day":14,"category":"acts4","difficulty":"hard","question":"True or False: the arrest stopped people from believing.","options":["False — but only a few believed","True — no one believed that day","False — many who heard the word believed","True — the crowd scattered"],"correct":2,"reference":"Acts 4:4","explanation":"The very opposite happened. Even as the apostles were arrested, about five thousand men believed."},{"id":2071,"day":15,"category":"acts4","difficulty":"hard","question":"Which four men are named as gathered with the rulers at Jerusalem?","options":["Annas, Caiaphas, Nicodemus, and John","Annas, Caiaphas, Gamaliel, and Alexander","Caiaphas, Pilate, John, and Annas","Annas, Caiaphas, John, and Alexander"],"correct":3,"reference":"Acts 4:6","explanation":"Annas the high priest, Caiaphas, John, and Alexander. Remember A-C-J-A."},{"id":2072,"day":15,"category":"acts4","difficulty":"medium","question":"What question did the rulers ask Peter and John?","options":["Why do you break the Sabbath?","By what power or by what name have you done this?","Who gave you permission to teach?","Where is the man who was healed?"],"correct":1,"reference":"Acts 4:7","explanation":"'By what power or by what name have you done this?' Peter's answer becomes one of the great verses of Acts."},{"id":2073,"day":15,"category":"acts4","difficulty":"medium","question":"Peter answered them filled with what?","options":["The Holy Spirit","Righteous anger","Wisdom from above","Great courage"],"correct":0,"reference":"Acts 4:8","explanation":"'Then Peter, filled with the Holy Spirit, said to them…' The Spirit is the one doing the work throughout Acts."},{"id":2074,"day":15,"category":"acts4","difficulty":"medium","question":"What did Peter call the stone which was rejected by the builders?","options":["The foundation stone","The living stone","The chief cornerstone","The stone of stumbling"],"correct":2,"reference":"Acts 4:11","explanation":"'This is the stone which was rejected by you builders, which has become the chief cornerstone.'"},{"id":2075,"day":15,"category":"acts4","difficulty":"hard","question":"Complete the verse: 'Nor is there salvation in any other, for there is no other ___ under heaven given among men by which we must be saved.'","options":["name","hope","power","way"],"correct":0,"reference":"Acts 4:12","explanation":"'There is no other NAME under heaven given among men by which we must be saved.' This is the memory verse for Week 3."},{"id":2076,"day":16,"category":"acts4","difficulty":"medium","question":"How did the council describe Peter and John?","options":["Galilean fishermen only","Dangerous rebels","Learned men of the law","Uneducated and untrained men"],"correct":3,"reference":"Acts 4:13","explanation":"They saw their boldness and perceived they were uneducated and untrained men — and they realized they had been with Jesus."},{"id":2077,"day":16,"category":"acts4","difficulty":"medium","question":"What did the rulers realize about Peter and John?","options":["That they were Galileans","That they had been with Jesus","That they were prophets","That they were priests"],"correct":1,"reference":"Acts 4:13","explanation":"Their boldness gave them away: 'they realized that they had been with Jesus.'"},{"id":2078,"day":16,"category":"acts4","difficulty":"medium","question":"Why could the council say nothing against the apostles?","options":["They had no witnesses","The crowd was too loud","Pilate had forbidden it","The healed man was standing with them"],"correct":3,"reference":"Acts 4:14","explanation":"Seeing the man who had been healed standing with them, they could say nothing against it. The evidence was on his feet."},{"id":2079,"day":16,"category":"acts4","difficulty":"hard","question":"Complete Peter and John's answer: 'For we cannot but speak the things which we have ___ and ___.'","options":["learned / believed","seen / heard","known / received","heard / believed"],"correct":1,"reference":"Acts 4:20","explanation":"'For we cannot but speak the things which we have seen and heard.' This is the Week 4 memory verse."},{"id":2080,"day":16,"category":"acts4","difficulty":"medium","question":"How old was the man on whom the miracle of healing had been performed?","options":["Over forty years old","Just a young man","Over sixty years old","About thirty years old"],"correct":0,"reference":"Acts 4:22","explanation":"The man was over forty years old — so everyone in Jerusalem had seen him begging for decades."},{"id":2081,"day":17,"category":"acts4","difficulty":"medium","question":"When released, who did Peter and John go to?","options":["The crowd at the temple","Their families","The high priest","Their own companions"],"correct":3,"reference":"Acts 4:23","explanation":"'And being let go, they went to their own companions and reported all that the chief priests and elders had said to them.'"},{"id":2082,"day":17,"category":"acts4","difficulty":"hard","question":"In their prayer, how did the believers describe God?","options":["Who sees all things","Who reigns forever and ever","Who made heaven and earth and the sea, and all that is in them","Who is mighty to save"],"correct":2,"reference":"Acts 4:24","explanation":"They began by praising God as the Maker of heaven, earth, sea, and all that is in them — before asking for anything."},{"id":2083,"day":17,"category":"acts4","difficulty":"hard","question":"Which two rulers are named as gathered together against Jesus?","options":["Annas and Caiaphas","Herod and Gamaliel","Pilate and Alexander","Herod and Pontius Pilate"],"correct":3,"reference":"Acts 4:27","explanation":"'Both Herod and Pontius Pilate, with the Gentiles and the people of Israel, were gathered together.'"},{"id":2084,"day":17,"category":"acts4","difficulty":"medium","question":"What did the believers actually ask God for?","options":["Boldness to speak His word","Protection from their enemies","Rest from persecution","Wisdom to answer the council"],"correct":0,"reference":"Acts 4:29","explanation":"They did not ask for safety — they asked for boldness. That is the heart of this prayer."},{"id":2085,"day":17,"category":"acts4","difficulty":"easy","question":"What happened when they had prayed?","options":["The place was shaken and they were filled with the Holy Spirit","An angel appeared","The doors opened","A light shone from heaven"],"correct":0,"reference":"Acts 4:31","explanation":"The place where they were assembled was shaken, they were all filled with the Holy Spirit, and they spoke the word of God with boldness — exactly what they asked for."},{"id":2086,"day":18,"category":"acts4","difficulty":"medium","question":"The multitude of those who believed were of what?","options":["One accord and one place","One faith and one hope","One mind and one voice","One heart and one soul"],"correct":3,"reference":"Acts 4:32","explanation":"'Now the multitude of those who believed were of one heart and one soul.'"},{"id":2087,"day":18,"category":"acts4","difficulty":"medium","question":"True or False: Great grace was upon Peter alone.","options":["False — grace was upon the apostles only","True — Peter alone had great grace","False — great grace was upon them all","True — on Peter and John"],"correct":2,"reference":"Acts 4:33","explanation":"'And great grace was upon them ALL' — not just on the leaders."},{"id":2088,"day":18,"category":"acts4","difficulty":"medium","question":"What did those who owned lands or houses do with the proceeds?","options":["Gave them to the temple","Divided them among their families","Kept a portion for themselves","Laid them at the apostles' feet"],"correct":3,"reference":"Acts 4:34-35","explanation":"They sold them, brought the proceeds, and laid them at the apostles' feet, and it was distributed to each as anyone had need."},{"id":2089,"day":18,"category":"acts4","difficulty":"hard","question":"What was Barnabas's other name, and what does 'Barnabas' mean?","options":["Joses — Son of Encouragement","Joses — Son of Thunder","Justus — Son of Consolation","Joseph — Son of Comfort"],"correct":0,"reference":"Acts 4:36","explanation":"He was Joses, named Barnabas by the apostles, which is translated Son of Encouragement. This whole cluster is heavily quizzed."},{"id":2090,"day":18,"category":"acts4","difficulty":"hard","question":"What was Barnabas's tribe and country?","options":["A Benjamite of the country of Cyprus","A Levite of the country of Cyprus","A Levite of the country of Crete","A Levite of the country of Cilicia"],"correct":1,"reference":"Acts 4:36","explanation":"A Levite of the country of Cyprus. Remember: Levite + Cyprus + Son of Encouragement, all in one verse."},{"id":2091,"day":19,"category":"acts5","difficulty":"easy","question":"What were the names of the husband and wife who sold a possession?","options":["Ananias and Dorcas","Aquila and Priscilla","Ananias and Sapphira","Andronicus and Junia"],"correct":2,"reference":"Acts 5:1","explanation":"Ananias, with Sapphira his wife, sold a possession. Careful — a different, good Ananias appears in Acts 9."},{"id":2092,"day":19,"category":"acts5","difficulty":"medium","question":"What did Peter say had filled Ananias's heart?","options":["Satan","Greed","Fear","Pride"],"correct":0,"reference":"Acts 5:3","explanation":"'Ananias, why has Satan filled your heart to lie to the Holy Spirit…'"},{"id":2093,"day":19,"category":"acts5","difficulty":"hard","question":"According to Peter, who had Ananias really lied to?","options":["The apostles","His wife","The church","God"],"correct":3,"reference":"Acts 5:4","explanation":"'You have not lied to men but to God.' The money was his to keep — the sin was the lie, not the keeping."},{"id":2094,"day":19,"category":"acts5","difficulty":"medium","question":"How long after Ananias did Sapphira come in?","options":["About three hours later","About one hour later","The next morning","The same moment"],"correct":0,"reference":"Acts 5:7","explanation":"About three hours later — 'three hours late, same fate.'"},{"id":2095,"day":19,"category":"acts5","difficulty":"medium","question":"What came upon all the church after these events?","options":["Great boldness","Great grace","Great fear","Great joy"],"correct":2,"reference":"Acts 5:11","explanation":"'So great fear came upon all the church and upon all who heard these things.'"},{"id":2096,"day":20,"category":"acts5","difficulty":"medium","question":"Where were the believers all gathered with one accord?","options":["The upper room","The Beautiful Gate","Solomon's Porch","The Court of Women"],"correct":2,"reference":"Acts 5:12","explanation":"'And they were all with one accord in Solomon's Porch.'"},{"id":2097,"day":20,"category":"acts5","difficulty":"medium","question":"True or False: Many signs and wonders were done by the apostles among the people.","options":["False — only Peter did signs","True","True, but only in secret","False — the signs had stopped"],"correct":1,"reference":"Acts 5:12","explanation":"'Through the hands of the apostles many signs and wonders were done among the people.'"},{"id":2098,"day":20,"category":"acts5","difficulty":"easy","question":"What did people hope would fall on the sick lying in the streets?","options":["The word of Peter","The oil of anointing","The hands of the apostles","The shadow of Peter"],"correct":3,"reference":"Acts 5:15","explanation":"They laid the sick on beds and couches so that at least the shadow of Peter passing by might fall on some of them."},{"id":2099,"day":20,"category":"acts5","difficulty":"medium","question":"True or False: Only people from Jerusalem were healed.","options":["True — the city was closed","False — a multitude came from the surrounding cities","True — only Jerusalem","False — only Galileans came"],"correct":1,"reference":"Acts 5:16","explanation":"A multitude gathered from the surrounding cities to Jerusalem, bringing the sick and those tormented by unclean spirits."},{"id":2100,"day":20,"category":"acts5","difficulty":"medium","question":"What happened to those who were sick or tormented by unclean spirits?","options":["They were sent away","Only the believers were healed","They were all healed","Some were healed"],"correct":2,"reference":"Acts 5:16","explanation":"'And they were ALL healed.' The word 'all' is what the question usually hangs on."},{"id":2101,"day":21,"category":"acts5","difficulty":"medium","question":"Which group was the high priest part of?","options":["The sect of the Sadducees","The sect of the Pharisees","The Herodians","The scribes"],"correct":0,"reference":"Acts 5:17","explanation":"The high priest and all those with him were of the sect of the Sadducees, and they were filled with indignation."},{"id":2102,"day":21,"category":"acts5","difficulty":"medium","question":"Where were the apostles put?","options":["The inner prison","The common prison","The temple guardroom","The house of the high priest"],"correct":1,"reference":"Acts 5:18","explanation":"They laid hands on the apostles and put them in the common prison."},{"id":2103,"day":21,"category":"acts5","difficulty":"easy","question":"Who opened the prison doors, and when?","options":["An angel of the Lord, at dawn","A guard, in the morning","An earthquake, at midnight","An angel of the Lord, at night"],"correct":3,"reference":"Acts 5:19","explanation":"'But at night an angel of the Lord opened the prison doors and brought them out.'"},{"id":2104,"day":21,"category":"acts5","difficulty":"hard","question":"What did the angel tell them to do?","options":["Flee the city at once","Hide until morning","Go, stand in the temple and speak all the words of this life","Return to Galilee"],"correct":2,"reference":"Acts 5:20","explanation":"The angel did not tell them to escape — he told them to go straight back and preach in the temple."},{"id":2105,"day":21,"category":"acts5","difficulty":"medium","question":"When did the apostles enter the temple to teach?","options":["Early in the morning","In the evening","At midnight","At the ninth hour"],"correct":0,"reference":"Acts 5:21","explanation":"'And when they heard that, they entered the temple early in the morning and taught.'"},{"id":2106,"day":22,"category":"acts5","difficulty":"hard","question":"What did the officers report about the prison?","options":["The doors were broken open","It was shut securely with guards outside, but no one was inside","The guards were asleep","The prisoners had bribed the guards"],"correct":1,"reference":"Acts 5:23","explanation":"'We found the prison shut securely, and the guards standing outside before the doors; but when we opened them, we found no one inside!'"},{"id":2107,"day":22,"category":"acts5","difficulty":"medium","question":"Where were the escaped apostles found?","options":["Standing in the temple, teaching the people","On the road to Galilee","At Solomon's Porch praying","Hiding in the upper room"],"correct":0,"reference":"Acts 5:25","explanation":"'Look, the men whom you put in prison are standing in the temple and teaching the people!'"},{"id":2108,"day":22,"category":"acts5","difficulty":"medium","question":"Why did the captain bring them without violence?","options":["The council ordered gentleness","They respected the apostles","The apostles came willingly","They feared the people might stone them"],"correct":3,"reference":"Acts 5:26","explanation":"'For they feared the people, lest they should be stoned.'"},{"id":2109,"day":22,"category":"acts5","difficulty":"easy","question":"What was Peter and the apostles' famous answer to the council?","options":["We will speak no more in this name","We are witnesses of these things","We ought to obey God rather than men","Judge for yourselves what is right"],"correct":2,"reference":"Acts 5:29","explanation":"'We ought to obey God rather than men.' Short, quotable, and the Week 5 memory verse."},{"id":2110,"day":22,"category":"acts5","difficulty":"hard","question":"To what has God exalted Jesus, and as what?","options":["To His right hand, as Prince and Savior","To His right hand, as Lord and Christ","To heaven, as Judge and Ruler","To His throne, as King and Lord"],"correct":0,"reference":"Acts 5:31","explanation":"'Him God has exalted to His right hand to be Prince and Savior, to give repentance to Israel and forgiveness of sins.'"},{"id":2111,"day":23,"category":"acts5","difficulty":"easy","question":"Who stood up in the council to give advice?","options":["Annas","Gamaliel","Caiaphas","Nicodemus"],"correct":1,"reference":"Acts 5:34","explanation":"Gamaliel, a Pharisee and a teacher of the law held in respect by all the people. Think 'Gam-ALLY-el' — he acted like an ally."},{"id":2112,"day":23,"category":"acts5","difficulty":"medium","question":"What was Gamaliel's position?","options":["A Pharisee and teacher of the law","A scribe of the temple","A Levite and elder","A Sadducee and chief priest"],"correct":0,"reference":"Acts 5:34","explanation":"A Pharisee named Gamaliel, a teacher of the law held in respect by all the people."},{"id":2113,"day":23,"category":"acts5","difficulty":"hard","question":"Which two men did Gamaliel give as examples?","options":["Theudas and Simon the sorcerer","Judas Iscariot and Theudas","Barabbas and Judas of Galilee","Theudas and Judas of Galilee"],"correct":3,"reference":"Acts 5:36-37","explanation":"Theudas, who had about four hundred men join him, and Judas of Galilee, who rose up in the days of the census. Both movements came to nothing."},{"id":2114,"day":23,"category":"acts5","difficulty":"hard","question":"What was Gamaliel's reasoning?","options":["If it is of men it will come to nothing; if it is of God you cannot overthrow it","If they are guilty, God will judge them","Rome will settle the matter","The people will decide in time"],"correct":0,"reference":"Acts 5:38-39","explanation":"And he warned they might 'even be found to fight against God.' That argument saved the apostles' lives."},{"id":2115,"day":23,"category":"acts5","difficulty":"medium","question":"How did the apostles feel after being beaten?","options":["Discouraged but determined","Angry at the council","Afraid to return to the temple","Rejoicing that they were counted worthy to suffer shame for His name"],"correct":3,"reference":"Acts 5:41","explanation":"They departed rejoicing that they were counted worthy to suffer shame for His name — and kept teaching daily."},{"id":2116,"day":24,"category":"acts6","difficulty":"medium","question":"Who complained against whom, and why?","options":["The elders against the apostles, over money","The Hellenists against the Hebrews, because their widows were neglected","The Hebrews against the Hellenists, over the daily bread","The widows against the twelve, over prayer"],"correct":1,"reference":"Acts 6:1","explanation":"The Hellenists complained against the Hebrews because their widows were neglected in the daily distribution."},{"id":2117,"day":24,"category":"acts6","difficulty":"medium","question":"How many men were to be sought out to handle the distribution?","options":["Five","Ten","Seven","Twelve"],"correct":2,"reference":"Acts 6:3","explanation":"'Seek out from among you seven men of good reputation, full of the Holy Spirit and wisdom.'"},{"id":2118,"day":24,"category":"acts6","difficulty":"hard","question":"What three qualities were required of the seven?","options":["Faith, courage, and honesty","Wisdom, strength, and patience","Good reputation, learning, and wealth","Good reputation, full of the Holy Spirit, and wisdom"],"correct":3,"reference":"Acts 6:3","explanation":"Men of good reputation, full of the Holy Spirit and wisdom."},{"id":2119,"day":24,"category":"acts6","difficulty":"hard","question":"Who were the seven men chosen?","options":["Stephen, Philip, Prochorus, Nicanor, Timon, Parmenas, Nicolas","Stephen, Philip, Barnabas, Nicanor, Timon, Parmenas, Nicolas","Stephen, Peter, Prochorus, Nicanor, Timon, Parmenas, Nicolas","Stephen, Philip, Prochorus, Nicanor, Silas, Parmenas, Nicolas"],"correct":0,"reference":"Acts 6:5","explanation":"Chant it: 'Stephen, Philip, Prochorus, Nicanor — Timon, Parmenas, Nicolas.' Nicolas was a proselyte from Antioch."},{"id":2120,"day":24,"category":"acts6","difficulty":"medium","question":"Who among the seven was a proselyte from Antioch?","options":["Parmenas","Prochorus","Nicanor","Nicolas"],"correct":3,"reference":"Acts 6:5","explanation":"'And Nicolas, a proselyte from Antioch.' He is the only one given that description."},{"id":2121,"day":25,"category":"acts6","difficulty":"medium","question":"How is Stephen described as he did great wonders and signs?","options":["Full of the Spirit and joy","Full of wisdom and grace","Full of faith and power","Full of courage and truth"],"correct":2,"reference":"Acts 6:8","explanation":"'And Stephen, full of faith and power, did great wonders and signs among the people.'"},{"id":2122,"day":25,"category":"acts6","difficulty":"hard","question":"What was the name of the synagogue whose members disputed with Stephen?","options":["The Synagogue of the Elders","The Synagogue of Alexandria","The Synagogue of the Freedmen","The Synagogue of the Cyrenians"],"correct":2,"reference":"Acts 6:9","explanation":"The Synagogue of the Freedmen — including Cyrenians, Alexandrians, and those from Cilicia and Asia."},{"id":2123,"day":25,"category":"acts6","difficulty":"medium","question":"What were his opponents unable to resist?","options":["The wisdom and the Spirit by which he spoke","His miracles","His courage","The crowd's support"],"correct":0,"reference":"Acts 6:10","explanation":"'And they were not able to resist the wisdom and the Spirit by which he spoke.' So they resorted to lies instead."},{"id":2124,"day":25,"category":"acts6","difficulty":"medium","question":"What were the false witnesses paid to claim Stephen had spoken against?","options":["Moses and God","The prophets and the council","The temple and the priests","Caesar and the law"],"correct":0,"reference":"Acts 6:11","explanation":"'We have heard him speak blasphemous words against Moses and God.'"},{"id":2125,"day":25,"category":"acts6","difficulty":"easy","question":"What did the council see when they looked steadfastly at Stephen?","options":["That he was afraid","That he was praying","A light around him","His face as the face of an angel"],"correct":3,"reference":"Acts 6:15","explanation":"'All who sat in the council, looking steadfastly at him, saw his face as the face of an angel.'"},{"id":2126,"day":26,"category":"acts7","difficulty":"medium","question":"Where was Abraham when the God of glory appeared to him?","options":["In Ur, after leaving Haran","In Haran, before he went to Canaan","In Mesopotamia, before he dwelt in Haran","In Egypt, before the famine"],"correct":2,"reference":"Acts 7:2","explanation":"'The God of glory appeared to our father Abraham when he was in Mesopotamia, before he dwelt in Haran.'"},{"id":2127,"day":26,"category":"acts7","difficulty":"medium","question":"What did God command Abraham to do?","options":["Stay where he was and wait","Get out of your country and from your relatives","Build an altar in the mountains","Go back to Jerusalem"],"correct":1,"reference":"Acts 7:3","explanation":"'Get out of your country and from your relatives, and come to a land that I will show you.'"},{"id":2128,"day":26,"category":"acts7","difficulty":"hard","question":"How much inheritance did God give Abraham in the land?","options":["None — not even enough to set his foot on","A field near Shechem","A tomb and a well","A tenth of the land"],"correct":0,"reference":"Acts 7:5","explanation":"God gave him no inheritance in it, not even enough to set his foot on — yet He promised it to him and his descendants."},{"id":2129,"day":26,"category":"acts7","difficulty":"medium","question":"For how many years would Abraham's descendants be oppressed in a foreign land?","options":["Forty years","Four hundred years","Three hundred years","Five hundred years"],"correct":1,"reference":"Acts 7:6","explanation":"God said they would be in bondage and oppressed four hundred years."},{"id":2130,"day":26,"category":"acts7","difficulty":"hard","question":"On what day was Isaac circumcised, and what did Jacob beget?","options":["The eighth day; the twelve apostles","The seventh day; the twelve tribes","The first day; the twelve patriarchs","The eighth day; the twelve patriarchs"],"correct":3,"reference":"Acts 7:8","explanation":"Abraham begot Isaac and circumcised him on the eighth day; Isaac begot Jacob, and Jacob begot the twelve patriarchs."},{"id":2131,"day":27,"category":"acts7","difficulty":"medium","question":"Why did the patriarchs sell Joseph into Egypt?","options":["They feared his dreams","They needed money","They became envious","Their father commanded it"],"correct":2,"reference":"Acts 7:9","explanation":"'And the patriarchs, becoming envious, sold Joseph into Egypt. But God was with him.'"},{"id":2132,"day":27,"category":"acts7","difficulty":"medium","question":"What two things did God give Joseph in Pharaoh's presence?","options":["Favor and freedom","Favor and wisdom","Wisdom and strength","Power and riches"],"correct":1,"reference":"Acts 7:10","explanation":"God 'gave him favor and wisdom in the presence of Pharaoh, king of Egypt,' and he was made governor over Egypt and all his house."},{"id":2133,"day":27,"category":"acts7","difficulty":"medium","question":"What came over the land of Egypt and Canaan?","options":["A famine and great trouble","A war","A plague","A great flood"],"correct":0,"reference":"Acts 7:11","explanation":"'Now a famine and great trouble came over all the land of Egypt and Canaan, and our fathers found no sustenance.'"},{"id":2134,"day":27,"category":"acts7","difficulty":"hard","question":"How many people did Joseph call down to Egypt?","options":["Seventy","Eighty","Seventy-five","Sixty-six"],"correct":2,"reference":"Acts 7:14","explanation":"Joseph called his father Jacob and all his relatives — seventy-five people. Pair it: '75 went down, 400 years stayed down.'"},{"id":2135,"day":27,"category":"acts7","difficulty":"hard","question":"Where were Jacob and the fathers carried back to and laid?","options":["Bethel, in the family tomb","Hebron, in the cave of Machpelah","Haran, in their father's land","Shechem, in the tomb Abraham bought"],"correct":3,"reference":"Acts 7:16","explanation":"They were carried back to Shechem and laid in the tomb Abraham bought from the sons of Hamor."},{"id":2136,"day":28,"category":"acts7","difficulty":"medium","question":"What was true of the new king who arose in Egypt?","options":["He was a friend of Israel","He did not know Joseph","He was killed in a war","He was Joseph's son"],"correct":1,"reference":"Acts 7:18","explanation":"'Till another king arose who did not know Joseph.'"},{"id":2137,"day":28,"category":"acts7","difficulty":"medium","question":"What cruel thing did that king make the people do?","options":["Expose their babies so they might not live","Leave their homes","Give up their flocks","Build cities without straw"],"correct":0,"reference":"Acts 7:19","explanation":"He dealt treacherously with them, 'making them expose their babies, so that they might not live.'"},{"id":2138,"day":28,"category":"acts7","difficulty":"hard","question":"How long was Moses brought up in his father's house?","options":["One year","Three months","Forty days","Three years"],"correct":1,"reference":"Acts 7:20","explanation":"Moses was well pleasing to God and was brought up in his father's house for three months."},{"id":2139,"day":28,"category":"acts7","difficulty":"medium","question":"Who took Moses and brought him up as her own son?","options":["Pharaoh's wife","His own mother","Pharaoh's daughter","An Egyptian priestess"],"correct":2,"reference":"Acts 7:21","explanation":"'But when he was set out, Pharaoh's daughter took him away and brought him up as her own son.'"},{"id":2140,"day":28,"category":"acts7","difficulty":"medium","question":"How is Moses described in verse 22?","options":["A prince and a warrior","Humble and slow of speech","A shepherd and a wanderer","Learned in all the wisdom of the Egyptians, mighty in words and deeds"],"correct":3,"reference":"Acts 7:22","explanation":"'And Moses was learned in all the wisdom of the Egyptians, and was mighty in words and deeds.'"},{"id":2141,"day":29,"category":"acts7","difficulty":"medium","question":"How old was Moses when he decided to visit his brethren?","options":["Thirty years old","Forty years old","Eighty years old","Twenty years old"],"correct":1,"reference":"Acts 7:23","explanation":"'Now when he was forty years old, it came into his heart to visit his brethren.' This is the first 40 of Moses' three forties."},{"id":2142,"day":29,"category":"acts7","difficulty":"medium","question":"What did Moses do when he saw one of them suffer wrong?","options":["He defended him and struck down the Egyptian","He fled in fear","He prayed for him","He reported it to Pharaoh"],"correct":0,"reference":"Acts 7:24","explanation":"'He defended and avenged him who was oppressed, and struck down the Egyptian.'"},{"id":2143,"day":29,"category":"acts7","difficulty":"hard","question":"What did Moses suppose his brethren would understand?","options":["That he was on their side","That Pharaoh would free them","That God would deliver them by his hand","That he would become their king"],"correct":2,"reference":"Acts 7:25","explanation":"'For he supposed that his brethren would have understood that God would deliver them by his hand, but they did not understand.'"},{"id":2144,"day":29,"category":"acts7","difficulty":"medium","question":"What did the man who was doing wrong say to Moses?","options":["You are not one of us","Go back to Pharaoh","Who made you a ruler and a judge over us?","Leave us alone, Egyptian!"],"correct":2,"reference":"Acts 7:27","explanation":"'Who made you a ruler and a judge over us?' Stephen repeats this line later in verse 35 to make his point."},{"id":2145,"day":29,"category":"acts7","difficulty":"medium","question":"Where did Moses flee to, and how many sons did he have there?","options":["Sinai, where he had two sons","Canaan, where he had two sons","Midian, where he had three sons","Midian, where he had two sons"],"correct":3,"reference":"Acts 7:29","explanation":"'Moses fled and became a dweller in the land of Midian, where he had two sons.'"},{"id":2146,"day":30,"category":"acts7","difficulty":"medium","question":"How many years passed before the Angel appeared to Moses?","options":["Forty years","Ten years","Twenty years","Thirty years"],"correct":0,"reference":"Acts 7:30","explanation":"'And when forty years had passed, an Angel of the Lord appeared to him.' That is the second forty."},{"id":2147,"day":30,"category":"acts7","difficulty":"medium","question":"Where and how did the Angel of the Lord appear to Moses?","options":["In a pillar of fire in the desert","In a dream in Midian","In a flame of fire in a bush, in the wilderness of Mount Sinai","In a cloud on Mount Horeb"],"correct":2,"reference":"Acts 7:30","explanation":"In a flame of fire in a bush, in the wilderness of Mount Sinai."},{"id":2148,"day":30,"category":"acts7","difficulty":"hard","question":"How did God identify Himself to Moses?","options":["The God of heaven and earth","The God who was and is to come","The God of Abraham, the God of Isaac, and the God of Jacob","The God of Israel and Egypt"],"correct":2,"reference":"Acts 7:32","explanation":"'I am the God of your fathers — the God of Abraham, the God of Isaac, and the God of Jacob.' And Moses trembled and dared not look."},{"id":2149,"day":30,"category":"acts7","difficulty":"easy","question":"Complete the verse: 'Take your sandals off your feet, for the place where you stand is ___.'","options":["holy ground","sacred to Me","before the Lord","the mount of God"],"correct":0,"reference":"Acts 7:33","explanation":"'Take your sandals off your feet, for the place where you stand is holy ground.' This is the Week 6 memory verse."},{"id":2150,"day":30,"category":"acts7","difficulty":"medium","question":"God sent Moses to be what two things?","options":["A judge and a king","A leader and a lawgiver","A prophet and a priest","A ruler and a deliverer"],"correct":3,"reference":"Acts 7:35","explanation":"The very man they rejected as 'a ruler and a judge' is the one God sent to be 'a ruler and a deliverer.' That is Stephen's whole argument."},{"id":2151,"day":31,"category":"acts7","difficulty":"medium","question":"Where was Moses when the Angel spoke to him and he received the living oracles?","options":["In the congregation in the wilderness, on Mount Sinai","In the tabernacle of witness","In Egypt before Pharaoh","In Midian by the well"],"correct":0,"reference":"Acts 7:38","explanation":"He was in the congregation in the wilderness with the Angel who spoke to him on Mount Sinai, and received the living oracles to give to us."},{"id":2152,"day":31,"category":"acts7","difficulty":"medium","question":"In their hearts, where did the fathers turn back to?","options":["Midian","Canaan","Babylon","Egypt"],"correct":3,"reference":"Acts 7:39","explanation":"They would not obey Moses but rejected him, and in their hearts they turned back to Egypt."},{"id":2153,"day":31,"category":"acts7","difficulty":"easy","question":"What did the people ask Aaron to make, and what did they make?","options":["Gods to go before them; they made a calf","An altar; they made a tent","A throne; they made an ark","Gods to go before them; they made a serpent"],"correct":0,"reference":"Acts 7:40-41","explanation":"They told Aaron to make gods to go before them, and they made a calf, offered sacrifices to the idol, and rejoiced in the works of their own hands."},{"id":2154,"day":31,"category":"acts7","difficulty":"hard","question":"For how many years does the quotation ask whether they offered sacrifices in the wilderness?","options":["Thirty years","Forty years","Seventy years","Four hundred years"],"correct":1,"reference":"Acts 7:42","explanation":"'Did you offer Me slaughtered animals and sacrifices during forty years in the wilderness, O house of Israel?'"},{"id":2155,"day":31,"category":"acts7","difficulty":"hard","question":"Whose tabernacle and whose star did they take up?","options":["The tabernacle of Moloch and the star of Chiun","The tabernacle of Remphan and the star of Moloch","The tabernacle of Baal and the star of Dagon","The tabernacle of Moloch and the star of Remphan"],"correct":3,"reference":"Acts 7:43","explanation":"'You also took up the tabernacle of Moloch, and the star of your god Remphan.' Two hard names — learn them as a pair."},{"id":2156,"day":32,"category":"acts7","difficulty":"medium","question":"What did the fathers have in the wilderness?","options":["The tent of meeting of David","The ark of the covenant only","The tabernacle of witness","The temple of the Lord"],"correct":2,"reference":"Acts 7:44","explanation":"'Our fathers had the tabernacle of witness in the wilderness, as He appointed, instructing Moses to make it according to the pattern that he had seen.'"},{"id":2157,"day":32,"category":"acts7","difficulty":"medium","question":"Who brought the tabernacle into the land possessed by the Gentiles?","options":["Moses","David","Samuel","Joshua"],"correct":3,"reference":"Acts 7:45","explanation":"Our fathers brought it with Joshua into the land God drove the nations out of, until the days of David."},{"id":2158,"day":32,"category":"acts7","difficulty":"medium","question":"Who asked to find a dwelling for the God of Jacob, and who actually built the house?","options":["David asked; Solomon built it","Solomon asked; David built it","Moses asked; Joshua built it","David asked; Joshua built it"],"correct":0,"reference":"Acts 7:46-47","explanation":"David found favor before God and asked; 'But Solomon built Him a house.'"},{"id":2159,"day":32,"category":"acts7","difficulty":"hard","question":"Complete the prophecy: 'Heaven is My throne, and earth is My ___.'","options":["resting place","footstool","garden","dwelling"],"correct":1,"reference":"Acts 7:49","explanation":"'Heaven is My throne, and earth is My footstool. What house will you build for Me?' The Most High does not dwell in temples made with hands."},{"id":2160,"day":32,"category":"acts7","difficulty":"hard","question":"What did Stephen accuse the council of always doing?","options":["Resisting the Holy Spirit","Forgetting the prophets","Breaking the Sabbath","Worshiping idols"],"correct":0,"reference":"Acts 7:51","explanation":"'You stiff-necked and uncircumcised in heart and ears! You always resist the Holy Spirit; as your fathers did, so do you.'"},{"id":2161,"day":33,"category":"acts7","difficulty":"medium","question":"How did the council react when they heard Stephen's words?","options":["They were silent and ashamed","They asked him to explain further","They were cut to the heart and gnashed at him with their teeth","They laughed at him"],"correct":2,"reference":"Acts 7:54","explanation":"They were cut to the heart and gnashed at him with their teeth — a very different reaction from the crowd in Acts 2:37 who were also cut to the heart."},{"id":2162,"day":33,"category":"acts7","difficulty":"easy","question":"What did Stephen see when he gazed into heaven?","options":["The throne of God alone","A great light and an open door","Angels descending","The glory of God, and Jesus standing at the right hand of God"],"correct":3,"reference":"Acts 7:55","explanation":"Full of the Holy Spirit, he saw the glory of God and Jesus STANDING at the right hand of God."},{"id":2163,"day":33,"category":"acts7","difficulty":"medium","question":"What title did Stephen use for Jesus in his cry?","options":["The Son of Man","The Prince of life","The Son of God","The Holy One"],"correct":0,"reference":"Acts 7:56","explanation":"'Look! I see the heavens opened and the Son of Man standing at the right hand of God!' This is the Week 7 memory verse."},{"id":2164,"day":33,"category":"acts7","difficulty":"medium","question":"At whose feet did the witnesses lay down their clothes?","options":["The high priest","A young man named Saul","A young man named Silas","A young man named Simon"],"correct":1,"reference":"Acts 7:58","explanation":"This is Saul's very first appearance in the Bible — holding the coats at Stephen's stoning. Remember it: he becomes Paul."},{"id":2165,"day":33,"category":"acts7","difficulty":"hard","question":"What was Stephen's last prayer?","options":["Father, forgive them","Lord Jesus, receive my spirit","Lord, do not charge them with this sin","Lord, remember me"],"correct":2,"reference":"Acts 7:60","explanation":"He first said 'Lord Jesus, receive my spirit' (v59), then knelt and cried, 'Lord, do not charge them with this sin' — and fell asleep."},{"id":2166,"day":34,"category":"acts8","difficulty":"medium","question":"What was Saul doing at Stephen's death?","options":["Casting the first stone","Consenting to his death","Watching from a distance in secret","Pleading for his life"],"correct":1,"reference":"Acts 8:1","explanation":"'Now Saul was consenting to his death.' He approved of it."},{"id":2167,"day":34,"category":"acts8","difficulty":"hard","question":"Who was NOT scattered by the great persecution?","options":["The elders","The seven","The widows","The apostles"],"correct":3,"reference":"Acts 8:1","explanation":"They were all scattered throughout Judea and Samaria, EXCEPT the apostles. That exception is a favourite quiz detail."},{"id":2168,"day":34,"category":"acts8","difficulty":"medium","question":"How did Saul make havoc of the church?","options":["Preaching against them in the synagogues","Entering every house and dragging off men and women to prison","Burning down the meeting places","Bribing the officials"],"correct":1,"reference":"Acts 8:3","explanation":"'As for Saul, he made havoc of the church, entering every house, and dragging off men and women, committing them to prison.'"},{"id":2169,"day":34,"category":"acts8","difficulty":"easy","question":"What did those who were scattered do?","options":["They returned to their old work","They gathered in Samaria to wait","They went everywhere preaching the word","They hid until the danger passed"],"correct":2,"reference":"Acts 8:4","explanation":"The persecution meant to stop the gospel is exactly what spread it. Step two of the Acts 1:8 map is now happening."},{"id":2170,"day":34,"category":"acts8","difficulty":"medium","question":"Who went down to the city of Samaria and preached Christ, and what was the result?","options":["Peter; there was great fear in that city","Philip; there was great fear in that city","Philip; there was great joy in that city","Stephen; there was great joy in that city"],"correct":2,"reference":"Acts 8:5-8","explanation":"Philip — one of the seven from Acts 6:5, not Philip the apostle. Unclean spirits came out and many paralyzed and lame were healed, and there was great joy in that city."},{"id":2171,"day":35,"category":"acts8","difficulty":"easy","question":"What was the name of the man who practiced sorcery in Samaria?","options":["Elymas","Simon","Nicolas","Bar-Jesus"],"correct":1,"reference":"Acts 8:9","explanation":"Simon previously practiced sorcery and astonished the people of Samaria, claiming that he was someone great."},{"id":2172,"day":35,"category":"acts8","difficulty":"medium","question":"What did the people of Samaria call Simon?","options":["The servant of the Most High","The wise one","The prophet of Samaria","The great power of God"],"correct":3,"reference":"Acts 8:10","explanation":"'This man is the great power of God' — from the least to the greatest, they all gave heed to him."},{"id":2173,"day":35,"category":"acts8","difficulty":"medium","question":"Why had the people heeded Simon for so long?","options":["He gave them money","He had astonished them with his sorceries for a long time","He had healed their sick","He was a ruler of the city"],"correct":1,"reference":"Acts 8:11","explanation":"'And they heeded him because he had astonished them with his sorceries for a long time.'"},{"id":2174,"day":35,"category":"acts8","difficulty":"medium","question":"What did Philip preach that caused men and women to be baptized?","options":["The resurrection only","Repentance from sorcery","The kingdom of God and the name of Jesus Christ","The law of Moses"],"correct":2,"reference":"Acts 8:12","explanation":"'When they believed Philip as he preached the things concerning the kingdom of God and the name of Jesus Christ, both men and women were baptized.'"},{"id":2175,"day":35,"category":"acts8","difficulty":"medium","question":"What did Simon himself do?","options":["He fled the city","He believed, was baptized, and continued with Philip","He refused to listen","He challenged Philip to a contest"],"correct":1,"reference":"Acts 8:13","explanation":"Simon himself also believed and was baptized, and was amazed at the miracles and signs which were done."},{"id":2176,"day":36,"category":"acts8","difficulty":"medium","question":"Whom did the apostles at Jerusalem send to Samaria?","options":["Peter and John","John and Philip","Peter and James","Paul and Barnabas"],"correct":0,"reference":"Acts 8:14","explanation":"When they heard that Samaria had received the word of God, they sent Peter and John."},{"id":2177,"day":36,"category":"acts8","difficulty":"hard","question":"In whose name had the Samaritans only been baptized so far?","options":["John the Baptist","The Holy Spirit","The Father and the Son","The Lord Jesus"],"correct":3,"reference":"Acts 8:16","explanation":"'They had only been baptized in the name of the Lord Jesus' — the Spirit had not yet fallen on any of them."},{"id":2178,"day":36,"category":"acts8","difficulty":"easy","question":"What did Simon offer the apostles?","options":["His sorcery books","His house","Money","His service"],"correct":2,"reference":"Acts 8:18","explanation":"Seeing that the Holy Spirit was given through the laying on of the apostles' hands, he offered them money for the power."},{"id":2179,"day":36,"category":"acts8","difficulty":"medium","question":"What did Peter say to Simon?","options":["Your money perish with you","Leave this city at once","You are not worthy of this gift","Go, and sin no more"],"correct":0,"reference":"Acts 8:20","explanation":"'Your money perish with you, because you thought that the gift of God could be purchased with money!'"},{"id":2180,"day":36,"category":"acts8","difficulty":"hard","question":"How did Peter describe Simon's condition?","options":["Blinded by pride and greed","Poisoned by bitterness and bound by iniquity","Deceived by sorcery","Hardened in heart and mind"],"correct":1,"reference":"Acts 8:23","explanation":"'For I see that you are poisoned by bitterness and bound by iniquity.' Peter told him to repent and pray."},{"id":2181,"day":37,"category":"acts8","difficulty":"medium","question":"Which road was Philip sent to, and what kind of place was it?","options":["The road from Jerusalem to Gaza; it is desert","The road from Samaria to Gaza; it is mountainous","The road from Jerusalem to Damascus; it is desert","The road from Jerusalem to Joppa; it is by the sea"],"correct":0,"reference":"Acts 8:26","explanation":"An angel told him to go toward the south along the road which goes down from Jerusalem to Gaza. 'This is desert.'"},{"id":2182,"day":37,"category":"acts8","difficulty":"hard","question":"Who was the Ethiopian, and what was his job?","options":["A merchant of the queen's household","A soldier of the Ethiopian guard","A scribe of the queen's court","A eunuch of great authority under Candace, in charge of all her treasury"],"correct":3,"reference":"Acts 8:27","explanation":"A eunuch of great authority under Candace the queen of the Ethiopians, who had charge of all her treasury. 'Candace' is a royal title, like 'Pharaoh.'"},{"id":2183,"day":37,"category":"acts8","difficulty":"medium","question":"Why had the Ethiopian come to Jerusalem?","options":["To buy scrolls","To trade","To worship","To visit the queen's ambassadors"],"correct":2,"reference":"Acts 8:27","explanation":"'And had come to Jerusalem to worship' — he was returning home when Philip met him."},{"id":2184,"day":37,"category":"acts8","difficulty":"easy","question":"Which prophet was the Ethiopian reading?","options":["Daniel","Isaiah","Jeremiah","Joel"],"correct":1,"reference":"Acts 8:28","explanation":"Sitting in his chariot, he was reading Isaiah the prophet — out loud, which is how Philip could hear him."},{"id":2185,"day":37,"category":"acts8","difficulty":"medium","question":"What did the Ethiopian answer when Philip asked if he understood?","options":["How can I, unless someone guides me?","Only a priest could tell me","I understand it well enough","It speaks of the prophet himself"],"correct":0,"reference":"Acts 8:31","explanation":"'How can I, unless someone guides me?' And he asked Philip to come up and sit with him."},{"id":2186,"day":38,"category":"acts8","difficulty":"medium","question":"What did the eunuch ask Philip about the Scripture?","options":["When will this come to pass?","Of whom does the prophet say this, of himself or of some other man?","Why is this passage so sad?","Who wrote these words?"],"correct":1,"reference":"Acts 8:34","explanation":"That question opened the door — Philip began at that Scripture and preached Jesus to him."},{"id":2187,"day":38,"category":"acts8","difficulty":"medium","question":"What did the eunuch say when they came to some water?","options":["Let us stop and rest here","Is this the water of life?","Shall we drink before we go on?","See, here is water. What hinders me from being baptized?"],"correct":3,"reference":"Acts 8:36","explanation":"'See, here is water. What hinders me from being baptized?'"},{"id":2188,"day":38,"category":"acts8","difficulty":"hard","question":"What did the eunuch confess before being baptized?","options":["I believe that Jesus Christ is the Son of God","I believe in the God of Israel","I will follow the Way","I believe the prophet Isaiah"],"correct":0,"reference":"Acts 8:37","explanation":"Philip said, 'If you believe with all your heart, you may.' And he answered, 'I believe that Jesus Christ is the Son of God.'"},{"id":2189,"day":38,"category":"acts8","difficulty":"medium","question":"What happened immediately after the baptism?","options":["Philip returned to Samaria on foot","An angel appeared to them both","They travelled on together to Gaza","The Spirit of the Lord caught Philip away, and the eunuch went on his way rejoicing"],"correct":3,"reference":"Acts 8:39","explanation":"The Spirit caught Philip away so the eunuch saw him no more — and he went on his way rejoicing."},{"id":2190,"day":38,"category":"acts8","difficulty":"hard","question":"Where was Philip found, and where did he preach until he arrived?","options":["Found at Azotus; preached until he came to Caesarea","Found at Azotus; preached until he came to Jerusalem","Found at Gaza; preached until he came to Joppa","Found at Samaria; preached until he came to Caesarea"],"correct":0,"reference":"Acts 8:40","explanation":"'But Philip was found at Azotus. And passing through, he preached in all the cities till he came to Caesarea.'"},{"id":2191,"day":39,"category":"acts9","difficulty":"easy","question":"Who was breathing threats and murder against the disciples?","options":["Philip","Cornelius","Saul","Simon"],"correct":2,"reference":"Acts 9:1","explanation":"'Then Saul, still breathing threats and murder against the disciples of the Lord, went to the high priest.'"},{"id":2192,"day":39,"category":"acts9","difficulty":"medium","question":"What did Saul ask the high priest for?","options":["Permission to enter Samaria","Soldiers to arrest the disciples","Money for the journey","Letters to the synagogues of Damascus"],"correct":3,"reference":"Acts 9:2","explanation":"He asked for letters to the synagogues of Damascus so he could bring any of the Way bound to Jerusalem."},{"id":2193,"day":39,"category":"acts9","difficulty":"easy","question":"Near which city did Saul see the light from heaven?","options":["Jerusalem","Damascus","Caesarea","Bethlehem"],"correct":1,"reference":"Acts 9:3","explanation":"'As he journeyed he came near Damascus, and suddenly a light shone around him from heaven.'"},{"id":2194,"day":39,"category":"acts9","difficulty":"medium","question":"Whose voice did Saul hear, and what did it say?","options":["Jesus — 'Why do you fight against God?'","The high priest — 'Return to Jerusalem'","An angel — 'Saul, arise and go'","Jesus — 'Saul, Saul, why are you persecuting Me?'"],"correct":3,"reference":"Acts 9:4-5","explanation":"'Saul, Saul, why are you persecuting Me?' … 'I am Jesus, whom you are persecuting.'"},{"id":2195,"day":39,"category":"acts9","difficulty":"medium","question":"How long was Saul without sight, and what did he do during that time?","options":["Three days; he ate only bread","Seven days; he fasted and prayed","Three days; he neither ate nor drank","One week; he neither ate nor drank"],"correct":2,"reference":"Acts 9:9","explanation":"'And he was three days without sight, and neither ate nor drank.' Remember the three threes."},{"id":2196,"day":40,"category":"acts9","difficulty":"medium","question":"What was the name of the disciple at Damascus whom the Lord spoke to in a vision?","options":["Simon","Barnabas","Ananias","Judas"],"correct":2,"reference":"Acts 9:10","explanation":"Ananias — a GOOD Ananias, not the one who lied and died in Acts 5. Two completely different men."},{"id":2197,"day":40,"category":"acts9","difficulty":"hard","question":"Which street, whose house, and which man was Ananias told to find?","options":["The street called Straight, the house of Judas, Saul of Tarsus","The street called Straight, the house of Simon, Saul of Tarsus","The main street, the house of Judas, Saul of Damascus","The street called Straight, the house of Ananias, Saul of Tarsus"],"correct":0,"reference":"Acts 9:11","explanation":"All three details are in one verse — they are often asked together. And the Lord added: 'behold, he is praying.'"},{"id":2198,"day":40,"category":"acts9","difficulty":"medium","question":"Why was Ananias afraid to go?","options":["He had been forbidden by the elders","He had heard how much harm Saul had done to the saints in Jerusalem","He did not know the way","He feared the Roman soldiers"],"correct":1,"reference":"Acts 9:13-14","explanation":"Saul had authority from the chief priests to bind all who called on the Lord's name."},{"id":2199,"day":40,"category":"acts9","difficulty":"hard","question":"What did the Lord call Saul, and before whom would he bear His name?","options":["A chosen vessel — before kings and priests","A chosen apostle — before Jews and Gentiles","A faithful servant — before the nations and their rulers","A chosen vessel — before Gentiles, kings, and the children of Israel"],"correct":3,"reference":"Acts 9:15","explanation":"'He is a chosen vessel of Mine to bear My name before Gentiles, kings, and the children of Israel.' The Week 8 memory verse."},{"id":2200,"day":40,"category":"acts9","difficulty":"easy","question":"What fell from Saul's eyes?","options":["A dark cloth","Tears of repentance","Something like scales","A shadow"],"correct":2,"reference":"Acts 9:18","explanation":"'Immediately there fell from his eyes something like scales, and he received his sight at once; and he arose and was baptized.'"},{"id":2201,"day":41,"category":"acts9","difficulty":"medium","question":"What did Saul immediately preach in the synagogues?","options":["The Christ, that He is the Son of God","The coming of the Holy Spirit","The resurrection of the dead","Repentance from the law"],"correct":0,"reference":"Acts 9:20","explanation":"'Immediately he preached the Christ in the synagogues, that He is the Son of God.' No delay at all."},{"id":2202,"day":41,"category":"acts9","difficulty":"medium","question":"Why were all who heard him amazed?","options":["Because he spoke so many languages","Because he was the one who had destroyed those who called on this name","Because he was so young","Because he performed miracles"],"correct":1,"reference":"Acts 9:21","explanation":"'Is this not he who destroyed those who called on this name in Jerusalem?'"},{"id":2203,"day":41,"category":"acts9","difficulty":"medium","question":"What was Saul proving to the Jews in Damascus?","options":["That the Gentiles could be saved","That this Jesus is the Christ","That the law was fulfilled","That the temple would fall"],"correct":1,"reference":"Acts 9:22","explanation":"'But Saul increased all the more in strength, and confounded the Jews who dwelt in Damascus, proving that this Jesus is the Christ.'"},{"id":2204,"day":41,"category":"acts9","difficulty":"medium","question":"How closely did the plotters watch for Saul?","options":["They set guards at the synagogue","They searched every house","They followed him in secret","They watched the gates day and night"],"correct":3,"reference":"Acts 9:24","explanation":"'And they watched the gates day and night, to kill him.'"},{"id":2205,"day":41,"category":"acts9","difficulty":"easy","question":"How did Saul escape from Damascus?","options":["He slipped out at the gate in disguise","The disciples let him down through the wall in a large basket by night","He escaped by boat","He was carried out by soldiers"],"correct":1,"reference":"Acts 9:25","explanation":"The great persecutor of the church escaped over a wall in a basket. Note it happened BY NIGHT."},{"id":2206,"day":42,"category":"acts9","difficulty":"medium","question":"How did the disciples at Jerusalem react to Saul?","options":["They were all afraid of him and did not believe he was a disciple","They asked him to prove himself with a miracle","They sent him away at once","They welcomed him with joy"],"correct":0,"reference":"Acts 9:26","explanation":"They were all afraid of him and did not believe that he was a disciple — which is understandable, given chapter 8."},{"id":2207,"day":42,"category":"acts9","difficulty":"easy","question":"Who took Saul and brought him to the apostles?","options":["Philip","Barnabas","Peter","Silas"],"correct":1,"reference":"Acts 9:27","explanation":"Barnabas — the Son of Encouragement — vouched for him. Without Barnabas, Saul may never have been accepted."},{"id":2208,"day":42,"category":"acts9","difficulty":"hard","question":"What three things did Barnabas declare to the apostles about Saul?","options":["He had seen a vision, healed the sick, and preached in Samaria","He had repented, been baptized, and fasted","He had seen the Lord, the Lord had spoken to him, and he had preached boldly at Damascus","He had left the chief priests, changed his name, and joined the Way"],"correct":2,"reference":"Acts 9:27","explanation":"How he had seen the Lord on the road, that He had spoken to him, and how he had preached boldly at Damascus in the name of Jesus."},{"id":2209,"day":42,"category":"acts9","difficulty":"medium","question":"Against whom did Saul dispute in Jerusalem?","options":["The Sadducees","The Pharisees","The scribes","The Hellenists"],"correct":3,"reference":"Acts 9:29","explanation":"'He spoke boldly in the name of the Lord Jesus and disputed against the Hellenists, but they attempted to kill him.'"},{"id":2210,"day":42,"category":"acts9","difficulty":"medium","question":"Where did the brethren take Saul, and where did they send him?","options":["Down to Joppa, then out to Damascus","Down to Caesarea, then out to Tarsus","Down to Lydda, then out to Tarsus","Down to Caesarea, then out to Antioch"],"correct":1,"reference":"Acts 9:30","explanation":"They brought him down to Caesarea and sent him out to Tarsus — his home town, where Barnabas later goes to find him."},{"id":2211,"day":43,"category":"acts9","difficulty":"hard","question":"Which three regions had peace and were edified?","options":["Judea, Galilee, and Samaria","Galilee, Samaria, and Phoenicia","Judea, Galilee, and Cyprus","Judea, Samaria, and Syria"],"correct":0,"reference":"Acts 9:31","explanation":"'Then the churches throughout all Judea, Galilee, and Samaria had peace and were edified.'"},{"id":2212,"day":43,"category":"acts9","difficulty":"medium","question":"In what two things were the churches walking as they multiplied?","options":["Truth and grace","The fear of the Lord and the comfort of the Holy Spirit","Faith and love","Prayer and fasting"],"correct":1,"reference":"Acts 9:31","explanation":"'And walking in the fear of the Lord and in the comfort of the Holy Spirit, they were multiplied.'"},{"id":2213,"day":43,"category":"acts9","difficulty":"easy","question":"What was the name of the paralyzed man Peter found, and in which town?","options":["Tabitha, in Lydda","Aeneas, in Sharon","Aeneas, in Lydda","Aeneas, in Joppa"],"correct":2,"reference":"Acts 9:33","explanation":"'There he found a certain man named Aeneas' at Lydda. Remember: 'Aeneas, eight' — he had been bedridden eight years."},{"id":2214,"day":43,"category":"acts9","difficulty":"medium","question":"How long had Aeneas been bedridden?","options":["Three years","Twelve years","Forty years","Eight years"],"correct":3,"reference":"Acts 9:33","explanation":"He had been bedridden eight years and was paralyzed."},{"id":2215,"day":43,"category":"acts9","difficulty":"hard","question":"What did Peter say to Aeneas, and who saw him and turned to the Lord?","options":["'Jesus the Christ heals you. Arise and make your bed' — all who dwelt at Lydda and Sharon","'Rise up and walk' — all who dwelt at Lydda and Joppa","'In the name of Jesus, rise' — all who dwelt at Sharon","'Jesus the Christ heals you. Arise and walk' — all Jerusalem"],"correct":0,"reference":"Acts 9:34-35","explanation":"'Aeneas, Jesus the Christ heals you. Arise and make your bed.' All who dwelt at Lydda and Sharon saw him and turned to the Lord."},{"id":2216,"day":44,"category":"acts9","difficulty":"easy","question":"What was Tabitha's other name?","options":["Sapphira","Dorcas","Lydia","Gazelle"],"correct":1,"reference":"Acts 9:36","explanation":"At Joppa there was a disciple named Tabitha, which is translated Dorcas. The name means 'gazelle.'"},{"id":2217,"day":44,"category":"acts9","difficulty":"medium","question":"In which city did Tabitha live?","options":["Jerusalem","Lydda","Joppa","Caesarea"],"correct":2,"reference":"Acts 9:36","explanation":"'At Joppa there was a certain disciple named Tabitha.' Lydda was nearby, which is where Peter was."},{"id":2218,"day":44,"category":"acts9","difficulty":"medium","question":"How many men did the disciples send to Peter?","options":["Two","None — they sent a letter","Seven","Three"],"correct":0,"reference":"Acts 9:38","explanation":"They sent two men to him, imploring him not to delay in coming to them."},{"id":2219,"day":44,"category":"acts9","difficulty":"medium","question":"What did the widows show Peter?","options":["The food she had given them","The money she had saved","The house she had built","The tunics and garments which Dorcas made"],"correct":3,"reference":"Acts 9:39","explanation":"All the widows stood by him weeping, showing the tunics and garments which Dorcas had made while she was with them."},{"id":2220,"day":44,"category":"acts9","difficulty":"hard","question":"What did Peter do before he said 'Tabitha, arise'?","options":["He put them all out and knelt down and prayed","He wept over her","He anointed her with oil","He called the elders together"],"correct":0,"reference":"Acts 9:40","explanation":"'But Peter put them all out, and knelt down and prayed. And turning to the body he said, Tabitha, arise.'"},{"id":2221,"day":45,"category":"acts10","difficulty":"easy","question":"In which city did Cornelius live?","options":["Antioch","Lydda","Caesarea","Joppa"],"correct":2,"reference":"Acts 10:1","explanation":"'There was a certain man in Caesarea called Cornelius.'"},{"id":2222,"day":45,"category":"acts10","difficulty":"medium","question":"What was Cornelius's rank and regiment?","options":["A centurion of the Augustan Regiment","A captain of the Roman Guard","A centurion of the Italian Regiment","A commander of the Caesarean Legion"],"correct":2,"reference":"Acts 10:1","explanation":"A centurion of what was called the Italian Regiment."},{"id":2223,"day":45,"category":"acts10","difficulty":"hard","question":"Which four things describe Cornelius in verse 2?","options":["Faithful, humble, gave alms, and fasted often","Devout, feared God with all his household, gave alms generously, prayed to God always","Devout, a Jew, a soldier, and a father","Rich, generous, wise, and brave"],"correct":1,"reference":"Acts 10:2","explanation":"This full description is asked almost every year — learn all four parts together."},{"id":2224,"day":45,"category":"acts10","difficulty":"medium","question":"At what hour did Cornelius see the angel in a vision?","options":["Midnight","The third hour","The sixth hour","The ninth hour"],"correct":3,"reference":"Acts 10:3","explanation":"'About the ninth hour of the day he saw clearly in a vision an angel of God.' That is about 3 in the afternoon."},{"id":2225,"day":45,"category":"acts10","difficulty":"hard","question":"What did the angel say had come up for a memorial before God?","options":["His fasting and prayers","His prayers and his alms","His faith and his household","His good works"],"correct":1,"reference":"Acts 10:4","explanation":"'Your prayers and your alms have come up for a memorial before God.' Then he was told to send to Joppa for Simon Peter."},{"id":2226,"day":46,"category":"acts10","difficulty":"medium","question":"Where did Peter go to pray, and at what hour?","options":["In the temple, about the third hour","Up on the housetop, about the ninth hour","By the sea, about the sixth hour","Up on the housetop, about the sixth hour"],"correct":3,"reference":"Acts 10:9","explanation":"Peter went up on the housetop to pray, about the sixth hour — about noon. Learn the set: third hour (9am), sixth hour (noon), ninth hour (3pm)."},{"id":2227,"day":46,"category":"acts10","difficulty":"medium","question":"What did Peter see descending from heaven?","options":["An object like a great sheet bound at the four corners","A ladder reaching to heaven","A cloud full of fire","A scroll written on both sides"],"correct":0,"reference":"Acts 10:11","explanation":"He saw heaven opened and an object like a great sheet bound at the four corners, let down to the earth."},{"id":2228,"day":46,"category":"acts10","difficulty":"hard","question":"What kinds of creatures were in the sheet?","options":["Fish, birds, and creeping things","Four-footed animals, wild beasts, creeping things, and birds of the air","Sheep, oxen, and doves","Clean animals and birds only"],"correct":1,"reference":"Acts 10:12","explanation":"'In it were all kinds of four-footed animals of the earth, wild beasts, creeping things, and birds of the air.'"},{"id":2229,"day":46,"category":"acts10","difficulty":"easy","question":"What did the voice say to Peter?","options":["Go to Caesarea","Fear not, Peter","Come up here, Peter","Rise, Peter; kill and eat"],"correct":3,"reference":"Acts 10:13","explanation":"'And a voice came to him, Rise, Peter; kill and eat.' Peter refused, saying he had never eaten anything common or unclean."},{"id":2230,"day":46,"category":"acts10","difficulty":"medium","question":"What did the voice answer, and how many times was this done?","options":["'Do not question the Lord' — twice","'All things are lawful' — three times","'What God has cleansed you must not call common' — three times","'What God has cleansed you must not call common' — twice"],"correct":2,"reference":"Acts 10:15-16","explanation":"'What God has cleansed you must not call common.' This was done three times, and the object was taken up into heaven again."},{"id":2231,"day":47,"category":"acts10","difficulty":"medium","question":"Where were the men from Cornelius when Peter was still wondering about the vision?","options":["On the housetop with Peter","Waiting at the city entrance","At the seashore","Standing before the gate of Simon's house"],"correct":3,"reference":"Acts 10:17","explanation":"They had made inquiry for Simon's house and stood before the gate — the timing is exact."},{"id":2232,"day":47,"category":"acts10","difficulty":"medium","question":"How many men did the Spirit say were seeking Peter?","options":["Two","Three","Four","Six"],"correct":1,"reference":"Acts 10:19","explanation":"'Behold, three men are seeking you.' Cornelius had sent two household servants and a devout soldier."},{"id":2233,"day":47,"category":"acts10","difficulty":"hard","question":"What did the Spirit tell Peter to do?","options":["Go with them, doubting nothing, for I have sent them","Ask them their business first","Send them away and pray again","Wait until morning and then go"],"correct":0,"reference":"Acts 10:20","explanation":"'Arise therefore, go down and go with them, doubting nothing; for I have sent them.'"},{"id":2234,"day":47,"category":"acts10","difficulty":"hard","question":"How did the men describe Cornelius to Peter?","options":["A rich man of Caesarea","A powerful Roman officer","A just man who fears God and has a good reputation among all the nation of the Jews","A convert to the Jewish faith"],"correct":2,"reference":"Acts 10:22","explanation":"And they added that he 'was divinely instructed by a holy angel to summon you to his house, and to hear words from you.'"},{"id":2235,"day":47,"category":"acts10","difficulty":"medium","question":"Who accompanied Peter when he went with the men?","options":["John and James","The elders of the church","Some brethren from Joppa","The three messengers only"],"correct":2,"reference":"Acts 10:23","explanation":"'On the next day Peter went away with them, and some brethren from Joppa accompanied him.' Acts 11:12 tells us there were six of them."},{"id":2236,"day":48,"category":"acts10","difficulty":"medium","question":"Who had Cornelius called together to wait for Peter?","options":["The whole city","The soldiers of his regiment","The elders of Caesarea","His relatives and close friends"],"correct":3,"reference":"Acts 10:24","explanation":"Cornelius was waiting for them and had called together his relatives and close friends."},{"id":2237,"day":48,"category":"acts10","difficulty":"easy","question":"What did Cornelius do when Peter came in, and how did Peter respond?","options":["He knelt and wept; Peter prayed for him","He fell at his feet and worshiped; Peter lifted him up saying 'I myself am also a man'","He bowed and greeted him; Peter blessed him","He fell at his feet; Peter accepted his worship"],"correct":1,"reference":"Acts 10:25-26","explanation":"'Stand up; I myself am also a man.' Peter refuses worship straight away."},{"id":2238,"day":48,"category":"acts10","difficulty":"hard","question":"What had God shown Peter?","options":["That he should not call any man common or unclean","That he should travel to Rome","That the Gentiles would rule","That the law was ended"],"correct":0,"reference":"Acts 10:28","explanation":"The sheet was never really about food — it was about people. 'God has shown me that I should not call any man common or unclean.'"},{"id":2239,"day":48,"category":"acts10","difficulty":"hard","question":"How long before had Cornelius been fasting and praying when the man in bright clothing appeared?","options":["Three days ago, at the sixth hour","Four days ago, at the third hour","Four days ago, at the ninth hour","Two days ago, at the ninth hour"],"correct":2,"reference":"Acts 10:30","explanation":"'Four days ago I was fasting until this hour; and at the ninth hour I prayed in my house.'"},{"id":2240,"day":48,"category":"acts10","difficulty":"medium","question":"What did Cornelius say they were all present to do?","options":["To hear all the things commanded him by God","To see a miracle","To question Peter about the law","To be baptized at once"],"correct":0,"reference":"Acts 10:33","explanation":"'Now therefore, we are all present before God, to hear all the things commanded you by God.' A ready audience."},{"id":2241,"day":49,"category":"acts10","difficulty":"easy","question":"Complete Peter's words: 'In truth I perceive that God shows no ___.'","options":["anger","favour to the proud","weakness","partiality"],"correct":3,"reference":"Acts 10:34","explanation":"'God shows no partiality' — the theme sentence of the whole book, and the Week 10 memory verse."},{"id":2242,"day":49,"category":"acts10","difficulty":"hard","question":"Who is accepted by God, according to Peter?","options":["Those who are baptized in water","In every nation, whoever fears Him and works righteousness","Only those who keep the law of Moses","Those who are born of Israel"],"correct":1,"reference":"Acts 10:35","explanation":"'But in every nation whoever fears Him and works righteousness is accepted by Him.'"},{"id":2243,"day":49,"category":"acts10","difficulty":"medium","question":"With what did God anoint Jesus of Nazareth?","options":["Wisdom and with grace","The Spirit and with fire","The Holy Spirit and with power","Oil and with glory"],"correct":2,"reference":"Acts 10:38","explanation":"'How God anointed Jesus of Nazareth with the Holy Spirit and with power, who went about doing good and healing all who were oppressed by the devil.'"},{"id":2244,"day":49,"category":"acts10","difficulty":"medium","question":"On what day did God raise Jesus up?","options":["The first day","The seventh day","The third day","The eighth day"],"correct":2,"reference":"Acts 10:40","explanation":"'Him God raised up on the third day, and showed Him openly.'"},{"id":2245,"day":49,"category":"acts10","difficulty":"hard","question":"What did God ordain Jesus to be?","options":["Judge of the living and the dead","King of Israel","Lord of all nations","Prince and Savior"],"correct":0,"reference":"Acts 10:42","explanation":"'To testify that it is He who was ordained by God to be Judge of the living and the dead.'"},{"id":2246,"day":50,"category":"acts10","difficulty":"easy","question":"When did the Holy Spirit fall on those who heard?","options":["After Peter had prayed for them","On the next day","After they were baptized","While Peter was still speaking"],"correct":3,"reference":"Acts 10:44","explanation":"'While Peter was still speaking these words, the Holy Spirit fell upon all those who heard the word.' God did not even wait for the sermon to end."},{"id":2247,"day":50,"category":"acts10","difficulty":"medium","question":"How did those of the circumcision react?","options":["They left the house","They rejoiced","They were astonished","They objected loudly"],"correct":2,"reference":"Acts 10:45","explanation":"They were astonished, because the gift of the Holy Spirit had been poured out on the Gentiles also."},{"id":2248,"day":50,"category":"acts10","difficulty":"medium","question":"What did they hear the Gentiles doing?","options":["Weeping and confessing","Singing psalms","Speaking with tongues and magnifying God","Praying in Hebrew"],"correct":2,"reference":"Acts 10:46","explanation":"'For they heard them speak with tongues and magnify God' — the same sign as at Pentecost."},{"id":2249,"day":50,"category":"acts10","difficulty":"hard","question":"What question did Peter ask?","options":["Can anyone forbid water, that these should not be baptized?","Who among you will object to this?","Shall we not give thanks to God?","Who will teach these new believers?"],"correct":0,"reference":"Acts 10:47","explanation":"'Can anyone forbid water, that these should not be baptized who have received the Holy Spirit just as we have?'"},{"id":2250,"day":50,"category":"acts10","difficulty":"medium","question":"In whose name did Peter command them to be baptized?","options":["The Lord","The Father and the Son","The Holy Spirit","Jesus of Nazareth only"],"correct":0,"reference":"Acts 10:48","explanation":"'And he commanded them to be baptized in the name of the Lord. Then they asked him to stay a few days.'"},{"id":2251,"day":51,"category":"acts11","difficulty":"medium","question":"What did the apostles and brethren in Judea hear?","options":["That Cornelius had been baptized","That a famine was coming","That Peter had been arrested","That the Gentiles had also received the word of God"],"correct":3,"reference":"Acts 11:1","explanation":"News of the Gentile conversions reached Judea before Peter did."},{"id":2252,"day":51,"category":"acts11","difficulty":"medium","question":"What was the complaint against Peter?","options":["You left Jerusalem without leave","You preached without permission","You went in to uncircumcised men and ate with them!","You baptized without the apostles"],"correct":2,"reference":"Acts 11:3","explanation":"Those of the circumcision contended with him over eating with uncircumcised men."},{"id":2253,"day":51,"category":"acts11","difficulty":"medium","question":"How did Peter answer them?","options":["He referred them to James","He explained it to them in order from the beginning","He called witnesses to speak first","He rebuked them sharply"],"correct":1,"reference":"Acts 11:4","explanation":"'But Peter explained it to them in order from the beginning.' Calm and orderly — a good example."},{"id":2254,"day":51,"category":"acts11","difficulty":"medium","question":"In which city was Peter praying when he saw the vision?","options":["Joppa","Caesarea","Lydda","Jerusalem"],"correct":0,"reference":"Acts 11:5","explanation":"'I was in the city of Joppa praying; and in a trance I saw a vision.'"},{"id":2255,"day":51,"category":"acts11","difficulty":"hard","question":"How did Peter describe what he said to the voice?","options":["I am unworthy to eat before the Lord","Nothing common or unclean has at any time entered my mouth","I will do whatever You say","I have kept the law from my youth"],"correct":1,"reference":"Acts 11:8","explanation":"'But I said, Not so, Lord! For nothing common or unclean has at any time entered my mouth.'"},{"id":2256,"day":52,"category":"acts11","difficulty":"medium","question":"How many brethren accompanied Peter to the man's house?","options":["Two","Three","Twelve","Six"],"correct":3,"reference":"Acts 11:12","explanation":"'Moreover these six brethren accompanied me, and we entered the man's house.' Six witnesses — Peter brought proof."},{"id":2257,"day":52,"category":"acts11","difficulty":"hard","question":"What did the angel say Peter would tell Cornelius?","options":["The way of the Lord more perfectly","The story of Jesus of Nazareth","Words by which you and all your household will be saved","The commandments of God"],"correct":2,"reference":"Acts 11:14","explanation":"'Who will tell you words by which you and all your household will be saved.'"},{"id":2258,"day":52,"category":"acts11","difficulty":"medium","question":"Which word of the Lord did Peter remember?","options":["Go into all the world and preach","Feed My sheep","You shall be witnesses to Me","John indeed baptized with water, but you shall be baptized with the Holy Spirit"],"correct":3,"reference":"Acts 11:16","explanation":"He remembered the promise Jesus gave back in Acts 1:5 — the whole book keeps circling back to it."},{"id":2259,"day":52,"category":"acts11","difficulty":"hard","question":"How did Peter finish his defence?","options":["Who was I that I could withstand God?","Judge for yourselves what is right","What more can I say to you?","God has done a great thing"],"correct":0,"reference":"Acts 11:17","explanation":"'If therefore God gave them the same gift as He gave us… who was I that I could withstand God?'"},{"id":2260,"day":52,"category":"acts11","difficulty":"medium","question":"How did the brethren respond when they heard?","options":["They sent Peter back to Caesarea","They became silent and glorified God","They called a council at once","They argued further"],"correct":1,"reference":"Acts 11:18","explanation":"'Then God has also granted to the Gentiles repentance to life.' The argument was settled — for now."},{"id":2261,"day":53,"category":"acts11","difficulty":"hard","question":"How far did those scattered by the persecution over Stephen travel?","options":["As far as Egypt, Cyprus, and Rome","As far as Samaria, Galilee, and Syria","As far as Phoenicia, Cyrene, and Antioch","As far as Phoenicia, Cyprus, and Antioch"],"correct":3,"reference":"Acts 11:19","explanation":"Phoenicia, Cyprus, and Antioch — at first preaching to no one but the Jews only."},{"id":2262,"day":53,"category":"acts11","difficulty":"medium","question":"Men from which two places began preaching to the Hellenists at Antioch?","options":["Cyprus and Cilicia","Cyprus and Cyrene","Cilicia and Cyrene","Cyrene and Crete"],"correct":1,"reference":"Acts 11:20","explanation":"'But some of them were men from Cyprus and Cyrene, who, when they had come to Antioch, spoke to the Hellenists, preaching the Lord Jesus.'"},{"id":2263,"day":53,"category":"acts11","difficulty":"medium","question":"Whom did the church in Jerusalem send to Antioch?","options":["James","Silas","Peter","Barnabas"],"correct":3,"reference":"Acts 11:22","explanation":"They sent out Barnabas to go as far as Antioch. He was glad when he saw the grace of God and encouraged them all."},{"id":2264,"day":53,"category":"acts11","difficulty":"medium","question":"How is Barnabas described in verse 24?","options":["A bold man, full of courage","A good man, full of the Holy Spirit and of faith","A wise man, full of learning","A generous man, full of kindness"],"correct":1,"reference":"Acts 11:24","explanation":"'For he was a good man, full of the Holy Spirit and of faith. And a great many people were added to the Lord.'"},{"id":2265,"day":53,"category":"acts11","difficulty":"easy","question":"In which city were the disciples first called Christians?","options":["Caesarea","Damascus","Antioch","Jerusalem"],"correct":2,"reference":"Acts 11:26","explanation":"Barnabas fetched Saul from Tarsus, and for a whole year they taught there — 'And the disciples were first called Christians in Antioch.' One of the most-quizzed facts in Acts."},{"id":2266,"day":54,"category":"acts11","difficulty":"medium","question":"Who came from Jerusalem to Antioch in those days?","options":["Scribes","Apostles","Elders","Prophets"],"correct":3,"reference":"Acts 11:27","explanation":"'And in these days prophets came from Jerusalem to Antioch.'"},{"id":2267,"day":54,"category":"acts11","difficulty":"easy","question":"What was the name of the prophet who foretold a great famine?","options":["Ananias","Agabus","Silas","Manaen"],"correct":1,"reference":"Acts 11:28","explanation":"Agabus stood up and showed by the Spirit that there was going to be a great famine throughout all the world. Think 'A-GAB-us gabbed about the famine.'"},{"id":2268,"day":54,"category":"acts11","difficulty":"medium","question":"In whose days did the famine happen?","options":["Tiberius Caesar","Augustus Caesar","Herod the king","Claudius Caesar"],"correct":3,"reference":"Acts 11:28","explanation":"'Which also happened in the days of Claudius Caesar.'"},{"id":2269,"day":54,"category":"acts11","difficulty":"hard","question":"How did the disciples decide how much relief to send?","options":["By an equal share from each","By the decision of the elders","Each according to his ability","By casting lots"],"correct":2,"reference":"Acts 11:29","explanation":"'Then the disciples, each according to his ability, determined to send relief to the brethren dwelling in Judea.'"},{"id":2270,"day":54,"category":"acts11","difficulty":"medium","question":"By whose hands was the relief sent to the elders?","options":["Agabus and Silas","Barnabas and Mark","Barnabas and Saul","Peter and John"],"correct":2,"reference":"Acts 11:30","explanation":"'And sent it to the elders by the hands of Barnabas and Saul.'"},{"id":2271,"day":55,"category":"acts12","difficulty":"medium","question":"Who stretched out his hand to harass the church?","options":["Pontius Pilate","Herod the king","Caiaphas the high priest","Claudius Caesar"],"correct":1,"reference":"Acts 12:1","explanation":"'Now about that time Herod the king stretched out his hand to harass some from the church.'"},{"id":2272,"day":55,"category":"acts12","difficulty":"easy","question":"Whom did Herod kill with the sword?","options":["James the brother of John","Peter","James the brother of the Lord","Stephen"],"correct":0,"reference":"Acts 12:2","explanation":"James the brother of John. Careful — a different James speaks at the Jerusalem Council in Acts 15."},{"id":2273,"day":55,"category":"acts12","difficulty":"medium","question":"Why did Herod proceed to seize Peter also?","options":["Because the council demanded it","Because Peter preached in the temple","Because Peter had escaped before","Because he saw that killing James pleased the Jews"],"correct":3,"reference":"Acts 12:3","explanation":"'And because he saw that it pleased the Jews, he proceeded further to seize Peter also.'"},{"id":2274,"day":55,"category":"acts12","difficulty":"medium","question":"During which feast was Peter arrested?","options":["The Feast of Tabernacles","Pentecost","The Days of Unleavened Bread","The Day of Atonement"],"correct":2,"reference":"Acts 12:3","explanation":"'Now it was during the Days of Unleavened Bread.' Herod intended to bring him out after Passover."},{"id":2275,"day":55,"category":"acts12","difficulty":"hard","question":"To how many squads of soldiers was Peter delivered?","options":["Four squads","Three squads","Six squads","Two squads"],"correct":0,"reference":"Acts 12:4","explanation":"Four squads of soldiers to keep one man — Herod was taking no chances. And it still was not enough."},{"id":2276,"day":56,"category":"acts12","difficulty":"easy","question":"What was the church doing while Peter was kept in prison?","options":["They were planning his escape","Constant prayer was offered to God for him","They were hiding in fear","They were gathering money for his release"],"correct":1,"reference":"Acts 12:5","explanation":"'But constant prayer was offered to God for him by the church.' This is the Week 12 memory verse — the prayer is the real point of the story."},{"id":2277,"day":56,"category":"acts12","difficulty":"hard","question":"How was Peter guarded that night?","options":["Bound with two chains between two soldiers, with guards before the door","Bound with one chain between four soldiers","Locked alone in the inner prison","Chained to a wall with one guard"],"correct":0,"reference":"Acts 12:6","explanation":"Two chains, two soldiers, guards before the door — and he was sleeping! The whole escape is built on twos."},{"id":2278,"day":56,"category":"acts12","difficulty":"medium","question":"What happened when the angel struck Peter on the side?","options":["The doors flew open","A loud noise woke the guards","The prison shook","His chains fell off his hands"],"correct":3,"reference":"Acts 12:7","explanation":"A light shone in the prison, the angel said 'Arise quickly!' and his chains fell off his hands."},{"id":2279,"day":56,"category":"acts12","difficulty":"medium","question":"What did Peter think was happening as he followed the angel?","options":["He thought he was seeing a vision","He thought he was dreaming","He thought the guards had freed him","He thought he was being led to trial"],"correct":0,"reference":"Acts 12:9","explanation":"'And did not know that what was done by the angel was real, but thought he was seeing a vision.'"},{"id":2280,"day":56,"category":"acts12","difficulty":"hard","question":"How many guard posts did they pass, and what happened at the iron gate?","options":["One; it was already open","Two; it opened to them of its own accord","Two; Peter unlocked it","Three; the angel opened it"],"correct":1,"reference":"Acts 12:10","explanation":"Past the first and the second guard posts, then the iron gate that leads to the city opened to them of its own accord."},{"id":2281,"day":57,"category":"acts12","difficulty":"medium","question":"What did Peter say when he came to himself?","options":["Let me return and tell the guards","Now I know for certain that the Lord has sent His angel","Surely this is a dream","The Lord has answered my prayer"],"correct":1,"reference":"Acts 12:11","explanation":"'Now I know for certain that the Lord has sent His angel, and has delivered me from the hand of Herod.'"},{"id":2282,"day":57,"category":"acts12","difficulty":"hard","question":"To whose house did Peter go?","options":["The house of Barnabas","The house of Simon the tanner","The house of Mary, the mother of John whose surname was Mark","The house of Judas on Straight street"],"correct":2,"reference":"Acts 12:12","explanation":"Many were gathered there praying — for Peter, as it happens."},{"id":2283,"day":57,"category":"acts12","difficulty":"easy","question":"What was the name of the girl who came to answer the door?","options":["Mary","Tabitha","Sapphira","Rhoda"],"correct":3,"reference":"Acts 12:13","explanation":"A girl named Rhoda came to answer — and in her gladness she forgot to open the gate!"},{"id":2284,"day":57,"category":"acts12","difficulty":"medium","question":"What did the praying believers say to Rhoda?","options":["You are beside yourself!","Bring him in at once!","Go and look again","It cannot be true"],"correct":0,"reference":"Acts 12:15","explanation":"'You are beside yourself!' Then when she insisted, they said, 'It is his angel.' They were praying for him and still could not believe it."},{"id":2285,"day":57,"category":"acts12","difficulty":"medium","question":"What did Herod do when he searched for Peter and did not find him?","options":["He offered a reward","He examined the guards and commanded that they be put to death","He released the other prisoners","He sent soldiers to every city"],"correct":1,"reference":"Acts 12:19","explanation":"He examined the guards, had them put to death, then went down from Judea to Caesarea and stayed there."},{"id":2286,"day":58,"category":"acts12","difficulty":"hard","question":"With which two cities had Herod been very angry?","options":["Tyre and Sidon","Sidon and Caesarea","Tyre and Damascus","Tyre and Antioch"],"correct":0,"reference":"Acts 12:20","explanation":"The people of Tyre and Sidon asked for peace, because their country was supplied with food by the king's country."},{"id":2287,"day":58,"category":"acts12","difficulty":"hard","question":"Who was the king's personal aide whom they made their friend?","options":["Sergius","Elymas","Blastus","Manaen"],"correct":2,"reference":"Acts 12:20","explanation":"'Having made Blastus the king's personal aide their friend, they asked for peace.'"},{"id":2288,"day":58,"category":"acts12","difficulty":"medium","question":"What did the people shout at Herod's oration?","options":["Hail, Herod the great!","Long live the king!","He speaks with wisdom!","The voice of a god and not of a man!"],"correct":3,"reference":"Acts 12:22","explanation":"He was arrayed in royal apparel and sat on his throne, and the people kept shouting, 'The voice of a god and not of a man!'"},{"id":2289,"day":58,"category":"acts12","difficulty":"easy","question":"How did Herod die, and why?","options":["An angel struck him and he was eaten by worms, because he did not give glory to God","He was killed by soldiers for his cruelty","He was struck blind and died of grief","He died of fever in Caesarea"],"correct":0,"reference":"Acts 12:23","explanation":"Note the contrast: an angel freed Peter, and an angel struck Herod. Same word, opposite outcomes."},{"id":2290,"day":58,"category":"acts12","difficulty":"medium","question":"Whom did Barnabas and Saul take with them when they returned from Jerusalem?","options":["Timothy","John whose surname was Mark","Agabus","Silas"],"correct":1,"reference":"Acts 12:25","explanation":"They took John Mark — remember him; he causes the big argument in Acts 15."},{"id":2291,"day":59,"category":"acts13","difficulty":"hard","question":"Who were the prophets and teachers in the church at Antioch?","options":["Barnabas, Simeon called Niger, Luke of Cyrene, Manaen, and Saul","Barnabas, Simon Peter, Lucius, Manaen, and Saul","Barnabas, Simeon called Niger, Lucius of Cyrene, Manaen, and Saul","Barnabas, Silas, Lucius of Cyrene, Manaen, and Saul"],"correct":2,"reference":"Acts 13:1","explanation":"Chant it: 'Barnabas, Simeon, Lucius, Manaen, Saul.' Manaen had been brought up with Herod the tetrarch."},{"id":2292,"day":59,"category":"acts13","difficulty":"medium","question":"What did the Holy Spirit say while they ministered and fasted?","options":["Choose seven men to serve","Now separate to Me Barnabas and Saul for the work to which I have called them","Send Barnabas alone to Cyprus","Go to Jerusalem and wait"],"correct":1,"reference":"Acts 13:2","explanation":"The first missionary journey begins with the Holy Spirit's direct command."},{"id":2293,"day":59,"category":"acts13","difficulty":"medium","question":"What three things did the church do before sending them away?","options":["Prayed, anointed them, and blessed them","Prayed, sang, and blessed them","Fasted, gave money, and prayed","Fasted, prayed, and laid hands on them"],"correct":3,"reference":"Acts 13:3","explanation":"'Then, having fasted and prayed, and laid hands on them, they sent them away.'"},{"id":2294,"day":59,"category":"acts13","difficulty":"hard","question":"What were the sorcerer's two names?","options":["Bar-Jonah, also called Elymas","Bar-Jesus, also called Elymas","Bar-Jesus, also called Simon","Elymas, also called Blastus"],"correct":1,"reference":"Acts 13:6, 13:8","explanation":"A Jewish false prophet named Bar-Jesus; 'Elymas the sorcerer (for so his name is translated)' withstood them."},{"id":2295,"day":59,"category":"acts13","difficulty":"medium","question":"Who was the proconsul, and what happened to Elymas?","options":["Claudius Paulus; Elymas was struck dumb","Sergius Paulus; Elymas fled the island","Sergius Paulus; Elymas repented","Sergius Paulus; Elymas was struck blind for a time"],"correct":3,"reference":"Acts 13:7-11","explanation":"Sergius Paulus was an intelligent man who wanted to hear the word. A dark mist fell on Elymas, and the proconsul believed. Note verse 9: 'Saul, who also is called Paul' — the name switch happens here."},{"id":2296,"day":60,"category":"acts13","difficulty":"medium","question":"Where did John depart from the party and return to?","options":["He departed at Paphos and returned to Antioch","He departed at Perga and returned to Antioch","He departed at Perga and returned to Jerusalem","He departed at Cyprus and returned to Jerusalem"],"correct":2,"reference":"Acts 13:13","explanation":"At Perga in Pamphylia, John departed from them and returned to Jerusalem. This is exactly what Paul objects to in Acts 15:38."},{"id":2297,"day":60,"category":"acts13","difficulty":"medium","question":"On what day did Paul and his party go into the synagogue at Antioch in Pisidia?","options":["A feast day","The Sabbath day","The Day of Pentecost","The first day of the week"],"correct":1,"reference":"Acts 13:14","explanation":"'They came to Antioch in Pisidia, and went into the synagogue on the Sabbath day and sat down.'"},{"id":2298,"day":60,"category":"acts13","difficulty":"hard","question":"For about how long did God put up with Israel's ways in the wilderness?","options":["About seventy years","About four hundred and fifty years","About four hundred years","About forty years"],"correct":3,"reference":"Acts 13:18","explanation":"'Now for a time of about forty years He put up with their ways in the wilderness.' Do not mix it up with the 450 years of the judges in verse 20."},{"id":2299,"day":60,"category":"acts13","difficulty":"hard","question":"For about how many years did God give them judges, and until whom?","options":["About three hundred years, until Saul the king","About four hundred and fifty years, until Samuel the prophet","About four hundred years, until Samuel the prophet","About four hundred and fifty years, until David the king"],"correct":1,"reference":"Acts 13:20","explanation":"'After that He gave them judges for about four hundred and fifty years, until Samuel the prophet.'"},{"id":2300,"day":60,"category":"acts13","difficulty":"hard","question":"Who was Israel's first king — his father, tribe, and how long he reigned?","options":["Saul the son of Kish, of the tribe of Judah, for thirty years","Saul the son of Jesse, of the tribe of Judah, for forty years","David the son of Jesse, of the tribe of Benjamin, for forty years","Saul the son of Kish, of the tribe of Benjamin, for forty years"],"correct":3,"reference":"Acts 13:21","explanation":"'God gave them Saul the son of Kish, a man of the tribe of Benjamin, for forty years.' Then God raised up David, 'a man after My own heart.'"},{"id":2301,"day":61,"category":"acts13","difficulty":"hard","question":"Why did the rulers in Jerusalem condemn Him, according to Paul?","options":["Because they feared the Romans","Because they did not know Him, nor the voices of the Prophets read every Sabbath","Because they envied His miracles","Because the people demanded it"],"correct":1,"reference":"Acts 13:27","explanation":"In condemning Him they actually fulfilled the very prophecies they heard read every Sabbath."},{"id":2302,"day":61,"category":"acts13","difficulty":"medium","question":"Though they found no cause for death in Him, what did they ask Pilate?","options":["That He should be put to death","That He should be questioned","That He should be banished","That He should be beaten"],"correct":0,"reference":"Acts 13:28","explanation":"'And though they found no cause for death in Him, they asked Pilate that He should be put to death.'"},{"id":2303,"day":61,"category":"acts13","difficulty":"hard","question":"Which Psalm does Paul quote saying 'You are My Son, Today I have begotten You'?","options":["The sixteenth Psalm","The second Psalm","The first Psalm","The hundred and tenth Psalm"],"correct":1,"reference":"Acts 13:33","explanation":"'As it is also written in the second Psalm: You are My Son, Today I have begotten You.'"},{"id":2304,"day":61,"category":"acts13","difficulty":"medium","question":"What did David do that Jesus did not?","options":["He built the temple","He turned away from God","He fell asleep, was buried, and saw corruption","He refused to serve his generation"],"correct":2,"reference":"Acts 13:36-37","explanation":"'David, after he had served his own generation by the will of God, fell asleep… and saw corruption; but He whom God raised up saw no corruption.'"},{"id":2305,"day":61,"category":"acts13","difficulty":"medium","question":"What is preached through this Man?","options":["The day of judgment","The law of Moses","The kingdom of Israel","The forgiveness of sins"],"correct":3,"reference":"Acts 13:38","explanation":"'Through this Man is preached to you the forgiveness of sins' — and by Him everyone who believes is justified from all things."},{"id":2306,"day":62,"category":"acts13","difficulty":"medium","question":"What did the Gentiles beg for when the Jews went out of the synagogue?","options":["That Paul would stay in their homes","That these words might be preached to them the next Sabbath","That they might be baptized at once","That the rulers would not stop him"],"correct":1,"reference":"Acts 13:42","explanation":"They begged that the same words be preached the next Sabbath — and almost the whole city turned up."},{"id":2307,"day":62,"category":"acts13","difficulty":"medium","question":"Who came together on the next Sabbath?","options":["Almost the whole city","The rulers of the synagogue","A few devout proselytes","Only the Gentiles"],"correct":0,"reference":"Acts 13:44","explanation":"'On the next Sabbath almost the whole city came together to hear the word of God.'"},{"id":2308,"day":62,"category":"acts13","difficulty":"medium","question":"With what were the Jews filled when they saw the multitudes?","options":["Fear","Wonder","Envy","Anger at Rome"],"correct":2,"reference":"Acts 13:45","explanation":"'But when the Jews saw the multitudes, they were filled with envy; and contradicting and blaspheming, they opposed the things spoken by Paul.'"},{"id":2309,"day":62,"category":"acts13","difficulty":"hard","question":"What did Paul and Barnabas boldly declare?","options":["We shall go back to Jerusalem","We will never speak to you again","Since you reject it, behold, we turn to the Gentiles","God has rejected Israel forever"],"correct":2,"reference":"Acts 13:46","explanation":"'It was necessary that the word of God should be spoken to you first; but since you reject it… we turn to the Gentiles.'"},{"id":2310,"day":62,"category":"acts13","difficulty":"medium","question":"What did Paul and Barnabas do when they were expelled, and where did they go?","options":["They wept and returned to Antioch in Syria","They shook off the dust and came to Lystra","They appealed to the magistrates and stayed","They shook off the dust from their feet and came to Iconium"],"correct":3,"reference":"Acts 13:51","explanation":"They shook off the dust from their feet against them and came to Iconium — and the disciples were filled with joy and with the Holy Spirit."},{"id":2311,"day":63,"category":"acts14","difficulty":"medium","question":"What happened when they spoke in the synagogue at Iconium?","options":["A great multitude of both Jews and Greeks believed","Only the Greeks believed","They were thrown out immediately","The rulers forbade them to speak"],"correct":0,"reference":"Acts 14:1","explanation":"'They went together to the synagogue of the Jews, and so spoke that a great multitude both of the Jews and of the Greeks believed.'"},{"id":2312,"day":63,"category":"acts14","difficulty":"medium","question":"What did the unbelieving Jews do?","options":["They complained to the Roman governor","They stirred up the Gentiles and poisoned their minds against the brethren","They followed them to the next city","They prevented others from entering the synagogue"],"correct":1,"reference":"Acts 14:2","explanation":"'But the unbelieving Jews stirred up the Gentiles and poisoned their minds against the brethren.'"},{"id":2313,"day":63,"category":"acts14","difficulty":"hard","question":"What was the Lord doing while they stayed a long time speaking boldly?","options":["Protecting them from all harm","Sending them new helpers","Bearing witness to the word of His grace, granting signs and wonders by their hands","Opening the doors of every synagogue"],"correct":2,"reference":"Acts 14:3","explanation":"The Lord Himself was 'bearing witness to the word of His grace, granting signs and wonders to be done by their hands.'"},{"id":2314,"day":63,"category":"acts14","difficulty":"medium","question":"How was the multitude of the city divided?","options":["Part sided with the Jews, and part with the apostles","Part believed and part left the city","Part wanted to stone them and part to crown them","Part sided with Rome and part with the temple"],"correct":0,"reference":"Acts 14:4","explanation":"'But the multitude of the city was divided: part sided with the Jews, and part with the apostles.'"},{"id":2315,"day":63,"category":"acts14","difficulty":"hard","question":"To which two cities did they flee, and in what region were they?","options":["Lystra and Derbe, cities of Pisidia","Lystra and Attalia, cities of Lycaonia","Perga and Derbe, cities of Lycaonia","Lystra and Derbe, cities of Lycaonia"],"correct":3,"reference":"Acts 14:6","explanation":"They fled to Lystra and Derbe, cities of Lycaonia, and to the surrounding region — and kept preaching the gospel there."},{"id":2316,"day":64,"category":"acts14","difficulty":"hard","question":"How is the man at Lystra described?","options":["Without strength in his feet, a cripple from his mother's womb, who had never walked","Lame and over forty years old","Blind from birth and unable to speak","Paralyzed for eight years"],"correct":0,"reference":"Acts 14:8","explanation":"All three details matter. Do not confuse him with the lame man at the Beautiful Gate in Acts 3."},{"id":2317,"day":64,"category":"acts14","difficulty":"medium","question":"What did Paul see in the man before he healed him?","options":["That he was a believer already","That he was listening carefully","That he had faith to be healed","That he was suffering greatly"],"correct":2,"reference":"Acts 14:9","explanation":"'Paul, observing him intently and seeing that he had faith to be healed…' Then he said, 'Stand up straight on your feet!'"},{"id":2318,"day":64,"category":"acts14","difficulty":"medium","question":"What did the people cry out in the Lycaonian language?","options":["These men are servants of the Most High!","A prophet has risen among us!","The gods have come down to us in the likeness of men!","Let us make them our rulers!"],"correct":2,"reference":"Acts 14:11","explanation":"'The gods have come down to us in the likeness of men!' The apostles did not even understand at first — it was in the local language."},{"id":2319,"day":64,"category":"acts14","difficulty":"hard","question":"Which god did they call Barnabas, and which did they call Paul, and why?","options":["Barnabas Hermes, Paul Zeus, because Paul was the leader","Barnabas Zeus, Paul Hermes, because Paul was the chief speaker","Barnabas Hermes, Paul Zeus, because Barnabas was the chief speaker","Barnabas Zeus, Paul Apollo, because Paul was the healer"],"correct":1,"reference":"Acts 14:12","explanation":"Paul got the messenger god's name, Hermes, because he was the chief speaker. Barnabas was called Zeus."},{"id":2320,"day":64,"category":"acts14","difficulty":"medium","question":"What did the priest of Zeus bring, and how did the apostles react?","options":["Garlands and bread; they left the city at once","Oxen and wine; they accepted it and preached","Gold and incense; they refused it quietly","Oxen and garlands; they tore their clothes and ran in among the multitude"],"correct":3,"reference":"Acts 14:13-14","explanation":"They tore their clothes — a sign of horror — and cried out, 'We also are men with the same nature as you.'"},{"id":2321,"day":65,"category":"acts14","difficulty":"medium","question":"Who came to Lystra and stoned Paul?","options":["Jews from Jerusalem","The priest of Zeus and his servants","Jews from Antioch and Iconium","The rulers of Lystra"],"correct":2,"reference":"Acts 14:19","explanation":"'Then Jews from Antioch and Iconium came there; and having persuaded the multitudes, they stoned Paul.' They followed him from the earlier cities."},{"id":2322,"day":65,"category":"acts14","difficulty":"medium","question":"What did they suppose about Paul after stoning him?","options":["That he was only wounded","That he had fled","That he was dead","That he would never preach again"],"correct":2,"reference":"Acts 14:19","explanation":"They dragged him out of the city, supposing him to be dead — but when the disciples gathered around him, he rose up and went back into the city."},{"id":2323,"day":65,"category":"acts14","difficulty":"hard","question":"After Derbe, which three cities did they return to?","options":["Lystra, Iconium, and Antioch","Lystra, Perga, and Antioch","Iconium, Perga, and Attalia","Lystra, Iconium, and Cyprus"],"correct":0,"reference":"Acts 14:21","explanation":"They went back through the very cities where they had been attacked — that courage is the heart of the story."},{"id":2324,"day":65,"category":"acts14","difficulty":"easy","question":"Complete the verse: 'We must through many ___ enter the kingdom of God.'","options":["sufferings","tribulations","dangers","trials"],"correct":1,"reference":"Acts 14:22","explanation":"'We must through many tribulations enter the kingdom of God.' The Week 13 memory verse."},{"id":2325,"day":65,"category":"acts14","difficulty":"medium","question":"What did they do in every church before commending them to the Lord?","options":["Chose seven servants","Left them a written letter","Baptized all the new believers","Appointed elders and prayed with fasting"],"correct":3,"reference":"Acts 14:23","explanation":"'So when they had appointed elders in every church, and prayed with fasting, they commended them to the Lord in whom they had believed.'"},{"id":2326,"day":66,"category":"acts15","difficulty":"medium","question":"What did the men who came down from Judea teach?","options":["Unless you keep the Sabbath, you cannot be saved","You must be baptized by an apostle","Unless you are circumcised according to the custom of Moses, you cannot be saved","Gentiles cannot be saved at all"],"correct":2,"reference":"Acts 15:1","explanation":"That teaching is what set off the whole dispute and led to the Jerusalem Council."},{"id":2327,"day":66,"category":"acts15","difficulty":"medium","question":"How does the Bible describe the disagreement Paul and Barnabas had with them?","options":["No small dissension and dispute","A quiet disagreement","A brief misunderstanding","A friendly discussion"],"correct":0,"reference":"Acts 15:2","explanation":"'No small dissension and dispute' — a polite way of saying it was a serious argument."},{"id":2328,"day":66,"category":"acts15","difficulty":"medium","question":"Where were they sent, and to whom?","options":["Up to Jerusalem, to the apostles and elders","To Antioch, to the prophets","To Caesarea, to Peter","Up to Jerusalem, to James alone"],"correct":0,"reference":"Acts 15:2","explanation":"They went up to Jerusalem, to the apostles and elders, about this question."},{"id":2329,"day":66,"category":"acts15","difficulty":"hard","question":"Which regions did they pass through on the way, and what was the result?","options":["Galatia and Phrygia; they delivered the decrees","Phoenicia and Samaria; they caused great joy to all the brethren","Phoenicia and Cyprus; they preached to the Gentiles","Syria and Cilicia; they strengthened the churches"],"correct":1,"reference":"Acts 15:3","explanation":"They passed through Phoenicia and Samaria, describing the conversion of the Gentiles, and caused great joy to all the brethren."},{"id":2330,"day":66,"category":"acts15","difficulty":"medium","question":"Which group rose up at Jerusalem saying the Gentiles must be circumcised?","options":["The elders of Judea","The Sadducees","The scribes of the temple","Some of the sect of the Pharisees who believed"],"correct":3,"reference":"Acts 15:5","explanation":"'But some of the sect of the Pharisees who believed rose up, saying, It is necessary to circumcise them, and to command them to keep the law of Moses.'"},{"id":2331,"day":67,"category":"acts15","difficulty":"medium","question":"Who rose up and spoke first after much dispute?","options":["James","Barnabas","Peter","Paul"],"correct":2,"reference":"Acts 15:7","explanation":"Peter rose up and reminded them that God had chosen him to bring the gospel to the Gentiles — the Cornelius story from Acts 10."},{"id":2332,"day":67,"category":"acts15","difficulty":"hard","question":"How did God purify the Gentiles' hearts, according to Peter?","options":["By circumcision","By the law","By baptism","By faith"],"correct":3,"reference":"Acts 15:9","explanation":"God 'made no distinction between us and them, purifying their hearts by faith.'"},{"id":2333,"day":67,"category":"acts15","difficulty":"medium","question":"What did Peter call the demand being placed on the disciples?","options":["A heavy burden of gold","A yoke on the neck","A stumbling block","A chain of iron"],"correct":1,"reference":"Acts 15:10","explanation":"'Why do you test God by putting a yoke on the neck of the disciples which neither our fathers nor we were able to bear?'"},{"id":2334,"day":67,"category":"acts15","difficulty":"medium","question":"Who spoke after Barnabas and Paul had declared the miracles among the Gentiles?","options":["Silas","Judas Barsabas","James","Peter"],"correct":2,"reference":"Acts 15:13","explanation":"'And after they had become silent, James answered, saying, Men and brethren, listen to me.'"},{"id":2335,"day":67,"category":"acts15","difficulty":"hard","question":"What four things did James judge the Gentiles should abstain from?","options":["Idols, unclean meat, wine, and blood","Things polluted by idols, work on the Sabbath, blood, and strangled things","Idols, blood, theft, and immorality","Things polluted by idols, sexual immorality, things strangled, and blood"],"correct":3,"reference":"Acts 15:20","explanation":"Count them on four fingers: idols, immorality, strangled, blood. The same list appears again in verse 29."},{"id":2336,"day":68,"category":"acts15","difficulty":"hard","question":"Which two men were chosen to be sent to Antioch with Paul and Barnabas?","options":["Joseph Barsabas, and Silas","Judas also named Barsabas, and Silas","Judas Barsabas, and Timothy","Judas Iscariot, and Silas"],"correct":1,"reference":"Acts 15:22","explanation":"Judas also named Barsabas, and Silas — leading men among the brethren. Careful: a different Barsabas appeared back in Acts 1:23."},{"id":2337,"day":68,"category":"acts15","difficulty":"medium","question":"To whom was the letter addressed?","options":["All the believers scattered abroad","The elders at Antioch only","The churches of Judea and Samaria","The brethren who are of the Gentiles in Antioch, Syria, and Cilicia"],"correct":3,"reference":"Acts 15:23","explanation":"'To the brethren who are of the Gentiles in Antioch, Syria, and Cilicia: Greetings.'"},{"id":2338,"day":68,"category":"acts15","difficulty":"hard","question":"How did the letter describe Barnabas and Paul?","options":["Chosen apostles to the Gentiles","Men who have risked their lives for the name of our Lord Jesus Christ","Faithful servants of the church","Beloved teachers of the word"],"correct":1,"reference":"Acts 15:26","explanation":"'Our beloved Barnabas and Paul, men who have risked their lives for the name of our Lord Jesus Christ.'"},{"id":2339,"day":68,"category":"acts15","difficulty":"medium","question":"Complete the letter: 'For it seemed good to the ___, and to us, to lay upon you no greater burden.'","options":["Lord Jesus","elders","Holy Spirit","apostles"],"correct":2,"reference":"Acts 15:28","explanation":"'For it seemed good to the Holy Spirit, and to us, to lay upon you no greater burden than these necessary things.'"},{"id":2340,"day":68,"category":"acts15","difficulty":"medium","question":"How did the letter end?","options":["Grace and peace be with you all. Amen.","If you keep yourselves from these, you will do well. Farewell.","Obey these things and live. Farewell.","The Lord bless you and keep you."],"correct":1,"reference":"Acts 15:29","explanation":"'If you keep yourselves from these, you will do well. Farewell.'"},{"id":2341,"day":69,"category":"acts15","difficulty":"medium","question":"How did the church at Antioch react when they read the letter?","options":["They rejoiced over its encouragement","They were troubled by it","They sent it back to Jerusalem","They argued about it"],"correct":0,"reference":"Acts 15:31","explanation":"'When they had read it, they rejoiced over its encouragement.'"},{"id":2342,"day":69,"category":"acts15","difficulty":"medium","question":"What were Judas and Silas themselves?","options":["Scribes","Teachers of the law","Elders","Prophets"],"correct":3,"reference":"Acts 15:32","explanation":"'Now Judas and Silas, themselves being prophets also, exhorted and strengthened the brethren with many words.'"},{"id":2343,"day":69,"category":"acts15","difficulty":"easy","question":"Whom did Barnabas want to take, and why did Paul object?","options":["Timothy; he was too young","Silas; he was needed at Jerusalem","John called Mark; he had departed from them in Pamphylia","John called Mark; he was not a believer"],"correct":2,"reference":"Acts 15:37-38","explanation":"Paul insisted they not take 'the one who had departed from them in Pamphylia, and had not gone with them to the work.'"},{"id":2344,"day":69,"category":"acts15","difficulty":"medium","question":"How sharp did the contention become?","options":["Mild, and quickly settled","So sharp that the church had to judge it","So sharp that they parted from one another","Sharp, but they soon agreed"],"correct":2,"reference":"Acts 15:39","explanation":"'Then the contention became so sharp that they parted from one another.' Two good men disagreed — and God used both teams."},{"id":2345,"day":69,"category":"acts15","difficulty":"hard","question":"Who went with whom, and where?","options":["Barnabas took Silas to Cyprus; Paul took Mark to Syria","Barnabas took Mark to Cyprus; Paul chose Silas and went through Syria and Cilicia","Barnabas took Mark to Syria; Paul chose Silas and went to Cyprus","Barnabas took Mark to Antioch; Paul chose Timothy"],"correct":1,"reference":"Acts 15:39-41","explanation":"Draw it as a fork: Barnabas + Mark → Cyprus; Paul + Silas → Syria and Cilicia, strengthening the churches."},{"id":2346,"day":70,"category":"acts16","difficulty":"easy","question":"What were Timothy's parents?","options":["His mother was a Jewish woman who believed; his father was Greek","Both parents were Greek","Both parents were Jewish believers","His mother was Greek; his father was Jewish"],"correct":0,"reference":"Acts 16:1","explanation":"Jewish Mom, Greek Dad. This is asked almost every year."},{"id":2347,"day":70,"category":"acts16","difficulty":"medium","question":"By whom was Timothy well spoken of?","options":["The elders at Antioch","The churches of Galatia","The apostles at Jerusalem","The brethren at Lystra and Iconium"],"correct":3,"reference":"Acts 16:2","explanation":"'He was well spoken of by the brethren who were at Lystra and Iconium.'"},{"id":2348,"day":70,"category":"acts16","difficulty":"medium","question":"What did they deliver to the cities as they went through?","options":["Relief money for the famine","Letters of introduction from Antioch","The decrees determined by the apostles and elders at Jerusalem","Copies of the prophets"],"correct":2,"reference":"Acts 16:4","explanation":"'And as they went through the cities, they delivered to them the decrees to keep.' The churches were strengthened and increased in number daily."},{"id":2349,"day":70,"category":"acts16","difficulty":"hard","question":"Where were they forbidden by the Holy Spirit to preach, and where were they not permitted to go?","options":["Forbidden in Asia; not permitted into Macedonia","Forbidden in Asia; not permitted into Bithynia","Forbidden in Galatia; not permitted into Mysia","Forbidden in Bithynia; not permitted into Asia"],"correct":1,"reference":"Acts 16:6-7","explanation":"Forbidden by the Holy Spirit to preach in Asia; and at Mysia they tried to go into Bithynia, but the Spirit did not permit them. So they came down to Troas."},{"id":2350,"day":70,"category":"acts16","difficulty":"easy","question":"What did the man in Paul's night vision say?","options":["Come over to Macedonia and help us","Preach the word in Asia","Go back to Jerusalem","Follow me to Troas"],"correct":0,"reference":"Acts 16:9","explanation":"'A man of Macedonia stood and pleaded with him, saying, Come over to Macedonia and help us.' This is the moment the gospel crosses into Europe."},{"id":2351,"day":71,"category":"acts16","difficulty":"hard","question":"What was the route from Troas to Philippi?","options":["Troas to Thyatira, then Neapolis, then Philippi","Troas to Samothrace, then Neapolis, then Philippi","Troas to Neapolis, then Samothrace, then Philippi","Troas to Mysia, then Neapolis, then Philippi"],"correct":1,"reference":"Acts 16:11-12","explanation":"'Sailing from Troas, we ran a straight course to Samothrace, and the next day came to Neapolis, and from there to Philippi.'"},{"id":2352,"day":71,"category":"acts16","difficulty":"medium","question":"How is Philippi described?","options":["The capital city of all Macedonia","A small village by the river","The chief port of Macedonia","The foremost city of that part of Macedonia, a colony"],"correct":3,"reference":"Acts 16:12","explanation":"'Philippi, which is the foremost city of that part of Macedonia, a colony.'"},{"id":2353,"day":71,"category":"acts16","difficulty":"medium","question":"Where did they go on the Sabbath day, and whom did they speak to?","options":["Out of the city to the riverside, and spoke to the women who met there","To the synagogue, and spoke to the elders","To the city gate, and spoke to the magistrates","To the marketplace, and spoke to the crowds"],"correct":0,"reference":"Acts 16:13","explanation":"They went out to the riverside where prayer was customarily made, sat down, and spoke to the women who met there."},{"id":2354,"day":71,"category":"acts16","difficulty":"hard","question":"Who was Lydia — her trade and her city?","options":["A weaver of cloth from the city of Thyatira","A seller of purple from the city of Thyatira","A seller of purple from the city of Troas","A seller of linen from the city of Philippi"],"correct":1,"reference":"Acts 16:14","explanation":"A seller of purple from Thyatira, who worshiped God. Three facts, one woman: purple, Thyatira, and an opened heart."},{"id":2355,"day":71,"category":"acts16","difficulty":"medium","question":"Who opened Lydia's heart to heed the things spoken by Paul?","options":["The Lord","Her own searching","Paul's preaching","The women at the riverside"],"correct":0,"reference":"Acts 16:14","explanation":"'The Lord opened her heart to heed the things spoken by Paul.' Then she and her household were baptized."},{"id":2356,"day":72,"category":"acts16","difficulty":"medium","question":"What was the slave girl possessed with, and what did she bring her masters?","options":["An unclean spirit; great fame in the city","A lying spirit; much profit by trading","A spirit of divination; much profit by fortune-telling","A spirit of divination; great honour among the people"],"correct":2,"reference":"Acts 16:16","explanation":"'A certain slave girl possessed with a spirit of divination met us, who brought her masters much profit by fortune-telling.'"},{"id":2357,"day":72,"category":"acts16","difficulty":"medium","question":"What did the girl cry out, and for how long?","options":["'These men speak of a new god' — for many days","'These men are troublemakers' — for one day","'These men are Romans' — for several days","'These men are the servants of the Most High God' — for many days"],"correct":3,"reference":"Acts 16:17-18","explanation":"She followed them crying that they were servants of the Most High God who proclaim the way of salvation — and this she did for many days."},{"id":2358,"day":72,"category":"acts16","difficulty":"medium","question":"How did Paul feel, and what did he say?","options":["Greatly saddened; 'Be free, in the name of God'","Greatly annoyed; 'I command you in the name of Jesus Christ to come out of her'","Greatly amazed; 'Who has sent you?'","Greatly afraid; 'Depart from this place'"],"correct":1,"reference":"Acts 16:18","explanation":"'But Paul, greatly annoyed, turned and said to the spirit… And he came out that very hour.'"},{"id":2359,"day":72,"category":"acts16","difficulty":"medium","question":"Why did her masters seize Paul and Silas?","options":["Because their hope of profit was gone","Because they preached against Caesar","Because the girl had been harmed","Because they broke the Sabbath"],"correct":0,"reference":"Acts 16:19","explanation":"'But when her masters saw that their hope of profit was gone, they seized Paul and Silas and dragged them into the marketplace to the authorities.'"},{"id":2360,"day":72,"category":"acts16","difficulty":"hard","question":"What three things happened to Paul and Silas after the magistrates' order?","options":["Beaten with rods, thrown into the inner prison, feet fastened in the stocks","Beaten with rods, chained to soldiers, fed no food","Beaten with whips, thrown into a pit, hands bound","Stoned, imprisoned, and left for dead"],"correct":0,"reference":"Acts 16:22-24","explanation":"The magistrates tore off their clothes and had them beaten with rods; the jailer put them into the inner prison and fastened their feet in the stocks."},{"id":2361,"day":73,"category":"acts16","difficulty":"easy","question":"What were Paul and Silas doing at midnight, and who was listening?","options":["Praying quietly; no one was listening","Weeping and praying; the jailer was listening","Praying and singing hymns to God; the prisoners were listening","Sleeping soundly; the guards were watching"],"correct":2,"reference":"Acts 16:25","explanation":"'But at midnight Paul and Silas were praying and singing hymns to God, and the prisoners were listening to them.' Singing in the stocks!"},{"id":2362,"day":73,"category":"acts16","difficulty":"hard","question":"What three things happened in the earthquake?","options":["The prison collapsed and the prisoners escaped","The walls fell, the doors opened, and the guards fled","The foundations shook, the gate opened, and Paul's chains fell off","The foundations were shaken, all the doors were opened, and everyone's chains were loosed"],"correct":3,"reference":"Acts 16:26","explanation":"Foundations shaken, all the doors opened, everyone's chains loosed — and yet nobody ran."},{"id":2363,"day":73,"category":"acts16","difficulty":"medium","question":"Why was the keeper of the prison about to kill himself?","options":["He thought Paul and Silas were gods","He saw the doors open and supposed the prisoners had fled","He was afraid of the earthquake","He had been ordered to die"],"correct":1,"reference":"Acts 16:27","explanation":"Awaking from sleep and seeing the prison doors open, he supposed the prisoners had fled, and drew his sword."},{"id":2364,"day":73,"category":"acts16","difficulty":"medium","question":"What did Paul call out to him?","options":["Do yourself no harm, for we are all here","Put away your sword and listen","Fear not, for God is with you","Stop! The Lord has saved you"],"correct":0,"reference":"Acts 16:28","explanation":"'Do yourself no harm, for we are all here.' Nobody had run — and that is why the jailer believed."},{"id":2365,"day":73,"category":"acts16","difficulty":"easy","question":"What did the jailer ask, and what was the answer?","options":["'Who are you, sirs?' — 'We are servants of God'","'What must I do to be saved?' — 'Keep the law of Moses'","'What must I do to be saved?' — 'Believe on the Lord Jesus Christ'","'How did you escape?' — 'The Lord sent His angel'"],"correct":2,"reference":"Acts 16:30-31","explanation":"'Believe on the Lord Jesus Christ, and you will be saved, you and your household.' The Week 15 memory verse — learn it cold."},{"id":2366,"day":74,"category":"acts16","difficulty":"medium","question":"What did the magistrates send the officers to say when it was day?","options":["Let those men go","Keep them until Passover","Beat them once more","Bring those men before us"],"correct":0,"reference":"Acts 16:35","explanation":"'And when it was day, the magistrates sent the officers, saying, Let those men go.'"},{"id":2367,"day":74,"category":"acts16","difficulty":"medium","question":"Who reported the magistrates' words to Paul?","options":["The officers themselves","Lydia","Silas","The keeper of the prison"],"correct":3,"reference":"Acts 16:36","explanation":"'So the keeper of the prison reported these words to Paul, saying, The magistrates have sent to let you go.'"},{"id":2368,"day":74,"category":"acts16","difficulty":"hard","question":"What was Paul's objection?","options":["They had not apologized to Silas","They had beaten uncondemned Romans openly, and now wanted to put them out secretly","They had not paid them for their loss","They had not returned their clothing"],"correct":1,"reference":"Acts 16:37","explanation":"'They have beaten us openly, uncondemned Romans… And now do they put us out secretly? No indeed! Let them come themselves and get us out.'"},{"id":2369,"day":74,"category":"acts16","difficulty":"medium","question":"How did the magistrates feel when they heard Paul and Silas were Romans?","options":["They were amused","They were angry","They were relieved","They were afraid"],"correct":3,"reference":"Acts 16:38","explanation":"'And they were afraid when they heard that they were Romans.' Beating a Roman citizen uncondemned was a serious crime."},{"id":2370,"day":74,"category":"acts16","difficulty":"medium","question":"Whose house did Paul and Silas go to before departing?","options":["The house of the jailer","The house of the magistrates","The house of Lydia","The house by the riverside"],"correct":2,"reference":"Acts 16:40","explanation":"'So they went out of the prison and entered the house of Lydia; and when they had seen the brethren, they encouraged them and departed.' The chapter ends where it began — with Lydia."},{"id":2401,"day":1,"category":"acts1","difficulty":"medium","question":"Through whom had Jesus given commandments to the apostles He had chosen?","options":["The Holy Spirit","Moses","The prophets","The angels"],"correct":0,"reference":"Acts 1:2","explanation":"He gave commandments to the apostles 'through the Holy Spirit' before He was taken up. The Spirit is at work from the very first page of Acts."},{"id":2402,"day":1,"category":"acts1","difficulty":"medium","question":"What did the disciples ask Jesus about the kingdom?","options":["Who will be greatest in the kingdom?","Will You at this time restore the kingdom to Israel?","When will the kingdom come to the Gentiles?","Will You leave the kingdom to us?"],"correct":1,"reference":"Acts 1:6","explanation":"They were still thinking about an earthly kingdom for Israel. Jesus redirects them to the Holy Spirit and being witnesses instead."},{"id":2403,"day":1,"category":"acts1","difficulty":"hard","question":"How did Jesus answer their question about the kingdom?","options":["It is not for you to know times or seasons which the Father has put in His own authority","The kingdom will never be restored","Ask again after Pentecost","It is as you say"],"correct":0,"reference":"Acts 1:7","explanation":"Jesus does not answer the 'when'. He gives them a job instead — verse 8, the map of the whole book."},{"id":2404,"day":2,"category":"acts1","difficulty":"medium","question":"What did the two men in white tell the men of Galilee about Jesus?","options":["He will return within the year","He has gone to prepare a kingdom on earth","You will not see Him again","He will come in like manner as you saw Him go into heaven"],"correct":3,"reference":"Acts 1:11","explanation":"'Why do you stand gazing up into heaven? This same Jesus… will so come in like manner as you saw Him go.'"},{"id":2405,"day":2,"category":"acts1","difficulty":"hard","question":"Besides the apostles, who else was praying in the upper room?","options":["The women, Mary the mother of Jesus, and His brothers","The seventy disciples","Mary and Martha only","The elders of Jerusalem"],"correct":0,"reference":"Acts 1:14","explanation":"'These all continued with one accord in prayer and supplication, with the women and Mary the mother of Jesus, and with His brothers.'"},{"id":2406,"day":11,"category":"acts3","difficulty":"medium","question":"What did the lame man ask for when he saw Peter and John?","options":["Healing","Food","A blessing","Alms"],"correct":3,"reference":"Acts 3:3","explanation":"He asked for alms — money. He had no idea he was about to get something far better."},{"id":2407,"day":11,"category":"acts3","difficulty":"medium","question":"What did Peter say to the lame man before healing him?","options":["Do you believe?","Look at us","Rise and walk","What do you want?"],"correct":1,"reference":"Acts 3:4","explanation":"'And fixing his eyes on him, with John, Peter said, Look at us.' He wanted the man's full attention first."},{"id":2408,"day":11,"category":"acts3","difficulty":"medium","question":"What was the man expecting to receive from Peter and John?","options":["A place at the temple","Bread","Something — he gave them his attention","Nothing at all"],"correct":2,"reference":"Acts 3:5","explanation":"'So he gave them his attention, expecting to receive something from them.'"},{"id":2409,"day":11,"category":"acts3","difficulty":"hard","question":"Which two parts of the man's body received strength immediately?","options":["His legs and knees","His feet and hands","His knees and ankles","His feet and ankle bones"],"correct":3,"reference":"Acts 3:7","explanation":"'Immediately his feet and ankle bones received strength.' Luke was a doctor, and it shows in details like this."},{"id":2410,"day":11,"category":"acts3","difficulty":"medium","question":"How did the people feel when they recognized the healed beggar?","options":["Filled with wonder and amazement","Angry and suspicious","Doubtful","Afraid and silent"],"correct":0,"reference":"Acts 3:10","explanation":"They knew he was the one who sat begging at the Beautiful Gate, and 'they were filled with wonder and amazement.'"},{"id":2411,"day":12,"category":"acts3","difficulty":"hard","question":"Peter said they denied the Holy One and the Just, and asked for whom instead?","options":["A false prophet","A soldier","A thief","A murderer"],"correct":3,"reference":"Acts 3:14","explanation":"'But you denied the Holy One and the Just, and asked for a murderer to be granted to you' — a reference to Barabbas."},{"id":2412,"day":12,"category":"acts3","difficulty":"hard","question":"What made the lame man strong, according to Peter?","options":["Faith in the name of Jesus","The prayers of the apostles","Peter's own power","The holiness of the temple"],"correct":0,"reference":"Acts 3:16","explanation":"'And His name, through faith in His name, has made this man strong… the faith which comes through Him has given him this perfect soundness.'"},{"id":2413,"day":12,"category":"acts3","difficulty":"medium","question":"What had God foretold by the mouth of all His prophets?","options":["That the Gentiles would believe","That the temple would fall","That the Christ would suffer","That Israel would be restored"],"correct":2,"reference":"Acts 3:18","explanation":"'But those things which God foretold by the mouth of all His prophets, that the Christ would suffer, He has thus fulfilled.'"},{"id":2414,"day":12,"category":"acts3","difficulty":"hard","question":"What would happen to every soul who would not hear that Prophet?","options":["Utterly destroyed from among the people","Sent away from the temple","Left in ignorance","Judged at the last day"],"correct":0,"reference":"Acts 3:23","explanation":"'Every soul who will not hear that Prophet shall be utterly destroyed from among the people.' Peter is quoting Moses."},{"id":2415,"day":12,"category":"acts3","difficulty":"hard","question":"God sent His Servant Jesus to bless them by doing what?","options":["Turning every one of them away from their iniquities","Restoring the kingdom to Israel","Giving them the law","Rebuilding the temple"],"correct":0,"reference":"Acts 3:26","explanation":"'To you first, God… sent Him to bless you, in turning away every one of you from your iniquities.' The blessing is being turned from sin."},{"id":2416,"day":24,"category":"acts6","difficulty":"medium","question":"Who summoned the multitude of the disciples about the widows' complaint?","options":["Peter alone","The elders","The seven","The twelve"],"correct":3,"reference":"Acts 6:2","explanation":"'Then the twelve summoned the multitude of the disciples.' The apostles dealt with the complaint openly rather than ignoring it."},{"id":2417,"day":24,"category":"acts6","difficulty":"hard","question":"What did the twelve say it was not desirable for them to leave?","options":["Prayer, to teach","The temple, to travel","The word of God, to serve tables","Jerusalem, to go to Samaria"],"correct":2,"reference":"Acts 6:2","explanation":"'It is not desirable that we should leave the word of God and serve tables.' Not that serving tables was beneath them — it was that someone had to keep preaching."},{"id":2418,"day":24,"category":"acts6","difficulty":"medium","question":"What two things would the apostles give themselves continually to?","options":["The word and the breaking of bread","Prayer and fasting","Prayer and the ministry of the word","Teaching and healing"],"correct":2,"reference":"Acts 6:4","explanation":"'But we will give ourselves continually to prayer and to the ministry of the word.'"},{"id":2419,"day":24,"category":"acts6","difficulty":"medium","question":"What did the apostles do after the seven were set before them?","options":["They prayed and laid hands on them","They anointed them with oil","They sent them out at once","They gave them the money"],"correct":0,"reference":"Acts 6:6","explanation":"'Whom they set before the apostles; and when they had prayed, they laid hands on them.'"},{"id":2420,"day":24,"category":"acts6","difficulty":"hard","question":"Which group is specially mentioned as becoming obedient to the faith?","options":["The elders of the synagogue","A great many of the priests","The Pharisees","The Roman soldiers"],"correct":1,"reference":"Acts 6:7","explanation":"'And a great many of the priests were obedient to the faith.' A striking detail — the very group that opposed the apostles began to believe."},{"id":2421,"day":24,"category":"acts6","difficulty":"medium","question":"What happened to the word of God after the seven were appointed?","options":["It went out to Samaria","It was silenced for a time","It was written down","It spread, and the disciples multiplied greatly in Jerusalem"],"correct":3,"reference":"Acts 6:7","explanation":"Solving the widows' problem freed the apostles to preach — and the church grew. Good organisation served the gospel."},{"id":2422,"day":25,"category":"acts6","difficulty":"hard","question":"Which three groups did Stephen's opponents stir up against him?","options":["The priests, the scribes, and the Sadducees","The elders, the scribes, and the Romans","The people, the elders, and the scribes","The people, the Pharisees, and the elders"],"correct":2,"reference":"Acts 6:12","explanation":"'And they stirred up the people, the elders, and the scribes; and they came upon him, seized him, and brought him to the council.'"},{"id":2423,"day":25,"category":"acts6","difficulty":"medium","question":"What did the false witnesses say Stephen spoke against?","options":["Caesar and the council","This holy place and the law","Moses and the prophets","The temple and the priests"],"correct":1,"reference":"Acts 6:13","explanation":"'This man does not cease to speak blasphemous words against this holy place and the law.'"},{"id":2424,"day":25,"category":"acts6","difficulty":"hard","question":"What did the witnesses claim Stephen said Jesus of Nazareth would do?","options":["Destroy this place and change the customs Moses delivered","Abolish the law of Moses","Rebuild the temple in three days","Drive out the Romans"],"correct":0,"reference":"Acts 6:14","explanation":"'For we have heard him say that this Jesus of Nazareth will destroy this place and change the customs which Moses delivered to us.'"},{"id":2425,"day":25,"category":"acts6","difficulty":"medium","question":"Why were Stephen's opponents unable to win the argument with him?","options":["The council forbade it","They could not resist the wisdom and the Spirit by which he spoke","He refused to answer them","The crowd protected him"],"correct":1,"reference":"Acts 6:10","explanation":"They could not beat him fairly, so they set up false witnesses instead."},{"id":2426,"day":24,"category":"acts6","difficulty":"easy","question":"How many men were chosen to serve, and what was the first name on the list?","options":["Seven, beginning with Philip","Twelve, beginning with Philip","Five, beginning with Stephen","Seven, beginning with Stephen"],"correct":3,"reference":"Acts 6:5","explanation":"Seven men, and Stephen is named first — 'a man full of faith and the Holy Spirit.'"},{"id":2427,"day":24,"category":"acts6","difficulty":"hard","question":"Whose widows were being neglected in the daily distribution?","options":["The Hebrews'","The Hellenists'","The proselytes'","The Samaritans'"],"correct":1,"reference":"Acts 6:1","explanation":"The complaint came from the Hellenists (Greek-speaking Jews) against the Hebrews, because the Hellenists' widows were being overlooked."},{"id":2428,"day":25,"category":"acts6","difficulty":"medium","question":"How is Stephen described when he did great wonders and signs?","options":["Full of faith and power","Full of courage","Full of grace and truth","Full of wisdom and years"],"correct":0,"reference":"Acts 6:8","explanation":"'And Stephen, full of faith and power, did great wonders and signs among the people.'"},{"id":2429,"day":25,"category":"acts6","difficulty":"hard","question":"Members of which synagogue began disputing with Stephen?","options":["The Great Synagogue","The Synagogue of the Freedmen","The Synagogue of the Hellenists","The Synagogue of the Elders"],"correct":1,"reference":"Acts 6:9","explanation":"The Synagogue of the Freedmen, which included Cyrenians, Alexandrians, and men from Cilicia and Asia."},{"id":2430,"day":25,"category":"acts6","difficulty":"easy","question":"What did the council see when they looked at Stephen's face?","options":["It shone like the sun","It was turned away","It was like the face of an angel","It was full of fear"],"correct":2,"reference":"Acts 6:15","explanation":"'All who sat in the council, looking steadfastly at him, saw his face as the face of an angel.' The chapter ends on that image."},{"id":2431,"day":51,"category":"acts11","difficulty":"medium","question":"Who contended with Peter when he came up to Jerusalem?","options":["The Pharisees","The apostles","The elders of Judea","Those of the circumcision"],"correct":3,"reference":"Acts 11:2","explanation":"'And when Peter came up to Jerusalem, those of the circumcision contended with him.'"},{"id":2432,"day":52,"category":"acts11","difficulty":"hard","question":"In Peter's retelling, how many times was the vision repeated?","options":["Twice","Three times","Seven times","Once"],"correct":1,"reference":"Acts 11:10","explanation":"'Now this was done three times, and all were drawn up again into heaven.' The same detail as Acts 10:16."},{"id":2433,"day":52,"category":"acts11","difficulty":"medium","question":"How many men stood before the house at that very moment, and where were they from?","options":["Three men, sent from Caesarea","Three men, sent from Jerusalem","Four men, sent from Caesarea","Two men, sent from Joppa"],"correct":0,"reference":"Acts 11:11","explanation":"'At that very moment, three men stood before the house where I was, having been sent to me from Caesarea.' The timing is the point."},{"id":2434,"day":52,"category":"acts11","difficulty":"medium","question":"When did the Holy Spirit fall on Cornelius's household, in Peter's account?","options":["After he had finished preaching","After they were baptized","As he began to speak","The next morning"],"correct":2,"reference":"Acts 11:15","explanation":"'And as I began to speak, the Holy Spirit fell upon them, as upon us at the beginning.'"},{"id":2435,"day":53,"category":"acts11","difficulty":"medium","question":"What was with the men preaching at Antioch, so that a great number believed?","options":["The letters of the elders","The power of signs","The hand of the Lord","The blessing of the apostles"],"correct":2,"reference":"Acts 11:21","explanation":"'And the hand of the Lord was with them, and a great number believed and turned to the Lord.'"},{"id":2436,"day":56,"category":"acts12","difficulty":"medium","question":"What did the angel tell Peter to do before following him out?","options":["Leave everything behind","Take the keys","Wake the other prisoners","Gird yourself and tie on your sandals"],"correct":3,"reference":"Acts 12:8","explanation":"'Gird yourself and tie on your sandals… Put on your garment and follow me.' Remarkably calm instructions for a jailbreak."},{"id":2437,"day":57,"category":"acts12","difficulty":"medium","question":"Why did Rhoda not open the gate?","options":["Because of her gladness","Because she did not recognize him","Because she was afraid","Because it was locked"],"correct":0,"reference":"Acts 12:14","explanation":"She recognized Peter's voice and was so glad she ran back inside to tell everyone, leaving him standing outside knocking."},{"id":2438,"day":57,"category":"acts12","difficulty":"medium","question":"How did the praying believers react when they finally opened the door?","options":["They ran away","They fell down and worshiped","They rejoiced quietly","They were astonished"],"correct":3,"reference":"Acts 12:16","explanation":"'Now Peter continued knocking; and when they opened the door and saw him, they were astonished.' They had prayed for exactly this."},{"id":2439,"day":57,"category":"acts12","difficulty":"hard","question":"Whom did Peter say to tell about his escape?","options":["The apostles only","Mary and Rhoda","James and the brethren","The elders at Antioch"],"correct":2,"reference":"Acts 12:17","explanation":"'Go, tell these things to James and to the brethren.' Then he departed and went to another place."},{"id":2440,"day":57,"category":"acts12","difficulty":"medium","question":"What happened among the soldiers as soon as it was day?","options":["There was no small stir about what had become of Peter","They searched the prison quietly","They reported to the high priest","They fled the city"],"correct":0,"reference":"Acts 12:18","explanation":"'There was no small stir among the soldiers about what had become of Peter' — Luke's way of saying there was uproar."},{"id":2441,"day":59,"category":"acts13","difficulty":"medium","question":"Who sent Barnabas and Saul out, and where did they sail from?","options":["The apostles; they sailed from Joppa to Cyprus","The church at Jerusalem; they sailed from Antioch","The Holy Spirit; they sailed from Caesarea to Crete","The Holy Spirit; they went down to Seleucia and sailed to Cyprus"],"correct":3,"reference":"Acts 13:4","explanation":"'So, being sent out by the Holy Spirit, they went down to Seleucia, and from there they sailed to Cyprus.'"},{"id":2442,"day":59,"category":"acts13","difficulty":"hard","question":"In which city on Cyprus did they first preach, and who was their assistant?","options":["Salamis; John was their assistant","Paphos; John was their assistant","Paphos; Silas was their assistant","Salamis; Silas was their assistant"],"correct":0,"reference":"Acts 13:5","explanation":"'And when they arrived in Salamis, they preached the word of God in the synagogues of the Jews. They also had John as their assistant.'"},{"id":2443,"day":59,"category":"acts13","difficulty":"hard","question":"At which verse does Luke first call Saul by the name Paul?","options":["When he was converted on the Damascus road","When Barnabas fetched him from Tarsus","When he preached at Antioch in Pisidia","When he confronted Elymas the sorcerer"],"correct":3,"reference":"Acts 13:9","explanation":"'Then Saul, who also is called Paul, filled with the Holy Spirit, looked intently at him.' From here on Luke calls him Paul."},{"id":2444,"day":60,"category":"acts13","difficulty":"medium","question":"How did God describe David?","options":["A shepherd of My people","A man of war and of peace","A man after My own heart, who will do all My will","A king like no other"],"correct":2,"reference":"Acts 13:22","explanation":"'I have found David the son of Jesse, a man after My own heart, who will do all My will.'"},{"id":2445,"day":60,"category":"acts13","difficulty":"hard","question":"What did John say he was not worthy to do?","options":["Enter the kingdom","Loose the sandals of the feet of the One coming after him","Baptize the Messiah","Speak the name of the Christ"],"correct":1,"reference":"Acts 13:25","explanation":"'There comes One after me, the sandals of whose feet I am not worthy to loose.'"},{"id":2446,"day":62,"category":"acts13","difficulty":"medium","question":"What did the Lord command, according to Paul's quotation?","options":["Preach the law to all nations","Wait in Jerusalem for power","Go first to the lost sheep of Israel","I have set you as a light to the Gentiles, for salvation to the ends of the earth"],"correct":3,"reference":"Acts 13:47","explanation":"That quotation is why Paul turns to the Gentiles — he sees it as a direct command, not a change of plan."},{"id":2447,"day":62,"category":"acts13","difficulty":"medium","question":"How did the Gentiles respond when they heard they were included?","options":["They were glad and glorified the word of the Lord","They argued with the Jews","They were silent","They asked for a sign"],"correct":0,"reference":"Acts 13:48","explanation":"'Now when the Gentiles heard this, they were glad and glorified the word of the Lord. And as many as had been appointed to eternal life believed.'"},{"id":2448,"day":62,"category":"acts13","difficulty":"hard","question":"Whom did the Jews stir up to raise persecution against Paul and Barnabas?","options":["The Roman soldiers and magistrates","The priests of the temple","The whole multitude of the synagogue","The devout and prominent women and the chief men of the city"],"correct":3,"reference":"Acts 13:50","explanation":"'But the Jews stirred up the devout and prominent women and the chief men of the city… and expelled them from their region.'"},{"id":2449,"day":63,"category":"acts14","difficulty":"medium","question":"What did the Gentiles and Jews with their rulers violently attempt at Iconium?","options":["To abuse and stone them","To imprison them","To expel them quietly","To bribe them"],"correct":0,"reference":"Acts 14:5","explanation":"'And when a violent attempt was made by both the Gentiles and Jews, with their rulers, to abuse and stone them' — so they fled to Lystra and Derbe."},{"id":2450,"day":64,"category":"acts14","difficulty":"medium","question":"What did Paul say with a loud voice to the lame man at Lystra?","options":["In the name of Jesus, be healed!","Stand up straight on your feet!","Your faith has made you well!","Rise up and walk!"],"correct":1,"reference":"Acts 14:10","explanation":"'Said with a loud voice, Stand up straight on your feet! And he leaped and walked.'"},{"id":2451,"day":64,"category":"acts14","difficulty":"hard","question":"What did Barnabas and Paul do when they heard the crowd calling them gods?","options":["They tore their clothes and ran in among the multitude","They rebuked the priest of Zeus","They left the city at once","They accepted the honour quietly"],"correct":0,"reference":"Acts 14:14","explanation":"Tearing your clothes was a sign of horror. They were appalled, not flattered."},{"id":2452,"day":64,"category":"acts14","difficulty":"hard","question":"How did Paul describe the living God to the crowd at Lystra?","options":["Who chose Israel above all nations","Who dwells in the temple at Jerusalem","Who made the heaven, the earth, the sea, and all things in them","Who sent His Son into the world"],"correct":2,"reference":"Acts 14:15","explanation":"Speaking to people with no Bible background, Paul starts with creation rather than with Israel's history."},{"id":2453,"day":64,"category":"acts14","difficulty":"hard","question":"What witness did Paul say God had left of Himself among the nations?","options":["He gave them kings and rulers","He sent prophets to every land","He wrote His law on their hearts","He did good, gave rain from heaven and fruitful seasons"],"correct":3,"reference":"Acts 14:17","explanation":"'Nevertheless He did not leave Himself without witness, in that He did good, gave us rain from heaven and fruitful seasons, filling our hearts with food and gladness.'"},{"id":2454,"day":65,"category":"acts14","difficulty":"medium","question":"What did Paul do the very day after being stoned and left for dead?","options":["He departed with Barnabas to Derbe","He rested at Lystra for a week","He returned to Antioch","He sailed for Cyprus"],"correct":0,"reference":"Acts 14:20","explanation":"He rose up, went back into the city, and the next day set off for Derbe. Remarkable toughness."},{"id":2455,"day":65,"category":"acts14","difficulty":"hard","question":"Which two places did they pass through after Pisidia, before sailing?","options":["Cilicia, then Attalia","Pamphylia, then Perga and Attalia","Lycaonia, then Perga","Galatia, then Perga"],"correct":1,"reference":"Acts 14:24-25","explanation":"'After they had passed through Pisidia, they came to Pamphylia. Now when they had preached the word in Perga, they went down to Attalia.'"},{"id":2456,"day":65,"category":"acts14","difficulty":"medium","question":"What did they report when they gathered the church at Antioch together?","options":["That the Gentiles had rejected the word","That they had been persecuted everywhere","All that God had done with them, and that He had opened the door of faith to the Gentiles","That they needed more workers"],"correct":2,"reference":"Acts 14:27","explanation":"'He had opened the door of faith to the Gentiles' — that phrase is what sets up the argument in chapter 15."},{"id":2457,"day":65,"category":"acts14","difficulty":"medium","question":"How long did they stay at Antioch after the journey?","options":["Three days","Until the next Passover","A long time with the disciples","One year"],"correct":2,"reference":"Acts 14:28","explanation":"'So they stayed there a long time with the disciples.' The first missionary journey ends where it began."},{"id":2458,"day":63,"category":"acts14","difficulty":"medium","question":"After fleeing Iconium, what did Paul and Barnabas keep doing?","options":["Looking for a ship","Waiting quietly","Writing letters","Preaching the gospel"],"correct":3,"reference":"Acts 14:7","explanation":"'And they were preaching the gospel there.' Being driven out of one city simply moved the preaching to the next."},{"id":2459,"day":66,"category":"acts15","difficulty":"medium","question":"Who received Paul and Barnabas when they came to Jerusalem?","options":["The elders and the scribes","The church, the apostles, and the elders","The apostles only","James alone"],"correct":1,"reference":"Acts 15:4","explanation":"'They were received by the church and the apostles and the elders; and they reported all things that God had done with them.'"},{"id":2460,"day":67,"category":"acts15","difficulty":"medium","question":"How does Peter say God acknowledged the Gentiles?","options":["By giving them the Holy Spirit, just as He did to us","By giving them the law","By working miracles among them","By sending them prophets"],"correct":0,"reference":"Acts 15:8","explanation":"'So God, who knows the heart, acknowledged them by giving them the Holy Spirit, just as He did to us.'"},{"id":2461,"day":67,"category":"acts15","difficulty":"hard","question":"Complete Peter's conclusion: 'Through the grace of the Lord Jesus Christ we shall be saved in the same manner as ___.'","options":["our fathers","the prophets","they","the apostles"],"correct":2,"reference":"Acts 15:11","explanation":"'We shall be saved in the same manner as they' — Peter puts Jewish believers and Gentile believers on exactly the same footing."},{"id":2462,"day":67,"category":"acts15","difficulty":"medium","question":"What did the multitude do while Barnabas and Paul spoke?","options":["They argued among themselves","They kept silent and listened","They praised God aloud","They demanded a vote"],"correct":1,"reference":"Acts 15:12","explanation":"'Then all the multitude kept silent and listened to Barnabas and Paul declaring how many miracles and wonders God had worked through them among the Gentiles.'"},{"id":2463,"day":67,"category":"acts15","difficulty":"hard","question":"By what name does James refer to Peter at the council?","options":["The rock","Simon Peter","Cephas","Simon"],"correct":3,"reference":"Acts 15:14","explanation":"'Simon has declared how God at the first visited the Gentiles to take out of them a people for His name.'"},{"id":2464,"day":67,"category":"acts15","difficulty":"medium","question":"What was James's judgment about the Gentiles turning to God?","options":["That they should wait a year","That they should not be troubled","That they must keep the whole law","That they should be tested first"],"correct":1,"reference":"Acts 15:19","explanation":"'Therefore I judge that we should not trouble those from among the Gentiles who are turning to God.'"},{"id":2465,"day":68,"category":"acts15","difficulty":"hard","question":"What did the letter say about those who had troubled the Gentile believers?","options":["They were false brethren from Antioch","They spoke with the elders' approval","They went out from us, but we gave them no such commandment","They were sent by the apostles"],"correct":2,"reference":"Acts 15:24","explanation":"The council disowns them plainly: 'to whom we gave no such commandment.'"},{"id":2501,"day":1,"category":"acts1","difficulty":"medium","question":"Luke says his former account covered all that Jesus began to do and to do what else?","options":["Write","Build","Teach","Judge"],"correct":2,"reference":"Acts 1:1","explanation":"\"All that Jesus began both to do and teach.\" Do AND teach - Jesus lived it before He taught it, and Acts is the story of His followers doing the same."},{"id":2502,"day":1,"category":"acts1","difficulty":"hard","question":"Luke's account runs until which day?","options":["The day Jesus was taken up","The day of Pentecost","The day Stephen died","The day Paul reached Rome"],"correct":0,"reference":"Acts 1:2","explanation":"\"Until the day in which He was taken up.\" The Gospel of Luke ends where Acts begins - the ascension is the hinge between the two books."},{"id":2503,"day":1,"category":"acts1","difficulty":"medium","question":"By what did Jesus present Himself alive after His suffering?","options":["A written decree","Signs in the sky","The testimony of angels","Many infallible proofs"],"correct":3,"reference":"Acts 1:3","explanation":"\"By many infallible proofs.\" Infallible means it cannot fail or be wrong - the resurrection was not a rumour, it was demonstrated over forty days."},{"id":2504,"day":1,"category":"acts1","difficulty":"medium","question":"What were the apostles told to wait in Jerusalem for?","options":["The return of the King","The Promise of the Father","A letter from Rome","The rebuilding of the temple"],"correct":1,"reference":"Acts 1:4","explanation":"\"Wait for the Promise of the Father.\" They were not told to go yet - first wait, then witness. The waiting is what makes Acts 2 possible."},{"id":2505,"day":1,"category":"acts1","difficulty":"easy","question":"What did John baptize with?","options":["Wind","Water","Oil","Fire"],"correct":1,"reference":"Acts 1:5","explanation":"\"For John truly baptized with water.\" Water was John's baptism; the Holy Spirit would be theirs. Same word, bigger promise."},{"id":2506,"day":1,"category":"acts1","difficulty":"hard","question":"What did Jesus say the Father has put in His own authority?","options":["The names of the apostles","Signs and wonders","The gates of the city","Times or seasons"],"correct":3,"reference":"Acts 1:7","explanation":"\"It is not for you to know times or seasons which the Father has put in His own authority.\" They asked WHEN; Jesus answered with WHO - the timing belongs to the Father."},{"id":2507,"day":1,"category":"acts1","difficulty":"easy","question":"What would they receive when the Holy Spirit came upon them?","options":["Rest","Riches","Power","A kingdom"],"correct":2,"reference":"Acts 1:8","explanation":"\"You shall receive power when the Holy Spirit has come upon you.\" Power first, then witness - the memory verse of week one."},{"id":2508,"day":1,"category":"acts1","difficulty":"medium","question":"How were the two men who stood by the disciples dressed?","options":["In white apparel","In linen robes","In shining armour","In traveller's cloaks"],"correct":0,"reference":"Acts 1:10","explanation":"\"Two men stood by them in white apparel.\" White apparel is Luke's signal for a heavenly messenger - the same detail appears at the empty tomb."},{"id":2509,"day":1,"category":"acts1","difficulty":"hard","question":"How did the two men say Jesus would come again?","options":["In secret, at midnight","In like manner as they saw Him go","Before that generation passed","Only to the apostles"],"correct":1,"reference":"Acts 1:11","explanation":"\"Will so come in like manner as you saw Him go into heaven.\" He left visibly, bodily, in a cloud - and that is how He returns."},{"id":2510,"day":1,"category":"acts1","difficulty":"hard","question":"Which apostle in the upper room list is called \"the Zealot\"?","options":["Simon","Andrew","Bartholomew","Thomas"],"correct":0,"reference":"Acts 1:13","explanation":"\"Simon the Zealot.\" There are two Simons in the Gospels, so Luke adds the title - this is not Simon Peter, who is listed first."},{"id":2511,"day":1,"category":"acts1","difficulty":"medium","question":"How did those in the upper room continue together?","options":["With one accord in prayer and supplication","In fasting and silence","In singing and dancing","In study of the Law"],"correct":0,"reference":"Acts 1:14","explanation":"\"These all continued with one accord in prayer and supplication.\" One accord - of one mind. Watch that phrase; Luke uses it again and again in Acts."},{"id":2512,"day":1,"category":"acts1","difficulty":"hard","question":"What did Peter say Judas became to those who arrested Jesus?","options":["A guide","A witness","A judge","A servant"],"correct":0,"reference":"Acts 1:16","explanation":"\"Judas, who became a guide to those who arrested Jesus.\" A guide leads people somewhere - Judas used what he knew to lead them to the garden."},{"id":2513,"day":1,"category":"acts1","difficulty":"medium","question":"What had Judas obtained along with being numbered with the apostles?","options":["A house in Jerusalem","A share of the offerings","A part in this ministry","A seat at the table"],"correct":2,"reference":"Acts 1:17","explanation":"\"He was numbered with us and obtained a part in this ministry.\" Judas was not an outsider - that is what makes the betrayal so sharp."},{"id":2514,"day":1,"category":"acts1","difficulty":"hard","question":"What was the other name of Joseph called Barsabas?","options":["Zealot","Justus","Matthias","Alphaeus"],"correct":1,"reference":"Acts 1:23","explanation":"\"Joseph called Barsabas, who was surnamed Justus.\" Three names for one man - and he is still not the one chosen. Matthias was."},{"id":2515,"day":1,"category":"acts1","difficulty":"hard","question":"According to Peter's prayer, how did Judas fall from his ministry?","options":["By sickness","By the lot","By transgression","By exile"],"correct":2,"reference":"Acts 1:25","explanation":"\"From which Judas by transgression fell.\" Transgression means stepping over the line - he did not drift away, he crossed a boundary."},{"id":2516,"day":5,"category":"acts2","difficulty":"medium","question":"On the Day of Pentecost, how were they all gathered?","options":["In the temple courts","Scattered through the city","Two by two in the streets","With one accord in one place"],"correct":3,"reference":"Acts 2:1","explanation":"\"They were all with one accord in one place.\" One accord again - the same phrase as Acts 1:14. They were united before they were filled."},{"id":2517,"day":5,"category":"acts2","difficulty":"medium","question":"What did the sound from heaven fill?","options":["The whole house where they were sitting","The whole city of Jerusalem","The temple only","The upper room alone"],"correct":0,"reference":"Acts 2:2","explanation":"\"It filled the whole house where they were sitting.\" Not just their ears - the whole house. Notice they were sitting, not doing anything clever."},{"id":2518,"day":5,"category":"acts2","difficulty":"hard","question":"How many of them did a tongue of fire sit upon?","options":["One sat upon the twelve","One sat above them all","One sat upon each of them","One sat upon Peter only"],"correct":2,"reference":"Acts 2:3","explanation":"\"Divided tongues, as of fire, and one sat upon each of them.\" Each one. Nobody in that room was left out."},{"id":2519,"day":6,"category":"acts2","difficulty":"hard","question":"What were the crowd hearing the disciples speak about in their own tongues?","options":["The names of the apostles","The fall of Jerusalem","The laws of Moses","The wonderful works of God"],"correct":3,"reference":"Acts 2:11","explanation":"\"We hear them speaking in our own tongues the wonderful works of God.\" The miracle had content - it was not noise, it was praise everyone could understand."},{"id":2520,"day":6,"category":"acts2","difficulty":"medium","question":"What did the mockers say about the disciples?","options":["They are Galilean fools","They are out of their minds","They are speaking magic","They are full of new wine"],"correct":3,"reference":"Acts 2:13","explanation":"\"Others mocking said, 'They are full of new wine.'\" Peter's answer is wonderfully practical - it is only nine in the morning."},{"id":2521,"day":6,"category":"acts2","difficulty":"hard","question":"What hour of the day did Peter say it was?","options":["The third hour","The ninth hour","The sixth hour","The eleventh hour"],"correct":0,"reference":"Acts 2:15","explanation":"\"It is only the third hour of the day\" - about 9 in the morning. Too early to be drunk, and Peter says so plainly."},{"id":2522,"day":7,"category":"acts2","difficulty":"hard","question":"In Joel's prophecy, what will the old men do?","options":["See visions","Keep silence","Dream dreams","Prophesy"],"correct":2,"reference":"Acts 2:17","explanation":"\"Your young men shall see visions, your old men shall dream dreams.\" Young - visions. Old - dreams. Easy to swap, so fix it now."},{"id":2523,"day":8,"category":"acts2","difficulty":"hard","question":"Peter said God raised Jesus up, having loosed what?","options":["The pains of death","The seals of the tomb","The chains of the grave","The bands of sin"],"correct":0,"reference":"Acts 2:24","explanation":"\"Having loosed the pains of death, because it was not possible that He should be held by it.\" Death could not keep its grip - it was never possible."},{"id":2524,"day":9,"category":"acts2","difficulty":"medium","question":"How did the people respond when they heard Peter's message?","options":["They fell asleep","They tore their clothes","They ran from the city","They were cut to the heart"],"correct":3,"reference":"Acts 2:37","explanation":"\"They were cut to the heart, and said... 'What shall we do?'\" Cut to the heart - it hurt, and that is exactly why they asked what to do next."},{"id":2525,"day":10,"category":"acts2","difficulty":"medium","question":"What four things did the new believers continue steadfastly in?","options":["Fasting, almsgiving, prayer, and silence","The apostles' doctrine, fellowship, breaking of bread, and prayers","Preaching, healing, travelling, and writing","The Law, the Prophets, the Psalms, and the temple"],"correct":1,"reference":"Acts 2:42","explanation":"Doctrine, fellowship, breaking of bread, prayers. Four things - count them on your fingers, the exam loves this verse."},{"id":2526,"day":11,"category":"acts3","difficulty":"medium","question":"At what hour did Peter and John go up to the temple?","options":["The first hour","The third hour","The ninth hour","The sixth hour"],"correct":2,"reference":"Acts 3:1","explanation":"\"The hour of prayer, the ninth hour\" - about 3 in the afternoon. Acts 2 had the third hour; this is the ninth. Do not mix them up."},{"id":2527,"day":11,"category":"acts3","difficulty":"medium","question":"How long had the man at the temple gate been lame?","options":["Since a fall in the temple","For forty years","From his mother's womb","Since he was a boy"],"correct":2,"reference":"Acts 3:2","explanation":"\"Lame from his mother's womb.\" He had never walked, not one step - which is what makes verse 8 so astonishing."},{"id":2528,"day":11,"category":"acts3","difficulty":"easy","question":"What was the name of the temple gate where the lame man was laid?","options":["Beautiful","Solomon's","The Eastern Gate","The Sheep Gate"],"correct":0,"reference":"Acts 3:2","explanation":"\"The gate of the temple which is called Beautiful.\" A beautiful gate, and a man nobody looked at sitting beside it."},{"id":2529,"day":11,"category":"acts3","difficulty":"hard","question":"What did Peter say to the lame man before healing him?","options":["Do you believe?","Peace be with you","Look at us","Rise and be well"],"correct":2,"reference":"Acts 3:4","explanation":"\"Fixing his eyes on him, with John, Peter said, 'Look at us.'\" Before the healing came eye contact - they saw a man, not a beggar."},{"id":2530,"day":11,"category":"acts3","difficulty":"medium","question":"What was the lame man expecting to receive?","options":["Nothing at all","Something from them","Healing","A place in the temple"],"correct":1,"reference":"Acts 3:5","explanation":"\"Expecting to receive something from them\" - he was hoping for coins. He got his legs instead."},{"id":2531,"day":11,"category":"acts3","difficulty":"easy","question":"In whose name did Peter tell the man to rise up and walk?","options":["Jesus Christ of Nazareth","The Holy Spirit","The Lord of Hosts","The God of Abraham"],"correct":0,"reference":"Acts 3:6","explanation":"\"In the name of Jesus Christ of Nazareth, rise up and walk.\" The full title matters - Peter names Him precisely."},{"id":2532,"day":11,"category":"acts3","difficulty":"hard","question":"Which hand did Peter take the man by?","options":["The left hand","Neither - he did not touch him","Both hands","The right hand"],"correct":3,"reference":"Acts 3:7","explanation":"\"He took him by the right hand and lifted him up.\" A small detail the exam loves - right hand."},{"id":2533,"day":11,"category":"acts3","difficulty":"hard","question":"What received strength immediately?","options":["His feet and ankle bones","His whole body at once","His arms and shoulders","His knees and back"],"correct":0,"reference":"Acts 3:7","explanation":"\"Immediately his feet and ankle bones received strength.\" Luke the doctor gives the anatomy - feet and ankle bones."},{"id":2534,"day":11,"category":"acts3","difficulty":"medium","question":"What three things was the healed man doing as he entered the temple?","options":["Running, shouting, and weeping","Dancing, singing, and clapping","Standing, kneeling, and praying","Walking, leaping, and praising God"],"correct":3,"reference":"Acts 3:8","explanation":"\"Walking, leaping, and praising God.\" Three words, in that order - a favourite for fill-in-the-blank."},{"id":2535,"day":12,"category":"acts3","difficulty":"medium","question":"In which porch did the people run together to Peter and John?","options":["Beautiful","Solomon's","The Royal Porch","The Court of the Gentiles"],"correct":1,"reference":"Acts 3:11","explanation":"\"The porch which is called Solomon's.\" Beautiful was the gate; Solomon's is the porch. Two different places in one story."},{"id":2536,"day":12,"category":"acts3","difficulty":"hard","question":"Peter asked why they looked at him and John as though the healing came by what?","options":["The power of the temple","Our own learning","The prayers of the people","Our own power or godliness"],"correct":3,"reference":"Acts 3:12","explanation":"\"As though by our own power or godliness we had made this man walk.\" Peter refuses the credit before he says anything else."},{"id":2537,"day":12,"category":"acts3","difficulty":"hard","question":"Peter said they asked for whom to be granted to them instead of Jesus?","options":["A prophet","A murderer","A soldier","A thief"],"correct":1,"reference":"Acts 3:14","explanation":"\"You denied the Holy One and the Just, and asked for a murderer to be granted to you.\" Barabbas is not named here - Peter just says a murderer."},{"id":2538,"day":12,"category":"acts3","difficulty":"hard","question":"What title did Peter give Jesus, whom they killed?","options":["The King of glory","The Prince of life","The Lamb of God","The Son of Man"],"correct":1,"reference":"Acts 3:15","explanation":"\"And killed the Prince of life, whom God raised from the dead.\" Prince of life - killed. Peter sets the two side by side on purpose."},{"id":2539,"day":13,"category":"acts3","difficulty":"medium","question":"Peter said they and their rulers had acted in what?","options":["Fear","Anger","Envy","Ignorance"],"correct":3,"reference":"Acts 3:17","explanation":"\"I know that you did it in ignorance, as did also your rulers.\" Peter is hard on the deed and gentle with the people."},{"id":2540,"day":13,"category":"acts3","difficulty":"hard","question":"Peter said heaven must receive Jesus until what?","options":["The fall of Jerusalem","The day of judgement","The gospel reaches Rome","The times of restoration of all things"],"correct":3,"reference":"Acts 3:21","explanation":"\"Whom heaven must receive until the times of restoration of all things.\" Verse 19 has times of refreshing; verse 21 has times of restoration. Two different phrases, close together."},{"id":2541,"day":14,"category":"acts4","difficulty":"hard","question":"Who came upon Peter and John as they spoke to the people?","options":["The scribes and the Pharisees","The elders of Galilee","The priests, the captain of the temple, and the Sadducees","Herod's soldiers"],"correct":2,"reference":"Acts 4:1","explanation":"Three groups: the priests, the captain of the temple, and the Sadducees. The Sadducees denied the resurrection, which is exactly what was being preached."},{"id":2542,"day":14,"category":"acts4","difficulty":"medium","question":"Why were the rulers greatly disturbed?","options":["They preached in Jesus the resurrection from the dead","They refused to pay the temple tax","They entered the temple at night","They healed on the Sabbath"],"correct":0,"reference":"Acts 4:2","explanation":"\"Preached in Jesus the resurrection from the dead.\" The healing was not the problem - the resurrection was."},{"id":2543,"day":14,"category":"acts4","difficulty":"medium","question":"Why were Peter and John kept until the next day?","options":["The high priest was away","The council was fasting","It was already evening","The temple was closed for a feast"],"correct":2,"reference":"Acts 4:3","explanation":"\"For it was already evening.\" A night in custody simply because the day had run out."},{"id":2544,"day":14,"category":"acts4","difficulty":"hard","question":"Which four men of the high priest's family are named at the gathering?","options":["Caiaphas, Nicodemus, John, and James","Annas, Caiaphas, John, and Alexander","Annas, Caiaphas, Gamaliel, and Saul","Annas, Herod, Pilate, and Alexander"],"correct":1,"reference":"Acts 4:6","explanation":"Annas, Caiaphas, John, Alexander. Four names in a row - a favourite for the exam."},{"id":2545,"day":15,"category":"acts4","difficulty":"medium","question":"What two things did the council ask Peter and John?","options":["By what power or by what name have you done this?","Who sent you and who paid you?","Where is the man and who healed him?","When did you learn and from whom?"],"correct":0,"reference":"Acts 4:7","explanation":"\"By what power or by what name have you done this?\" Power and name - and Peter answers with the name."},{"id":2546,"day":15,"category":"acts4","difficulty":"hard","question":"What did Peter call the stone rejected by the builders?","options":["The living stone","The foundation stone","The chief cornerstone","The rock of offence"],"correct":2,"reference":"Acts 4:11","explanation":"\"The stone which was rejected by you builders, which has become the chief cornerstone.\" Rejected, then made the most important stone of all."},{"id":2547,"day":15,"category":"acts4","difficulty":"medium","question":"What did the council realise about Peter and John when they saw their boldness?","options":["That they were from Galilee","That they were trained in the law","That they were of the family of priests","That they had been with Jesus"],"correct":3,"reference":"Acts 4:13","explanation":"\"They realized that they had been with Jesus.\" Uneducated and untrained, yet unmistakable - time with Jesus showed."},{"id":2548,"day":16,"category":"acts4","difficulty":"hard","question":"Why could the council say nothing against Peter and John?","options":["The crowd had blocked the door","The healed man was standing with them","No witnesses could be found","The high priest was absent"],"correct":1,"reference":"Acts 4:14","explanation":"\"Seeing the man who had been healed standing with them, they could say nothing against it.\" The evidence was standing in the room."},{"id":2549,"day":16,"category":"acts4","difficulty":"hard","question":"How old was the man on whom the healing miracle had been performed?","options":["Over forty years old","About twenty years old","Over fifty years old","Over thirty years old"],"correct":0,"reference":"Acts 4:22","explanation":"\"The man was over forty years old.\" Over forty years unable to walk - which is why nobody could argue with it."},{"id":2550,"day":17,"category":"acts4","difficulty":"medium","question":"How did the believers raise their voice to God after Peter and John were released?","options":["With one accord","With weeping and fasting","In whispers, for fear","Each one alone in his house"],"correct":0,"reference":"Acts 4:24","explanation":"\"They raised their voice to God with one accord.\" One accord again - Luke keeps returning to it."},{"id":2551,"day":17,"category":"acts4","difficulty":"hard","question":"Who does the prayer name as gathered together against God's holy Servant Jesus?","options":["The Sadducees and the Pharisees","Herod and Pontius Pilate, with the Gentiles and the people of Israel","Annas and Caiaphas, with the scribes","Theudas and Judas of Galilee"],"correct":1,"reference":"Acts 4:27","explanation":"Herod, Pontius Pilate, the Gentiles, and the people of Israel - four parties, all named in one verse."},{"id":2552,"day":17,"category":"acts4","difficulty":"medium","question":"What did the believers ask for when they looked on the threats against them?","options":["Boldness to speak God's word","Judgement on the council","Escape from the city","Safety from their enemies"],"correct":0,"reference":"Acts 4:29","explanation":"They did not pray for the threats to stop - they prayed for boldness to keep speaking through them."},{"id":2553,"day":17,"category":"acts4","difficulty":"medium","question":"What happened to the place where they were assembled when they had prayed?","options":["It was filled with smoke","It was filled with light","It was shaken","Its doors were opened"],"correct":2,"reference":"Acts 4:31","explanation":"\"The place where they were assembled together was shaken.\" God answered the prayer for boldness by shaking the building."},{"id":2554,"day":18,"category":"acts4","difficulty":"medium","question":"The multitude of believers were of what?","options":["One mind and one voice","One tribe and one tongue","One faith and one baptism","One heart and one soul"],"correct":3,"reference":"Acts 4:32","explanation":"\"Of one heart and one soul.\" Heart and soul - and nobody called what he owned his own."},{"id":2555,"day":18,"category":"acts4","difficulty":"hard","question":"What does the name Barnabas mean, and where was he from?","options":["Son of Encouragement, a Levite of Cyprus","Son of Peace, a Pharisee of Tarsus","Son of Thunder, a Levite of Judea","Son of Consolation, a Greek of Antioch"],"correct":0,"reference":"Acts 4:36","explanation":"Joses, renamed Barnabas - Son of Encouragement - a Levite from Cyprus. His real name, his nickname, his tribe and his island, all in one verse."},{"id":2556,"day":19,"category":"acts5","difficulty":"easy","question":"What was the name of Ananias's wife?","options":["Rhoda","Priscilla","Dorcas","Sapphira"],"correct":3,"reference":"Acts 5:1","explanation":"\"Ananias, with Sapphira his wife.\" Two names to keep together - they agreed on the lie together."},{"id":2557,"day":19,"category":"acts5","difficulty":"medium","question":"What did Ananias do with part of the proceeds?","options":["He buried it in a field","He kept it back","He gave it to the poor","He paid a debt with it"],"correct":1,"reference":"Acts 5:2","explanation":"\"He kept back part of the proceeds.\" Keeping some was never the sin - pretending he had given it all was."},{"id":2558,"day":19,"category":"acts5","difficulty":"hard","question":"Peter said Ananias had not lied to men, but to whom?","options":["His own wife","The apostles","God","The church"],"correct":2,"reference":"Acts 5:4","explanation":"\"You have not lied to men but to God.\" Verse 3 says he lied to the Holy Spirit; verse 4 says to God. Peter joins the two."},{"id":2559,"day":19,"category":"acts5","difficulty":"hard","question":"How long after Ananias did Sapphira come in?","options":["About one hour","About three hours","Later that evening","The next morning"],"correct":1,"reference":"Acts 5:7","explanation":"\"About three hours later.\" Three hours in which nobody told her - and she repeated the lie on her own."},{"id":2560,"day":20,"category":"acts5","difficulty":"medium","question":"Where were the apostles all gathered with one accord?","options":["The Beautiful Gate","Solomon's Porch","The house of Mary","The upper room"],"correct":1,"reference":"Acts 5:12","explanation":"Solomon's Porch again - the same place the crowd ran to after the lame man was healed."},{"id":2561,"day":20,"category":"acts5","difficulty":"hard","question":"What did people hope would fall on the sick laid in the streets?","options":["The shadow of Peter passing by","Water from the pool","Oil from the temple","The hands of the apostles"],"correct":0,"reference":"Acts 5:15","explanation":"\"That at least the shadow of Peter passing by might fall on some of them.\" Not even his hand - his shadow."},{"id":2562,"day":20,"category":"acts5","difficulty":"medium","question":"Which sect was the high priest part of?","options":["The Zealots","The Sadducees","The Pharisees","The Essenes"],"correct":1,"reference":"Acts 5:17","explanation":"\"Which is the sect of the Sadducees.\" The same group from chapter 4, and still filled with indignation."},{"id":2563,"day":21,"category":"acts5","difficulty":"medium","question":"Who opened the prison doors at night?","options":["An angel of the Lord","Gamaliel","An earthquake","A sympathetic guard"],"correct":0,"reference":"Acts 5:19","explanation":"\"An angel of the Lord opened the prison doors.\" Acts 12 has another jailbreak and Acts 16 an earthquake - keep the three apart."},{"id":2564,"day":21,"category":"acts5","difficulty":"hard","question":"What did the angel tell the apostles to go and do?","options":["Flee to Galilee and wait","Stand in the temple and speak all the words of this life","Return to their homes quietly","Go to the high priest and answer him"],"correct":1,"reference":"Acts 5:20","explanation":"\"Go, stand in the temple and speak to the people all the words of this life.\" Freed from prison and sent straight back to preaching."},{"id":2565,"day":21,"category":"acts5","difficulty":"hard","question":"What did the officers find when they went to the prison?","options":["The prison shut securely and guards at the doors, but no one inside","The doors broken open and the guards asleep","The apostles still sleeping in their cell","The guards gone and the doors ablaze"],"correct":0,"reference":"Acts 5:23","explanation":"Shut securely, guards standing - and empty. That detail is what made it undeniable."},{"id":2566,"day":22,"category":"acts5","difficulty":"medium","question":"Why did the captain bring the apostles without violence?","options":["The apostles came willingly","The temple guard was too few","They feared the people might stone them","The high priest had forbidden force"],"correct":2,"reference":"Acts 5:26","explanation":"\"For they feared the people, lest they should be stoned.\" The crowd, not conscience, held them back."},{"id":2567,"day":22,"category":"acts5","difficulty":"hard","question":"What title did Peter say God exalted Jesus to His right hand to be?","options":["Lord and Christ","King and Judge","Prince and Savior","Shepherd and Bishop"],"correct":2,"reference":"Acts 5:31","explanation":"\"To be Prince and Savior.\" In Acts 2:36 it was Lord and Christ, in Acts 3:15 Prince of life. Different titles, different speeches."},{"id":2568,"day":23,"category":"acts5","difficulty":"medium","question":"Who was Gamaliel?","options":["A Pharisee and teacher of the law respected by all","The captain of the temple","A Sadducee of the council","The high priest that year"],"correct":0,"reference":"Acts 5:34","explanation":"\"A Pharisee named Gamaliel, a teacher of the law held in respect by all the people.\" A Pharisee - not a Sadducee - speaking up for the apostles."},{"id":2569,"day":23,"category":"acts5","difficulty":"hard","question":"How many men joined Theudas, according to Gamaliel?","options":["About a hundred and twenty","About three thousand","About five thousand","About four hundred"],"correct":3,"reference":"Acts 5:36","explanation":"\"A number of men, about four hundred, joined him.\" Acts is full of numbers - 120, 3,000, 5,000, and now 400."},{"id":2570,"day":23,"category":"acts5","difficulty":"medium","question":"How did the apostles feel as they left the council after being beaten?","options":["Silent, and spoke no more that week","Angry, and planned to appeal","Afraid, and went into hiding","Rejoicing that they were counted worthy to suffer shame for His name"],"correct":3,"reference":"Acts 5:41","explanation":"They left a beating rejoicing - counted worthy to suffer shame for His name. Then verse 42: they did not cease teaching."},{"id":2571,"day":24,"category":"acts6","difficulty":"medium","question":"Who complained that their widows were neglected?","options":["The Levites, against the priests","The Hellenists, against the Hebrews","The Hebrews, against the Hellenists","The Samaritans, against the Judeans"],"correct":1,"reference":"Acts 6:1","explanation":"\"A complaint against the Hebrews by the Hellenists.\" Hellenists were Greek-speaking Jews - the direction of the complaint matters."},{"id":2572,"day":24,"category":"acts6","difficulty":"hard","question":"What did the twelve say it was not desirable for them to leave?","options":["Their prayers, to settle disputes","The word of God, to serve tables","The temple, to travel","Jerusalem, to preach abroad"],"correct":1,"reference":"Acts 6:2","explanation":"\"It is not desirable that we should leave the word of God and serve tables.\" Not that serving tables was beneath them - it was not their task."},{"id":2573,"day":24,"category":"acts6","difficulty":"medium","question":"How many men were to be sought out, and what were they to be full of?","options":["Twelve, full of faith and power","Seven, full of the Holy Spirit and wisdom","Ten, full of grace and truth","Seven, full of zeal and learning"],"correct":1,"reference":"Acts 6:3","explanation":"Seven men of good reputation, full of the Holy Spirit and wisdom. Seven - the number that names this chapter."},{"id":2574,"day":24,"category":"acts6","difficulty":"hard","question":"What did the apostles say they would give themselves continually to?","options":["Prayer and the ministry of the word","Travel and the planting of churches","Fasting and the breaking of bread","Teaching and healing"],"correct":0,"reference":"Acts 6:4","explanation":"\"Prayer and to the ministry of the word.\" Two things, and they hand everything else away to keep them."},{"id":2575,"day":25,"category":"acts6","difficulty":"hard","question":"Which of the seven is described as a proselyte from Antioch?","options":["Nicanor","Parmenas","Prochorus","Nicolas"],"correct":3,"reference":"Acts 6:5","explanation":"\"Nicolas, a proselyte from Antioch.\" Nicanor and Nicolas look alike - only Nicolas gets the description."},{"id":2576,"day":25,"category":"acts6","difficulty":"medium","question":"How is Stephen described when the seven are chosen?","options":["A man learned in the law","A man full of faith and the Holy Spirit","A Levite of Cyprus","A man of great wealth"],"correct":1,"reference":"Acts 6:5","explanation":"\"Stephen, a man full of faith and the Holy Spirit.\" He is named first of the seven, and described before any of the others."},{"id":2577,"day":25,"category":"acts6","difficulty":"medium","question":"What did the apostles do when the seven were set before them?","options":["They sent them out two by two","They cast lots over them","They prayed and laid hands on them","They anointed them with oil"],"correct":2,"reference":"Acts 6:6","explanation":"\"When they had prayed, they laid hands on them.\" Prayer first, then hands."},{"id":2578,"day":25,"category":"acts6","difficulty":"hard","question":"Which group became obedient to the faith in great numbers?","options":["The Roman soldiers","The scribes","The priests","The Pharisees"],"correct":2,"reference":"Acts 6:7","explanation":"\"A great many of the priests were obedient to the faith.\" Priests - the very group opposing them in chapters 4 and 5."},{"id":2579,"day":26,"category":"acts6","difficulty":"medium","question":"Stephen was full of faith and what else, doing great wonders and signs?","options":["Grace","Joy","Power","Wisdom"],"correct":2,"reference":"Acts 6:8","explanation":"\"Stephen, full of faith and power.\" In verse 5 it was faith and the Holy Spirit; in verse 8, faith and power."},{"id":2580,"day":26,"category":"acts6","difficulty":"hard","question":"What was the name of the synagogue whose members disputed with Stephen?","options":["The Synagogue of the Elders","The Synagogue of the Diaspora","The Synagogue of the Freedmen","The Synagogue of the Cilicians"],"correct":2,"reference":"Acts 6:9","explanation":"\"The Synagogue of the Freedmen\" - Cyrenians, Alexandrians, and men from Cilicia and Asia. Saul was from Cilicia."},{"id":2581,"day":26,"category":"acts6","difficulty":"medium","question":"What were Stephen's opponents unable to resist?","options":["The crowds who followed him","The wisdom and the Spirit by which he spoke","The letters he wrote","The miracles he performed"],"correct":1,"reference":"Acts 6:10","explanation":"\"Not able to resist the wisdom and the Spirit by which he spoke.\" Losing the argument is what drove them to false witnesses."},{"id":2582,"day":26,"category":"acts6","difficulty":"hard","question":"What did the secretly induced men claim Stephen had spoken against?","options":["The temple and the priests","The council and the elders","Caesar and the law","Moses and God"],"correct":3,"reference":"Acts 6:11","explanation":"\"Blasphemous words against Moses and God.\" Then the false witnesses in verse 13 change it to the holy place and the law."},{"id":2583,"day":26,"category":"acts6","difficulty":"hard","question":"What did the false witnesses say Stephen claimed Jesus would do?","options":["Rebuild the temple in three days","Abolish the Sabbath entirely","Destroy this place and change the customs Moses delivered","Overthrow Caesar and crown Himself king"],"correct":2,"reference":"Acts 6:14","explanation":"\"Destroy this place and change the customs which Moses delivered to us.\" The same charge brought against Jesus at His own trial."},{"id":2584,"day":26,"category":"acts6","difficulty":"easy","question":"What did the council see when they looked steadfastly at Stephen?","options":["His hands raised in prayer","His face as the face of an angel","A light shining around him","Tears running down his face"],"correct":1,"reference":"Acts 6:15","explanation":"\"Saw his face as the face of an angel.\" The chapter ends there - and chapter 7 is what he says next."},{"id":2585,"day":24,"category":"acts6","difficulty":"medium","question":"Who chose the seven men?","options":["The twelve apostles alone","The elders of Jerusalem","The whole multitude of the disciples","Peter and John"],"correct":2,"reference":"Acts 6:5","explanation":"\"The saying pleased the whole multitude. And they chose...\" The people chose them; the apostles then prayed and laid hands on them."},{"id":2586,"day":33,"category":"acts8","difficulty":"medium","question":"Who was consenting to Stephen's death?","options":["Philip","Caiaphas","Gamaliel","Saul"],"correct":3,"reference":"Acts 8:1","explanation":"\"Now Saul was consenting to his death.\" Chapter 8 opens with Saul approving - and chapter 9 stops him on a road."},{"id":2587,"day":33,"category":"acts8","difficulty":"hard","question":"Who was NOT scattered when persecution arose in Jerusalem?","options":["The widows","The priests","The seven","The apostles"],"correct":3,"reference":"Acts 8:1","explanation":"\"They were all scattered... except the apostles.\" Everyone else left; the apostles stayed."},{"id":2588,"day":33,"category":"acts8","difficulty":"medium","question":"What did Saul do to the church?","options":["Banned it from the temple","Made havoc of it, dragging off men and women to prison","Taxed its members heavily","Wrote letters warning against it"],"correct":1,"reference":"Acts 8:3","explanation":"\"Entering every house, and dragging off men and women.\" Men AND women - Luke says so twice about Saul."},{"id":2589,"day":33,"category":"acts8","difficulty":"medium","question":"What did those who were scattered do?","options":["Settled in Samaria and farmed","Went everywhere preaching the word","Returned quietly to Jerusalem","Hid until the danger passed"],"correct":1,"reference":"Acts 8:4","explanation":"The persecution meant to stop the message spread it instead - scattering became sending."},{"id":2590,"day":34,"category":"acts8","difficulty":"easy","question":"What was there in the city of Samaria after Philip preached?","options":["Great mourning","Great confusion","Great fear","Great joy"],"correct":3,"reference":"Acts 8:8","explanation":"\"And there was great joy in that city.\" A short verse the exam likes."},{"id":2591,"day":34,"category":"acts8","difficulty":"hard","question":"What did the people of Samaria call Simon the sorcerer?","options":["The great power of God","The prophet of Samaria","The teacher of wisdom","The son of the most high"],"correct":0,"reference":"Acts 8:10","explanation":"\"This man is the great power of God\" - from the least to the greatest, they all said it."},{"id":2592,"day":34,"category":"acts8","difficulty":"medium","question":"What did Simon the sorcerer do after he believed?","options":["He returned to his sorceries","He was baptized and continued with Philip","He burned his books of magic","He left the city at once"],"correct":1,"reference":"Acts 8:13","explanation":"\"Simon himself also believed; and when he was baptized he continued with Philip.\" He really did believe - which makes verse 18 stranger still."},{"id":2593,"day":34,"category":"acts8","difficulty":"medium","question":"Which two apostles were sent from Jerusalem to Samaria?","options":["Peter and John","Barnabas and Saul","Peter and James","Philip and John"],"correct":0,"reference":"Acts 8:14","explanation":"Peter and John again - the same pair as the Beautiful Gate and the council."},{"id":2594,"day":34,"category":"acts8","difficulty":"hard","question":"What did Peter say to Simon when he offered money?","options":["Go, and sin no more","Your money perish with you","You have said it yourself","Take back your silver"],"correct":1,"reference":"Acts 8:20","explanation":"\"Your money perish with you, because you thought that the gift of God could be purchased with money!\" Peter does not soften it."},{"id":2595,"day":34,"category":"acts8","difficulty":"hard","question":"How did Peter describe Simon's condition?","options":["Proud in spirit and hard of heart","Lost in darkness and far from God","Blind of heart and deaf of ear","Poisoned by bitterness and bound by iniquity"],"correct":3,"reference":"Acts 8:23","explanation":"\"Poisoned by bitterness and bound by iniquity.\" Poison and chains - two pictures in one sentence."},{"id":2596,"day":35,"category":"acts8","difficulty":"medium","question":"Which road was Philip told to take, and what is said about it?","options":["Jerusalem to Gaza; this is desert","Damascus to Jerusalem; this is straight","Jerusalem to Joppa; this is by the sea","Samaria to Caesarea; this is the coast road"],"correct":0,"reference":"Acts 8:26","explanation":"\"The road which goes down from Jerusalem to Gaza. This is desert.\" Luke adds the note about the desert on purpose."},{"id":2597,"day":35,"category":"acts8","difficulty":"hard","question":"Who was the Ethiopian a eunuch of great authority under?","options":["Pharaoh of Egypt","Caesar of Rome","Candace the queen of the Ethiopians","Herod the tetrarch"],"correct":2,"reference":"Acts 8:27","explanation":"\"A eunuch of great authority under Candace the queen of the Ethiopians, who had charge of all her treasury.\" Candace is the title of the queen."},{"id":2598,"day":35,"category":"acts8","difficulty":"medium","question":"Which prophet was the Ethiopian reading?","options":["Jeremiah","Isaiah","Joel","Daniel"],"correct":1,"reference":"Acts 8:28","explanation":"\"He was reading Isaiah the prophet\" - the passage about the lamb led to the slaughter."},{"id":2599,"day":35,"category":"acts8","difficulty":"hard","question":"What did the eunuch reply when Philip asked if he understood?","options":["Only the priests can explain it","How can I, unless someone guides me?","I have read it many times","No man has ever taught me"],"correct":1,"reference":"Acts 8:31","explanation":"\"How can I, unless someone guides me?\" - and then he invites Philip up into the chariot."},{"id":2600,"day":35,"category":"acts8","difficulty":"medium","question":"Where was Philip found after the Spirit caught him away?","options":["Azotus","Joppa","Lydda","Caesarea"],"correct":0,"reference":"Acts 8:40","explanation":"\"Philip was found at Azotus\" - and preached through every city until he reached Caesarea."},{"id":2601,"day":36,"category":"acts9","difficulty":"medium","question":"What was Saul still breathing against the disciples?","options":["Threats and murder","Anger and scorn","Fire and judgement","Curses and slander"],"correct":0,"reference":"Acts 9:1","explanation":"\"Still breathing threats and murder.\" Breathing - as though it were the air he lived on."},{"id":2602,"day":36,"category":"acts9","difficulty":"hard","question":"What were the disciples in Damascus called in Saul's letters?","options":["Those who were of the Way","The people of the Book","The Nazarenes","The Christians"],"correct":0,"reference":"Acts 9:2","explanation":"\"Any who were of the Way.\" Christian does not appear until Acts 11:26 - here they are the Way."},{"id":2603,"day":36,"category":"acts9","difficulty":"hard","question":"What did the Lord say it was hard for Saul to kick against?","options":["The stones","The chains","The goads","The gates"],"correct":2,"reference":"Acts 9:5","explanation":"\"It is hard for you to kick against the goads.\" A goad is a sharp stick used to drive oxen - fighting it only hurts you."},{"id":2604,"day":36,"category":"acts9","difficulty":"hard","question":"What did the men travelling with Saul experience?","options":["They fell down blinded with him","They saw the light but heard nothing","They fled back to Jerusalem","They heard a voice but saw no one"],"correct":3,"reference":"Acts 9:7","explanation":"\"Stood speechless, hearing a voice but seeing no one.\" They heard; they did not see."},{"id":2605,"day":36,"category":"acts9","difficulty":"medium","question":"How long was Saul without sight, and what did he do?","options":["Three days, and wept continually","Forty days, and prayed","Seven days, and fasted","Three days, and neither ate nor drank"],"correct":3,"reference":"Acts 9:9","explanation":"\"Three days without sight, and neither ate nor drank.\" Three days - the number to remember here."},{"id":2606,"day":37,"category":"acts9","difficulty":"hard","question":"At whose house was Saul staying in Damascus?","options":["Barnabas","Ananias","Simon the tanner","Judas"],"correct":3,"reference":"Acts 9:11","explanation":"\"Inquire at the house of Judas for one called Saul of Tarsus.\" A different Judas - and a different Simon from the tanner in Joppa."},{"id":2607,"day":37,"category":"acts9","difficulty":"medium","question":"What fell from Saul's eyes when Ananias laid hands on him?","options":["A white film","A dark veil","Drops like blood","Something like scales"],"correct":3,"reference":"Acts 9:18","explanation":"\"Something like scales\" - and he received his sight at once, then was baptized."},{"id":2608,"day":38,"category":"acts9","difficulty":"hard","question":"How did the disciples get Saul out of Damascus?","options":["Led him out through a tunnel","Let him down through the wall in a large basket","Disguised him as a soldier","Hid him in a merchant's cart"],"correct":1,"reference":"Acts 9:25","explanation":"\"Let him down through the wall in a large basket.\" The man who came with letters of arrest left in a basket."},{"id":2609,"day":38,"category":"acts9","difficulty":"medium","question":"Who brought Saul to the apostles when they were afraid of him?","options":["Peter","Barnabas","Philip","Ananias"],"correct":1,"reference":"Acts 9:27","explanation":"\"But Barnabas took him and brought him to the apostles.\" Son of Encouragement, living up to the name."},{"id":2610,"day":39,"category":"acts9","difficulty":"hard","question":"How long had Aeneas been bedridden?","options":["Twelve years","Eight years","Three years","Forty years"],"correct":1,"reference":"Acts 9:33","explanation":"\"Bedridden eight years and was paralyzed.\" Eight - not the forty of the lame man at the gate."},{"id":2611,"day":41,"category":"acts10","difficulty":"medium","question":"Which regiment was Cornelius a centurion of?","options":["The Praetorian Guard","The Italian Regiment","The Syrian Cohort","The Augustan Regiment"],"correct":1,"reference":"Acts 10:1","explanation":"\"A centurion of what was called the Italian Regiment.\" Caesarea, Italian Regiment, Cornelius - three details in one verse."},{"id":2612,"day":41,"category":"acts10","difficulty":"hard","question":"What did the angel say had come up for a memorial before God?","options":["Cornelius's prayers and alms","The cries of the poor","The prayers of the church","The offerings of the temple"],"correct":0,"reference":"Acts 10:4","explanation":"\"Your prayers and your alms have come up for a memorial before God.\" Prayers AND alms - both are named."},{"id":2613,"day":41,"category":"acts10","difficulty":"medium","question":"Whose house was Peter lodging in at Joppa?","options":["Simon a tanner, by the sea","Judas, on the street called Straight","Lydia, a seller of purple","Mary the mother of John"],"correct":0,"reference":"Acts 10:6","explanation":"\"Simon, a tanner, whose house is by the sea.\" A tanner worked with dead animals - an unclean trade, and a hint of what is coming."},{"id":2614,"day":41,"category":"acts10","difficulty":"hard","question":"Whom did Cornelius send to Joppa?","options":["Two centurions and a scribe","Three soldiers of his regiment","Two household servants and a devout soldier","His son and two servants"],"correct":2,"reference":"Acts 10:7","explanation":"Two servants and one devout soldier - three men, which is what the Spirit tells Peter in verse 19."},{"id":2615,"day":42,"category":"acts10","difficulty":"medium","question":"At what hour did Peter go up on the housetop to pray?","options":["The third hour","The ninth hour","The eleventh hour","The sixth hour"],"correct":3,"reference":"Acts 10:9","explanation":"\"About the sixth hour\" - midday. Cornelius's vision was at the ninth hour; Peter's at the sixth."},{"id":2616,"day":42,"category":"acts10","difficulty":"hard","question":"How was the great sheet in Peter's vision described?","options":["Spread across the whole sky","Bound at the four corners, let down to the earth","Folded and sealed with seven seals","Carried by four angels"],"correct":1,"reference":"Acts 10:11","explanation":"\"An object like a great sheet bound at the four corners.\" Four corners - a small detail worth locking in."},{"id":2617,"day":42,"category":"acts10","difficulty":"medium","question":"How many times was the vision of the sheet repeated?","options":["Seven times","Once only","Twice","Three times"],"correct":3,"reference":"Acts 10:16","explanation":"\"This was done three times.\" Three - the same number as Peter's denials and his restoration."},{"id":2618,"day":43,"category":"acts10","difficulty":"medium","question":"What did Peter say when Cornelius fell down at his feet?","options":["Peace be to this house","Rise, and hear the word","Do not fear, for God is with you","Stand up; I myself am also a man"],"correct":3,"reference":"Acts 10:26","explanation":"\"Stand up; I myself am also a man.\" Peter refuses worship - just as he refused credit in Acts 3:12."},{"id":2619,"day":43,"category":"acts10","difficulty":"hard","question":"How long before Peter's arrival had Cornelius been fasting and praying?","options":["Three days","A week","Two days","Four days"],"correct":3,"reference":"Acts 10:30","explanation":"\"Four days ago I was fasting until this hour.\" Four days - the journey plus the waiting."},{"id":2620,"day":44,"category":"acts10","difficulty":"medium","question":"What happened while Peter was still speaking?","options":["The house was shaken","The Holy Spirit fell on all who heard the word","A great light filled the room","An angel appeared to them"],"correct":1,"reference":"Acts 10:44","explanation":"\"While Peter was still speaking these words, the Holy Spirit fell upon all those who heard.\" He never finished the sermon."},{"id":2621,"day":46,"category":"acts11","difficulty":"medium","question":"What did those of the circumcision accuse Peter of?","options":["Going in to uncircumcised men and eating with them","Leaving Jerusalem without permission","Baptizing without water","Preaching without the apostles' consent"],"correct":0,"reference":"Acts 11:3","explanation":"\"You went in to uncircumcised men and ate with them!\" Eating with them is the charge - sharing a table meant sharing a life."},{"id":2622,"day":46,"category":"acts11","difficulty":"hard","question":"How did Peter explain himself to the church in Jerusalem?","options":["With a written account","By calling witnesses first","In order from the beginning","By quoting the prophets"],"correct":2,"reference":"Acts 11:4","explanation":"\"Peter explained it to them in order from the beginning.\" He retells the whole vision rather than pulling rank."},{"id":2623,"day":46,"category":"acts11","difficulty":"hard","question":"How many brethren accompanied Peter to Cornelius's house?","options":["Three","Six","Seven","Twelve"],"correct":1,"reference":"Acts 11:12","explanation":"\"These six brethren accompanied me.\" Three men came from Caesarea; six brethren went back with Peter."},{"id":2624,"day":46,"category":"acts11","difficulty":"medium","question":"What word of the Lord did Peter remember when the Spirit fell on the Gentiles?","options":["What God has cleansed you must not call common","You shall be witnesses to the end of the earth","John baptized with water, but you shall be baptized with the Holy Spirit","Feed My sheep"],"correct":2,"reference":"Acts 11:16","explanation":"The promise from Acts 1:5, remembered now that it has landed on people nobody expected."},{"id":2625,"day":46,"category":"acts11","difficulty":"hard","question":"What question did Peter end his defence with?","options":["Who was I that I could withstand God?","Is God not the God of all?","Who among you would have done otherwise?","Shall I not obey the Spirit?"],"correct":0,"reference":"Acts 11:17","explanation":"\"Who was I that I could withstand God?\" The argument ends there - verse 18 says they became silent."},{"id":2626,"day":47,"category":"acts11","difficulty":"hard","question":"How far did those scattered after Stephen's death travel?","options":["As far as Egypt and Libya","As far as Rome and Spain","As far as Damascus and Tarsus","As far as Phoenicia, Cyprus, and Antioch"],"correct":3,"reference":"Acts 11:19","explanation":"Phoenicia, Cyprus, Antioch - and at first they preached to no one but the Jews only."},{"id":2627,"day":47,"category":"acts11","difficulty":"hard","question":"Where were the men from who first spoke to the Hellenists at Antioch?","options":["Phoenicia and Samaria","Tarsus and Cilicia","Cyprus and Cyrene","Judea and Galilee"],"correct":2,"reference":"Acts 11:20","explanation":"\"Men from Cyprus and Cyrene.\" Unnamed men, and the gospel crosses to the Greeks because of them."},{"id":2628,"day":47,"category":"acts11","difficulty":"medium","question":"Whom did the church in Jerusalem send to Antioch?","options":["Peter","Agabus","Philip","Barnabas"],"correct":3,"reference":"Acts 11:22","explanation":"They sent Barnabas - and he in turn went to fetch Saul."},{"id":2629,"day":47,"category":"acts11","difficulty":"medium","question":"How is Barnabas described in Acts 11?","options":["A bold man, quick to speak","A learned man, trained in the law","A rich man, generous to the poor","A good man, full of the Holy Spirit and of faith"],"correct":3,"reference":"Acts 11:24","explanation":"\"For he was a good man, full of the Holy Spirit and of faith.\" One of the warmest descriptions in the book."},{"id":2630,"day":47,"category":"acts11","difficulty":"medium","question":"Where did Barnabas go to seek Saul?","options":["Damascus","Tarsus","Cyprus","Jerusalem"],"correct":1,"reference":"Acts 11:25","explanation":"\"Barnabas departed for Tarsus to seek Saul.\" Saul had been sent home to Tarsus in Acts 9:30."},{"id":2631,"day":48,"category":"acts11","difficulty":"medium","question":"How long did Barnabas and Saul teach at Antioch?","options":["A whole year","Three months","Two years","Forty days"],"correct":0,"reference":"Acts 11:26","explanation":"\"For a whole year they assembled with the church and taught a great many people.\" A year in one place - and the name Christian was born there."},{"id":2632,"day":48,"category":"acts11","difficulty":"easy","question":"Where were the disciples first called Christians?","options":["Jerusalem","Damascus","Caesarea","Antioch"],"correct":3,"reference":"Acts 11:26","explanation":"\"The disciples were first called Christians in Antioch.\" Not Jerusalem - Antioch. The memory verse for this week."},{"id":2633,"day":48,"category":"acts11","difficulty":"hard","question":"Which prophet foretold a great famine?","options":["Simeon","Manaen","Agabus","Lucius"],"correct":2,"reference":"Acts 11:28","explanation":"\"One of them, named Agabus.\" He turns up again later in Acts, binding his own hands with Paul's belt."},{"id":2634,"day":48,"category":"acts11","difficulty":"hard","question":"In whose days did the great famine happen?","options":["Herod the king","Nero Caesar","Claudius Caesar","Augustus Caesar"],"correct":2,"reference":"Acts 11:28","explanation":"\"Which also happened in the days of Claudius Caesar.\" Luke anchors the prophecy to a real emperor."},{"id":2635,"day":48,"category":"acts11","difficulty":"medium","question":"By whose hands was the relief sent to the elders in Judea?","options":["Philip and Stephen","Agabus and Simeon","Peter and John","Barnabas and Saul"],"correct":3,"reference":"Acts 11:30","explanation":"\"Sent it to the elders by the hands of Barnabas and Saul.\" The pair who will set out on the first journey in chapter 13."},{"id":2636,"day":49,"category":"acts12","difficulty":"medium","question":"Which apostle did Herod kill with the sword?","options":["John the brother of James","James the brother of John","Peter","James the son of Alphaeus"],"correct":1,"reference":"Acts 12:2","explanation":"\"He killed James the brother of John with the sword.\" There are two men named James - this is John's brother."},{"id":2637,"day":49,"category":"acts12","difficulty":"hard","question":"During which feast was Peter arrested?","options":["The Feast of Dedication","Pentecost","The Days of Unleavened Bread","The Feast of Tabernacles"],"correct":2,"reference":"Acts 12:3","explanation":"\"Now it was during the Days of Unleavened Bread.\" Herod meant to bring him out after Passover."},{"id":2638,"day":49,"category":"acts12","difficulty":"hard","question":"To how many squads of soldiers was Peter delivered?","options":["Two","Four","Six","Three"],"correct":1,"reference":"Acts 12:4","explanation":"\"Delivered him to four squads of soldiers to keep him.\" Four squads - Herod was taking no chances."},{"id":2639,"day":49,"category":"acts12","difficulty":"medium","question":"What was the church doing while Peter was in prison?","options":["They fled the city","They petitioned Herod for his release","Constant prayer was offered to God for him","They chose a replacement for him"],"correct":2,"reference":"Acts 12:5","explanation":"\"Constant prayer was offered to God for him by the church.\" The memory verse for this week."},{"id":2640,"day":49,"category":"acts12","difficulty":"hard","question":"How was Peter sleeping on the night before Herod meant to bring him out?","options":["Chained to the prison wall","Bound with two chains between two soldiers","In the stocks with his feet fastened","Alone in an inner cell"],"correct":1,"reference":"Acts 12:6","explanation":"Two chains, two soldiers, guards at the door - and Peter asleep. The detail makes the escape sharper."},{"id":2641,"day":50,"category":"acts12","difficulty":"medium","question":"What did the angel tell Peter to do after his chains fell off?","options":["Run quickly and do not look back","Gird yourself and tie on your sandals","Say nothing until you are outside","Follow the light to the gate"],"correct":1,"reference":"Acts 12:8","explanation":"\"Gird yourself and tie on your sandals.\" Even in a miracle, Peter has to put his shoes on."},{"id":2642,"day":50,"category":"acts12","difficulty":"hard","question":"What did Peter think was happening as he followed the angel?","options":["That he was dreaming","That he was seeing a vision","That he was being taken to trial","That the guards had released him"],"correct":1,"reference":"Acts 12:9","explanation":"\"Did not know that what was done by the angel was real, but thought he was seeing a vision.\" He does not realise until verse 11."},{"id":2643,"day":50,"category":"acts12","difficulty":"medium","question":"How did the iron gate leading to the city open?","options":["A guard unlocked it","The angel struck it","Of its own accord","It was already standing open"],"correct":2,"reference":"Acts 12:10","explanation":"\"The iron gate that leads to the city, which opened to them of its own accord.\" Past two guard posts, then the gate opens itself."},{"id":2644,"day":50,"category":"acts12","difficulty":"hard","question":"Whose house did Peter go to?","options":["Judas on the street called Straight","Mary, the mother of John whose surname was Mark","Simon the tanner","Lydia the seller of purple"],"correct":1,"reference":"Acts 12:12","explanation":"\"The house of Mary, the mother of John whose surname was Mark\" - the same Mark who goes on the first journey."},{"id":2645,"day":50,"category":"acts12","difficulty":"easy","question":"What was the name of the girl who came to answer the door?","options":["Lydia","Rhoda","Sapphira","Dorcas"],"correct":1,"reference":"Acts 12:13","explanation":"\"A girl named Rhoda came to answer.\" She was so glad she left him knocking outside."},{"id":2646,"day":50,"category":"acts12","difficulty":"hard","question":"What did those praying say when Rhoda insisted Peter was at the gate?","options":["It is his angel","Let her go and see","She is dreaming","It is a spirit"],"correct":0,"reference":"Acts 12:15","explanation":"First \"You are beside yourself!\", then \"It is his angel.\" They were praying for him and could not believe the answer."},{"id":2647,"day":51,"category":"acts12","difficulty":"hard","question":"What did Herod do to the guards when Peter could not be found?","options":["Imprisoned them in Peter's place","Sent them away in disgrace","Commanded that they be put to death","Had them beaten and released"],"correct":2,"reference":"Acts 12:19","explanation":"\"He examined the guards and commanded that they should be put to death.\" Then he went down to Caesarea."},{"id":2648,"day":51,"category":"acts12","difficulty":"hard","question":"Who was Blastus?","options":["A prophet from Jerusalem","A sorcerer at Paphos","The king's personal aide","The captain of the guard"],"correct":2,"reference":"Acts 12:20","explanation":"\"Having made Blastus the king's personal aide their friend.\" One of the small names the exam likes to ask about."},{"id":2649,"day":51,"category":"acts12","difficulty":"medium","question":"What did the people shout at Herod's oration?","options":["He speaks with authority!","The voice of a god and not of a man!","Long live the king!","Great is Herod of Judea!"],"correct":1,"reference":"Acts 12:22","explanation":"\"The voice of a god and not of a man!\" - and Herod did not correct them, which is exactly the point of verse 23."},{"id":2650,"day":51,"category":"acts12","difficulty":"medium","question":"Why did the angel of the Lord strike Herod?","options":["He had lied to the people of Tyre","He did not give glory to God","He had killed James","He had imprisoned Peter"],"correct":1,"reference":"Acts 12:23","explanation":"\"Because he did not give glory to God.\" Then verse 24: \"But the word of God grew and multiplied.\""},{"id":2651,"day":52,"category":"acts13","difficulty":"hard","question":"Who had been brought up with Herod the tetrarch?","options":["Manaen","Barnabas","Lucius of Cyrene","Simeon called Niger"],"correct":0,"reference":"Acts 13:1","explanation":"\"Manaen who had been brought up with Herod the tetrarch.\" Five names at Antioch - Manaen is the one raised alongside a king."},{"id":2652,"day":52,"category":"acts13","difficulty":"medium","question":"What were the prophets and teachers doing when the Holy Spirit spoke?","options":["Teaching the new believers","Travelling towards Cyprus","Distributing relief to the poor","Ministering to the Lord and fasting"],"correct":3,"reference":"Acts 13:2","explanation":"\"As they ministered to the Lord and fasted.\" The first missionary journey starts in a prayer meeting."},{"id":2653,"day":52,"category":"acts13","difficulty":"hard","question":"Which port did Barnabas and Saul go down to before sailing to Cyprus?","options":["Seleucia","Salamis","Paphos","Perga"],"correct":0,"reference":"Acts 13:4","explanation":"Seleucia is the port; Salamis and Paphos are on Cyprus. Easy to mix up - keep the order: Seleucia, Salamis, Paphos."},{"id":2654,"day":52,"category":"acts13","difficulty":"medium","question":"Who went with Barnabas and Saul as their assistant?","options":["Titus","Silas","John","Timothy"],"correct":2,"reference":"Acts 13:5","explanation":"\"They also had John as their assistant\" - John Mark, who leaves them at Perga in verse 13."},{"id":2655,"day":53,"category":"acts13","difficulty":"hard","question":"What was the other name of Bar-Jesus the sorcerer?","options":["Simon","Agabus","Elymas","Blastus"],"correct":2,"reference":"Acts 13:8","explanation":"\"Elymas the sorcerer (for so his name is translated).\" Two names, one man - both are worth knowing."},{"id":2656,"day":53,"category":"acts13","difficulty":"medium","question":"Who was the proconsul at Paphos?","options":["Claudius Lysias","Sergius Paulus","Gallio","Felix"],"correct":1,"reference":"Acts 13:7","explanation":"\"The proconsul, Sergius Paulus, an intelligent man.\" He sent for Barnabas and Saul himself."},{"id":2657,"day":53,"category":"acts13","difficulty":"easy","question":"In which verse is Saul first called Paul?","options":["When he was sent out from Antioch","On the Damascus road","When he confronted Elymas at Paphos","When Ananias baptized him"],"correct":2,"reference":"Acts 13:9","explanation":"\"Then Saul, who also is called Paul.\" Not at his conversion - here, four chapters later, confronting a sorcerer."},{"id":2658,"day":53,"category":"acts13","difficulty":"hard","question":"What happened to Elymas?","options":["He was struck dumb","He fell down and died","A dark mist fell on him and he was blind","He fled the island"],"correct":2,"reference":"Acts 13:11","explanation":"\"Immediately a dark mist fell on him, and he went around seeking someone to lead him by the hand\" - exactly as Saul once had to be led."},{"id":2659,"day":54,"category":"acts13","difficulty":"medium","question":"Where did John leave Paul's party and return to Jerusalem?","options":["Perga in Pamphylia","Antioch in Pisidia","Paphos in Cyprus","Iconium"],"correct":0,"reference":"Acts 13:13","explanation":"\"They came to Perga in Pamphylia; and John, departing from them, returned to Jerusalem.\" This departure causes the argument in Acts 15."},{"id":2660,"day":54,"category":"acts13","difficulty":"hard","question":"How long did God give Israel judges, according to Paul?","options":["About three hundred years","About forty years","About four hundred and fifty years","About four hundred years"],"correct":2,"reference":"Acts 13:20","explanation":"\"About four hundred and fifty years, until Samuel the prophet.\" One of several numbers in Paul's sermon."},{"id":2661,"day":55,"category":"acts13","difficulty":"hard","question":"What did Paul and Barnabas do when they were expelled from the region?","options":["Stayed and preached in secret","Appealed to the proconsul","Returned quietly to Antioch","Shook off the dust from their feet against them"],"correct":3,"reference":"Acts 13:51","explanation":"\"They shook off the dust from their feet against them, and came to Iconium.\" Then verse 52: the disciples were filled with joy."},{"id":2662,"day":55,"category":"acts13","difficulty":"medium","question":"Who did the Jews stir up to raise persecution against Paul and Barnabas?","options":["The Roman garrison","The rulers of the synagogue only","The devout and prominent women and the chief men of the city","The merchants of the market"],"correct":2,"reference":"Acts 13:50","explanation":"\"The devout and prominent women and the chief men of the city.\" Luke names who was stirred up, not just that it happened."},{"id":2663,"day":56,"category":"acts14","difficulty":"medium","question":"In Iconium, who believed when Paul and Barnabas spoke in the synagogue?","options":["A great multitude of both Jews and Greeks","Only the rulers of the synagogue","The women of the city","Only the Greeks"],"correct":0,"reference":"Acts 14:1","explanation":"\"A great multitude both of the Jews and of the Greeks believed.\" Both groups - which is why the city ends up divided."},{"id":2664,"day":56,"category":"acts14","difficulty":"hard","question":"What did the unbelieving Jews do to the Gentiles' minds?","options":["Closed them to the prophets","Poisoned them against the brethren","Turned them to idols","Filled them with fear of Rome"],"correct":1,"reference":"Acts 14:2","explanation":"\"Stirred up the Gentiles and poisoned their minds against the brethren.\" Poisoned - a strong word Luke chooses deliberately."},{"id":2665,"day":56,"category":"acts14","difficulty":"medium","question":"How was the multitude of Iconium divided?","options":["Part with Rome, part with the temple","Part with the priests, part with the rulers","Part with Paul, part with Barnabas","Part with the Jews, part with the apostles"],"correct":3,"reference":"Acts 14:4","explanation":"\"Part sided with the Jews, and part with the apostles.\" A city split down the middle."},{"id":2666,"day":56,"category":"acts14","difficulty":"hard","question":"To which two cities of Lycaonia did Paul and Barnabas flee?","options":["Perga and Attalia","Troas and Philippi","Lystra and Derbe","Iconium and Antioch"],"correct":2,"reference":"Acts 14:6","explanation":"\"Fled to Lystra and Derbe, cities of Lycaonia.\" Keep Lystra and Derbe together - they belong to Lycaonia."},{"id":2667,"day":57,"category":"acts14","difficulty":"medium","question":"What did Paul see in the cripple at Lystra before healing him?","options":["That he was known to the crowd","That he had faith to be healed","That he was a Jew","That he had been praying"],"correct":1,"reference":"Acts 14:9","explanation":"\"Observing him intently and seeing that he had faith to be healed.\" Paul looked intently - the same phrase used of Peter in Acts 3:4."},{"id":2668,"day":57,"category":"acts14","difficulty":"hard","question":"What did Paul say with a loud voice to the cripple?","options":["Stand up straight on your feet!","Arise and make your bed!","In the name of Jesus, be healed!","Rise up and walk!"],"correct":0,"reference":"Acts 14:10","explanation":"\"Stand up straight on your feet!\" Peter said \"rise up and walk\" in Acts 3:6 - the wording here is different."},{"id":2669,"day":57,"category":"acts14","difficulty":"hard","question":"In which language did the people of Lystra shout that the gods had come down?","options":["Hebrew","Lycaonian","Greek","Latin"],"correct":1,"reference":"Acts 14:11","explanation":"\"Saying in the Lycaonian language.\" That is likely why Paul and Barnabas did not realise at once what was happening."},{"id":2670,"day":57,"category":"acts14","difficulty":"medium","question":"Whom did the crowd call Zeus, and whom Hermes?","options":["Barnabas was Hermes; Paul was Apollo","Barnabas was Zeus; Paul was Hermes","Both were called Zeus","Paul was Zeus; Barnabas was Hermes"],"correct":1,"reference":"Acts 14:12","explanation":"Barnabas - Zeus. Paul - Hermes, \"because he was the chief speaker.\" Easy to swap, so fix which is which."},{"id":2671,"day":57,"category":"acts14","difficulty":"hard","question":"What did the priest of Zeus bring to the gates?","options":["Lambs and oil","Oxen and garlands","Gold and incense","Bread and wine"],"correct":1,"reference":"Acts 14:13","explanation":"\"Brought oxen and garlands to the gates, intending to sacrifice.\" Garlands are flower wreaths for the animals."},{"id":2672,"day":57,"category":"acts14","difficulty":"medium","question":"How did Barnabas and Paul react when they heard what the crowd intended?","options":["They withdrew quietly from the city","They accepted the honour and preached","They tore their clothes and ran in among the multitude","They called down blindness on the priest"],"correct":2,"reference":"Acts 14:14","explanation":"Tearing your clothes was a sign of horror. They ran INTO the crowd to stop it."},{"id":2673,"day":58,"category":"acts14","difficulty":"hard","question":"How did Paul say God had not left Himself without witness?","options":["He wrote His law on stone","He sent prophets to every nation","He set signs in the stars","He gave rain from heaven and fruitful seasons"],"correct":3,"reference":"Acts 14:17","explanation":"\"Gave us rain from heaven and fruitful seasons, filling our hearts with food and gladness.\" A sermon to farmers, about rain and harvest."},{"id":2674,"day":58,"category":"acts14","difficulty":"medium","question":"Where did the Jews who stoned Paul at Lystra come from?","options":["Jerusalem and Judea","Damascus and Tarsus","Antioch and Iconium","Derbe and Perga"],"correct":2,"reference":"Acts 14:19","explanation":"\"Then Jews from Antioch and Iconium came there.\" They followed him from the cities he had already left."},{"id":2675,"day":58,"category":"acts14","difficulty":"medium","question":"What happened after Paul was stoned and dragged out of the city?","options":["Barnabas preached in his place","He was carried to Derbe on a stretcher","He rose up and went back into the city","He lay ill for many days"],"correct":2,"reference":"Acts 14:20","explanation":"\"When the disciples gathered around him, he rose up and went into the city.\" Stoned, left for dead, and walks back in."},{"id":2676,"day":58,"category":"acts14","difficulty":"medium","question":"What did Paul and Barnabas say about entering the kingdom of God?","options":["The kingdom is at hand, repent","Only the pure in heart shall enter","We must through many tribulations enter the kingdom of God","Enter by the narrow gate"],"correct":2,"reference":"Acts 14:22","explanation":"\"We must through many tribulations enter the kingdom of God.\" This week's memory verse - said just after Paul was stoned."},{"id":2677,"day":59,"category":"acts14","difficulty":"hard","question":"What did Paul and Barnabas report when they gathered the church at Antioch?","options":["That they had been stoned and survived","That the famine had ended","That God had opened the door of faith to the Gentiles","That the churches had appointed elders"],"correct":2,"reference":"Acts 14:27","explanation":"\"He had opened the door of faith to the Gentiles.\" The door - that image sets up the whole argument of chapter 15."},{"id":2678,"day":60,"category":"acts15","difficulty":"medium","question":"What did the men from Judea teach the brethren?","options":["Unless you keep the Sabbath, you cannot be saved","Unless you give alms, you cannot be saved","Unless you are baptized in Jerusalem, you cannot be saved","Unless you are circumcised according to the custom of Moses, you cannot be saved"],"correct":3,"reference":"Acts 15:1","explanation":"This is the question the whole council exists to answer - is circumcision required to be saved?"},{"id":2679,"day":60,"category":"acts15","difficulty":"hard","question":"Through which regions did Paul and Barnabas pass on their way to Jerusalem?","options":["Pisidia and Pamphylia","Phoenicia and Samaria","Galatia and Phrygia","Syria and Cilicia"],"correct":1,"reference":"Acts 15:3","explanation":"\"They passed through Phoenicia and Samaria, describing the conversion of the Gentiles.\" And they caused great joy on the way."},{"id":2680,"day":60,"category":"acts15","difficulty":"hard","question":"Which sect of believers rose up demanding circumcision and the law of Moses?","options":["The Pharisees","The Hellenists","The Sadducees","The Essenes"],"correct":0,"reference":"Acts 15:5","explanation":"\"Some of the sect of the Pharisees who believed.\" Believing Pharisees - they had come to faith but kept the old requirement."},{"id":2681,"day":61,"category":"acts15","difficulty":"medium","question":"What did Peter say God did to purify the Gentiles' hearts?","options":["Washed them in baptism","Sent them prophets","Purified their hearts by faith","Gave them the law to keep"],"correct":2,"reference":"Acts 15:9","explanation":"\"Made no distinction between us and them, purifying their hearts by faith.\" No distinction - that is Peter's whole argument."},{"id":2682,"day":61,"category":"acts15","difficulty":"hard","question":"What did Peter call the demand being placed on the disciples?","options":["A snare set by the enemy","A yoke which neither our fathers nor we were able to bear","A stumbling block before the blind","A burden too heavy for the Gentiles"],"correct":1,"reference":"Acts 15:10","explanation":"\"A yoke on the neck of the disciples which neither our fathers nor we were able to bear.\" Peter includes himself in the failure."},{"id":2683,"day":61,"category":"acts15","difficulty":"medium","question":"Who spoke after Barnabas and Paul had finished at the council?","options":["Peter","James","Silas","Judas Barsabas"],"correct":1,"reference":"Acts 15:13","explanation":"\"After they had become silent, James answered.\" Peter first, then Barnabas and Paul, then James gives the judgement."},{"id":2684,"day":61,"category":"acts15","difficulty":"hard","question":"Which prophet's words did James quote about rebuilding the tabernacle of David?","options":["Isaiah, on the suffering servant","Joel, on the outpouring of the Spirit","Moses, on the coming Prophet","The prophets, quoting the rebuilding of David's fallen tabernacle"],"correct":3,"reference":"Acts 15:16","explanation":"\"I will rebuild the tabernacle of David, which has fallen down.\" James points to the prophets agreeing with what God has done."},{"id":2685,"day":62,"category":"acts15","difficulty":"hard","question":"What four things did James say the Gentiles should abstain from?","options":["Idols, images, feasts, and fasting","Things polluted by idols, sexual immorality, things strangled, and blood","Blood, oaths, idols, and the temple tax","Idols, the Sabbath, unclean meat, and wine"],"correct":1,"reference":"Acts 15:20","explanation":"Four things - idols, immorality, strangled things, blood. The same four appear again in the letter at verse 29."},{"id":2686,"day":62,"category":"acts15","difficulty":"medium","question":"Which two leading men were sent to Antioch with Paul and Barnabas?","options":["John Mark and Luke","Timothy and Titus","Agabus and Manaen","Judas called Barsabas, and Silas"],"correct":3,"reference":"Acts 15:22","explanation":"\"Judas who was also named Barsabas, and Silas, leading men among the brethren.\" Silas becomes Paul's next travelling companion."},{"id":2687,"day":62,"category":"acts15","difficulty":"hard","question":"To whom was the letter from the council addressed?","options":["All the churches of Asia","The elders at Jerusalem","The churches of Judea and Galilee","The brethren who are of the Gentiles in Antioch, Syria, and Cilicia"],"correct":3,"reference":"Acts 15:23","explanation":"Antioch, Syria, Cilicia - three regions named in the address."},{"id":2688,"day":62,"category":"acts15","difficulty":"medium","question":"How did the council describe their decision in the letter?","options":["It seemed good to the Holy Spirit, and to us","We have judged after much fasting","The law of Moses requires it","It is the command of the apostles"],"correct":0,"reference":"Acts 15:28","explanation":"\"It seemed good to the Holy Spirit, and to us.\" They name the Spirit first, themselves second."},{"id":2689,"day":63,"category":"acts15","difficulty":"medium","question":"Why did Paul refuse to take John Mark on the second journey?","options":["He had departed from them in Pamphylia and not gone on to the work","He was needed in Jerusalem","He was too young to travel","He had denied the faith"],"correct":0,"reference":"Acts 15:38","explanation":"Mark left them at Perga in Acts 13:13. Paul remembered; Barnabas was willing to try again."},{"id":2690,"day":63,"category":"acts15","difficulty":"medium","question":"Who went with Barnabas, and where did they sail?","options":["Mark, and they sailed to Cyprus","Judas, and they sailed to Antioch","Timothy, and they sailed to Troas","Silas, and they sailed to Cilicia"],"correct":0,"reference":"Acts 15:39","explanation":"\"Barnabas took Mark and sailed to Cyprus\" - Barnabas's own island. Paul took Silas through Syria and Cilicia."},{"id":2691,"day":64,"category":"acts16","difficulty":"medium","question":"What were Timothy's parents?","options":["A Jewish mother who believed, and a Greek father","Both were Greek converts","Both were Jewish believers","A Greek mother and a Jewish father"],"correct":0,"reference":"Acts 16:1","explanation":"\"The son of a certain Jewish woman who believed, but his father was Greek.\" The exam asks this one often."},{"id":2692,"day":64,"category":"acts16","difficulty":"hard","question":"In which towns was Timothy well spoken of?","options":["Antioch and Tarsus","Troas and Philippi","Derbe and Perga","Lystra and Iconium"],"correct":3,"reference":"Acts 16:2","explanation":"\"Well spoken of by the brethren who were at Lystra and Iconium.\" His reputation reached beyond his own town."},{"id":2693,"day":64,"category":"acts16","difficulty":"hard","question":"Where were Paul and his companions forbidden by the Holy Spirit to preach?","options":["Asia","Macedonia","Galatia","Achaia"],"correct":0,"reference":"Acts 16:6","explanation":"Forbidden in Asia, not permitted into Bithynia - two closed doors before the vision opens a third."},{"id":2694,"day":64,"category":"acts16","difficulty":"hard","question":"Which region did the Spirit not permit them to enter after Mysia?","options":["Bithynia","Phrygia","Cilicia","Pamphylia"],"correct":0,"reference":"Acts 16:7","explanation":"\"They tried to go into Bithynia, but the Spirit did not permit them.\" Then they came down to Troas."},{"id":2695,"day":64,"category":"acts16","difficulty":"medium","question":"What did the man in Paul's night vision say?","options":["Do not be afraid, but speak","Go and preach in Asia","Come over to Macedonia and help us","Return to Jerusalem quickly"],"correct":2,"reference":"Acts 16:9","explanation":"\"A man of Macedonia stood and pleaded with him.\" That vision is how the gospel crossed into Europe."},{"id":2696,"day":65,"category":"acts16","difficulty":"hard","question":"How is Philippi described?","options":["The capital of all Greece","A fishing village on the coast","The foremost city of that part of Macedonia, a colony","A free city of Asia"],"correct":2,"reference":"Acts 16:12","explanation":"\"The foremost city of that part of Macedonia, a colony.\" A Roman colony - which matters when Paul claims his rights in verse 37."},{"id":2697,"day":65,"category":"acts16","difficulty":"medium","question":"Where did Paul and his companions find the women praying?","options":["By the riverside outside the city","In the synagogue","In the marketplace","At the city gate"],"correct":0,"reference":"Acts 16:13","explanation":"\"We went out of the city to the riverside, where prayer was customarily made.\" No synagogue in Philippi - so they went to the river."},{"id":2698,"day":65,"category":"acts16","difficulty":"easy","question":"What was Lydia's trade, and which city was she from?","options":["A merchant of spices, from Philippi","A seller of purple, from Thyatira","A maker of tents, from Tarsus","A weaver of linen, from Troas"],"correct":1,"reference":"Acts 16:14","explanation":"\"A seller of purple from the city of Thyatira.\" Purple cloth was expensive - Lydia was a businesswoman."},{"id":2699,"day":65,"category":"acts16","difficulty":"hard","question":"What did the Lord do for Lydia?","options":["Opened her heart to heed the things spoken by Paul","Gave her a vision in the night","Sent an angel to her house","Healed her of a long sickness"],"correct":0,"reference":"Acts 16:14","explanation":"\"The Lord opened her heart to heed the things spoken by Paul.\" He opened her heart before Paul opened his mouth."},{"id":2700,"day":66,"category":"acts16","difficulty":"hard","question":"What did the slave girl with a spirit of divination bring her masters?","options":["Protection from thieves","Favour with the magistrates","Fame throughout Macedonia","Much profit by fortune-telling"],"correct":3,"reference":"Acts 16:16","explanation":"\"Who brought her masters much profit by fortune-telling.\" The profit is why they were furious when it stopped."},{"id":2701,"day":66,"category":"acts16","difficulty":"medium","question":"What did the slave girl keep crying out about Paul and his companions?","options":["These men are the servants of the Most High God","These men are gods come down","These men are enemies of the city","These men are Romans"],"correct":0,"reference":"Acts 16:17","explanation":"What she said was true - and Paul still silenced it. Verse 18 says he was greatly annoyed, after many days."},{"id":2702,"day":66,"category":"acts16","difficulty":"hard","question":"Where did the jailer put Paul and Silas, and what did he do to their feet?","options":["The inner prison, and fastened their feet in the stocks","The outer court, and bound them with chains","The dungeon, and shackled their hands","A cell by the gate, and tied them with cords"],"correct":0,"reference":"Acts 16:24","explanation":"Inner prison, feet in the stocks. That is where the midnight singing happens."},{"id":2703,"day":66,"category":"acts16","difficulty":"medium","question":"What were Paul and Silas doing at midnight?","options":["Planning their escape","Arguing with the jailer","Praying and singing hymns to God","Sleeping soundly"],"correct":2,"reference":"Acts 16:25","explanation":"\"Praying and singing hymns to God, and the prisoners were listening to them.\" The other prisoners were listening - that detail matters."},{"id":2704,"day":66,"category":"acts16","difficulty":"hard","question":"What happened to the doors and chains in the earthquake?","options":["Only Paul and Silas were freed","All the doors were opened and everyone's chains were loosed","The doors held but the stocks broke","The outer gate fell and the walls cracked"],"correct":1,"reference":"Acts 16:26","explanation":"ALL the doors, EVERYONE'S chains - not just theirs. Which is why nobody ran, and the jailer lived."},{"id":2705,"day":66,"category":"acts16","difficulty":"hard","question":"Why did Paul refuse to leave the prison quietly?","options":["They had beaten uncondemned Romans openly","He was waiting for Lydia","The jailer had not yet been baptized","He wanted to preach to the prisoners first"],"correct":0,"reference":"Acts 16:37","explanation":"\"They have beaten us openly, uncondemned Romans... Let them come themselves and get us out.\" Being a Roman citizen made the beating illegal."}];
